insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2005-maj-kozep-L2$mtr$, $mtr$2005-maj-kozep$mtr$, $mtr$language$mtr$, 2, $mtr$bank$mtr$, $mtr$szóbank (szavak visszahelyezése)$mtr$, 10, 6, $mtr${"id":"2005-maj-kozep-L2","number":2,"kind":"bank","layout":"inline","examType":"szóbank (szavak visszahelyezése)","points":10,"instructions":["You are going to read a humorous story about an old couple. Some words are missing from the text.","Your task is to choose the most appropriate word from the list (A-L) for each gap (7-16) in the text. Write the letter of the appropriate word in the white box.","There is one extra word that you do not need to use."],"title":"OLD STYLE","body":["An 80-year-old couple were having problems remembering things, so they decided to see their family doctor to make sure {{0}} was wrong with them. When they arrived at the doctor’s, they {{7}} to him that they were having problems with their memory. The doctor told them they were physically fit but they {{8}} start writing things down and making {{9}} to help them remember things. The couple thanked the doctor and left.","Later that night {{10}} watching TV, the old man got up from his chair. His wife asked him, “Where are you going?” He replied, “To the kitchen.” She asked him, “Will you {{11}} me a bowl of ice cream?” He replied, “Sure.” Then she asked him, “Don’t you think you should write it down?” He said, “No, I can remember that.” Then the woman said, “Well, I would {{12}} like some strawberries on top. You had better write that down because I know you’ll forget it.” With {{13}} in his voice the old man said, “I don’t {{14}} to write that down. I can remember that you want a bowl of ice cream with strawberries on top.” He went into the kitchen {{15}}. After about 20 minutes he {{16}} and handed her a plate of bacon and eggs. She stared at the plate for a moment and said, “I told you to write it down. You forgot my toast.”"],"bank":[{"key":"A","text":"also"},{"key":"B","text":"angrily"},{"key":"C","text":"bring"},{"key":"D","text":"explained"},{"key":"E","text":"irritation"},{"key":"F","text":"need"},{"key":"G","text":"notes"},{"key":"H","text":"nothing"},{"key":"I","text":"returned"},{"key":"J","text":"should"},{"key":"K","text":"take"},{"key":"L","text":"while"}],"items":[{"n":0,"example":true,"answer":"H"},{"n":7},{"n":8},{"n":9},{"n":10},{"n":11},{"n":12},{"n":13},{"n":14},{"n":15},{"n":16}]}$mtr$::jsonb, null)
