need"},{"key":"G","text":"notes"},{"key":"H","text":"nothing"},{"key":"I","text":"returned"},{"key":"J","text":"should"},{"key":"K","text":"take"},{"key":"L","text":"while"}],"items":[{"n":0,"example":true,"answer":"H"},{"n":7,"answer":"D"},{"n":8,"answer":"J"},{"n":9,"answer":"G"},{"n":10,"answer":"L"},{"n":11,"answer":"C"},{"n":12,"answer":"A"},{"n":13,"answer":"E"},{"n":14,"answer":"F"},{"n":15,"answer":"B"},{"n":16,"answer":"I"}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2005-maj-kozep-L3$mtr$, $mtr$2005-maj-kozep$mtr$, $mtr$language$mtr$, 3, $mtr$text$mtr$, $mtr$nyílt cloze (egy szó)$mtr$, 9, 7, $mtr${"id":"2005-maj-kozep-L3","number":3,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":9,"instructions":["You are going to read a text about a sightseeing tour. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (17-25) after the text.","Use only one word in each gap."],"title":"THE OPEN-TOP BUS TOUR","body":["Explore the world’s most cosmopolitan city with London’s oldest sightseeing company using open-top double-decker buses. With half a century’s experience we like to think that we have got {{0}} right. And we are sure you’ll enjoy your time {{17}} us. Here is why: ¾ Our tour routes are the most comprehensive way to see {{18}} best London has to offer including the panoramic views {{19}} seven bridges, the Tower of London, Buckingham Palace, St. Paul’s Cathedral, Westminster Abbey, Trafalgar Square… ¾ There {{20}} a full commentary in English and a choice of six other languages. ¾ Unlike some other companies, your tickets {{21}} completely unrestricted. You can travel on any of our tour buses. Each route includes frequent stops – simply hop off {{22}} you want to and return to the same stop to continue your tour. ¾ We strongly recommend that first timers start the tour at one of {{23}} main departure points where our staff can provide advice about traffic conditions and final departure times. You may then choose {{24}} stay on the bus for a complete tour or hop on and hop off at your leisure. ¾ Tickets are valid {{25}} the same time the following day. Ask our staff when you should board your last bus of the day as times vary seasonally throughout the year."],"grading":{"spelling":"strict"},"items":[{"n":0,"example":true,"accept":["it"]},{"n":17},{"n":18},{"n":19},{"n":20},{"n":21},{"n":22},{"n":23},{"n":24},{"n":25}]}$mtr$::jsonb, null)
