cept":["valuable"]},{"n":21,"prompt":"danger","accept":["endangered"]},{"n":22,"prompt":"sell","accept":["sale","selling","sales"]},{"n":23,"prompt":"find","accept":["findings"]},{"n":24,"prompt":"economy","accept":["economic"]},{"n":25,"prompt":"profit","accept":["profitable"]},{"n":26,"prompt":"produce","accept":["products"]},{"n":27,"prompt":"attract","accept":["attraction"]}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
