insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2005-nov-emelt-L4$mtr$, $mtr$2005-nov-emelt$mtr$, $mtr$language$mtr$, 4, $mtr$lines$mtr$, $mtr$soronkénti hibakeresés (felesleges szó vagy helyes sor)$mtr$, 9, 8, $mtr${"id":"2005-nov-emelt-L4","number":4,"kind":"lines","layout":"lines","examType":"soronkénti hibakeresés (felesleges szó vagy helyes sor)","points":9,"instructions":["You are going to read an article about special driving courses. In most lines there is one word that should not be there. It is either grammatically incorrect or does not fit in with the sense of the text.","Read the text and then copy the extra word in the space provided after each line.","Some lines are correct. Indicate these lines with a tick (9).","The task begins with two examples (0)."],"title":"SPEEDERS TO BE SENT FOR LESSONS IN SAFE DRIVING","intro":"","items":[{"n":"0a","example":true,"text":"Speeding motorists are to be sent back to driving school as for an","answer":"for"},{"n":"0b","example":true,"text":"alternative to gaining points on their license.","answer":null},{"n":32,"text":"A national team is used to be set up within weeks following the"},{"n":33,"text":"success of six pilot courses were run by the police."},{"n":34,"text":"Its aim is how to improve the driving of those caught fractionally"},{"n":35,"text":"over the speed limit who have relatively clean licenses."},{"n":36,"text":"They will have to pay a £60 fine and at the cost of the"},{"n":37,"text":"specially-tailored speed awareness course."},{"n":38,"text":"Lessons will include the using driving simulators to improve"},{"n":39,"text":"drivers’ ability to spot hazards and judge speed. Drivers will also be"},{"n":40,"text":"forced not to confront the potentially fatal consequences of going"}],"outro":"too fast."}$mtr$::jsonb, null)
