insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2005-nov-emelt-H2$mtr$, $mtr$2005-nov-emelt$mtr$, $mtr$listening$mtr$, 2, $mtr$text$mtr$, $mtr$rövid válasz hallás után$mtr$, 10, 10, $mtr${"id":"2005-nov-emelt-H2","number":2,"kind":"text","layout":"stems","examType":"rövid válasz hallás után","points":10,"instructions":["In this section you are going to hear an interview about fatness in the U.S.","Your task is to complete the answers to the questions below.","First, you will have some time to study the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers.","At the end, you will have some more time to check your work."],"audio":{"file":"e_angol_05nov_fl.mp3","start":631.32,"end":1221.36,"clip":"hang/e_angol_05nov_fl_H2.mp3"},"items":[{"n":0,"example":true,"stem":"How has the number of overweight Americans changed in the past decade? There are {{gap}} {{gap}} obese people today than there were a decade ago.","accept":["50% more"]},{"n":8,"stem":"What is wrong with 44 million people in the U.S.? They are {{gap}} over the healthy weight for their height."},{"n":9,"stem":"What is the annual cost of all this? It is more than {{gap}} every year."},{"n":10,"stem":"Who is Dr Richard Carmona? He is the {{gap}} of the U.S.A."},{"n":11,"stem":"What statistical figures does Dr Carmona provide to illustrate that American society has become more sedentary? The average child is watching TV or playing video games {{gap}} a day."},{"n":12,"stem":"In what respect does he hold schools responsible for the present situation? A lot of schools have eliminated {{gap}} from their curriculum."},{"n":13,"stem":"How many kids are considered to be overweight in the U.S. today? {{gap}} children."},{"n":14,"stem":"Who does he say might be in a position to “break the cycle”? (Name any four of these circles.) {{gap}}, {{gap}}, {{gap}}, {{gap}}"},{"n":15,"stem":"What kind of substances have been used by some food manufacturers “to give us a taste for unhealthy diets” according to some critics? They have added {{gap}}, {{gap}} and {{gap}} to their products."},{"n":16,"stem":"What is the aim of the “goodwill campaign” initiated by Dr Carmona? The main aim is to reduce the {{gap}} in foodstuffs."},{"n":17,"stem":"In what areas have fast food companies shown signs of improvement recently? They have revised their {{gap}} and put healthier foods on their {{gap}}."}],"grading":{"spelling":"keywords"}}$mtr$::jsonb, $mtr${"file":"e_angol_05nov_fl.mp3","start":631.32,"end":1221.36,"clip":"hang/e_angol_05nov_fl_H2.mp3"}$mtr$::jsonb)
insert into public.task_keys (task_id, task) values ($mtr$2005-nov-emelt-H2$mtr$, $mtr${"id":"2005-nov-emelt-H2","number":2,"kind":"text","layout":"stems","examType":"rövid válasz hallás után","points":10,"instructions":["In this section you are going to hear an interview about fatness in the U.S.","Your task is to complete the answers to the questions below.","First, you will have some time to study the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers.","At the end, you will have some more time to check your work."],"audio":{"file":"e_angol_05nov_fl.mp3","start":631.32,"end":1221.36,"clip":"hang/e_angol_05nov_fl_H2.mp3"},"items":[{"n":0,"example":true,"stem":"How has the number of overweight Americans changed in the past decade? There are {{gap}} {{gap}} obese people today than there were a decade ago.","accept":["50% more"]},{"n":8,"stem":"What is wrong with 44 million people in the U.S.? They are {{gap}} over the healthy weight for their height.","key":"30/thirty pounds","keywords":[["30","pounds"],["thirty","pounds"]]},{"n":9,"stem":"What is the annual cost of all this? It is more than {{gap}} every year.","key":"120/one hundred and twenty billion dollars/$120 billion","keywords":[["120","billion","dollars"],["one","hundred","twenty","billion","dollars"]]},{"n":10,"stem":"Who is Dr Richard Carmona? He is the {{gap}} of the U.S.A.","key":"Surgeon General","keywords":[["surgeon","general"]]},{"n":11,"stem":"What statistical figures does Dr Carmona provide to illustrate that American society has become more sedentary? The average child is watching TV or playing video games {{gap}} a day.","key":"more than 4/four hours","keywords":[["more","than","4","hours"],["more","than","four","hours"]]},{"n":12,"stem":"In what respect does he hold schools responsible for the present situation? A lot of schools have eliminated {{gap}} from their curriculum.","key":"physical activity","keywords":[["physical","activity"]]},{"n":13,"stem":"How many kids are considered to be overweight in the U.S. today? {{gap}} children.","key":"9/nine million","keywords":[["9","million"],["nine","million"]]},{"n":14,"stem":"Who does he say might be in a position to “break the cycle”? (Name any four of these circles.) {{gap}}, {{gap}}, {{gap}}, {{gap}}","key":"schools, churches, parents, extended families, baseball teams, extracurricular activities (Csak akkor elfogadható, ha bármelyik négy helyes közülük, viszont a sorrend nem számít!)","keywords":[["schools","churches","parents","extended","families"],["schools","churches","parents","baseball","teams"],["schools","churches","parents","extracurricular","activities"],["schools","churches","extended","families","baseball","teams"],["schools","churches","extended","families","extracurricular","activities"],["schools","churches","baseball","teams","extracurricular","activities"],["schools","parents","extended","families","baseball","teams"],["schools","parents","extended","families","extracurricular","activities"],["schools","parents","baseball","teams","extracurricular","activities"],["schools","extended","families","baseball","teams","extracurricular","activities"],["churches","parents","extended","families","baseball","teams"],["churches","parents","extended","families","extracurricular","activities"],["churches","parents","baseball","teams","extracurricular","activities"],["churches","extended","families","baseball","teams","extracurricular","activities"],["parents","extended","families","baseball","teams","extracurricular","activities"]]},{"n":15,"stem":"What kind of substances have been used by some food manufacturers “to give us a taste for unhealthy diets” according to some critics? They have added {{gap}}, {{gap}} and {{gap}} to their products.","key":"sugar, fat, salt (Csak akkor elfogadható, ha mind a három helyes, viszo