insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2005-nov-emelt-H3$mtr$, $mtr$2005-nov-emelt$mtr$, $mtr$listening$mtr$, 3, $mtr$text$mtr$, $mtr$mondatkiegészítés hallás után (két szó)$mtr$, 13, 11, $mtr${"id":"2005-nov-emelt-H3","number":3,"kind":"text","layout":"inline","examType":"mondatkiegészítés hallás után (két szó)","points":13,"instructions":["In this section you are going to hear three short news reports.","Your task is to fill in the gaps in the sentences below with one or two words.","First, you will have some time to study the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers.","At the end, you will have some more time to check your work."],"audio":{"file":"e_angol_05nov_fl.mp3","start":1221.36,"end":1800.37,"clip":"hang/e_angol_05nov_fl_H3.mp3"},"body":["New research suggests that penalty shoot-outs in crucial football matches can seriously {{0}} the health of fans. The study claims that the number of {{18}} rose by 25% when England lost to Argentina in a penalty competition in the World Cup of 1998. The findings back up the theory that such fatalities can be triggered by {{19}}. The authors believe that these exciting games generate considerable stress amongst fans, which can make their blood thicken and become more sticky and their {{20}} increase, which can be fatal in some cases. Researchers recommend that people at risk should be told how to {{21}} during matches, and they even suggest that the ”lottery” of penalty shoot-out should perhaps be {{22}} on the grounds of public health.","The second report tells us that that mobile telephone companies have been deluged by enquiries from the police about calls by {{23}}. As many as half a million requests are made each year, because mobile phone {{24}} has played a key role in a number of recent {{25}}, as it did in the case of a man who was convicted of murder yesterday. Information on where and when a call is made by a suspect can be used by police to link them to a crime scene or a {{26}}. The number of enquiries has risen so sharply that mobile phone companies have begun charging a {{27}} for every request.","The third report is about a bitter {{28}} over Sir Paul McCartney’s latest {{29}}. The singer is listing 19 old Lennon- McCartney Beatles tracks as written by Paul McCartney and John Lennon, claiming that these songs were, in effect, written by him. John Lennon’s widow, Yoko Ono is furious and has called in the {{30}}."],"grading":{"spelling":"lenient"},"items":[{"n":0,"example":true,"accept":["endanger"]},{"n":18},{"n":19},{"n":20},{"n":21},{"n":22},{"n":23},{"n":24},{"n":25},{"n":26},{"n":27},{"n":28},{"n":29},{"n":30}]}$mtr$::jsonb, $mtr${"file":"e_angol_05nov_fl.mp3","start":1221.36,"end":1800.37,"clip":"hang/e_angol_05nov_fl_H3.mp3"}$mtr$::jsonb)
insert into public.task_keys (task_id, task) values ($mtr$2005-nov-emelt-H3$mtr$, $mtr${"id":"2005-nov-emelt-H3","number":3,"kind":"text","layout":"inline","examType":"mondatkiegészítés hallás után (két szó)","points":13,"instructions":["In this section you are going to hear three short news reports.","Your task is to fill in the gaps in the sentences below with one or two words.","First, you will have some time to study the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers.","At the end, you will have some more time to check your work."],"audio":{"file":"e_angol_05nov_fl.mp3","start":1221.36,"end":1800.37,"clip":"hang/e_angol_05nov_fl_H3.mp3"},"body":["New research suggests that penalty shoot-outs in crucial football matches can seriously {{0}} the health of fans. The study claims that the number of {{18}} rose by 25% when England lost to Argentina in a penalty competition in the World Cup of 1998. The findings back up the theory that such fatalities can be triggered by {{19}}. The authors believe that these exciting games generate considerable stress amongst fans, which can make their blood thicken and become more sticky and their {{20}} increase, which can be fatal in some cases. Researchers recommend that people at risk should be told how to {{21}} during matches, and they even suggest that the ”lottery” of penalty shoot-out should perhaps be {{22}} on the grounds of public health.","The second report tells us that that mobile telephone companies have been deluged by enquiries from the police about calls by {{23}}. As many as half a million requests are made each year, because mobile phone {{24}} has played a key role in a number of recent {{25}}, as it did in the case of a man who was convicted of murder yesterday. Information on where and when a call is made by a suspect can be used by police to link them to a crime scene or a {{26}}. The number of enquiries has risen so sharply that mobile phone companies have begun charging a {{27}} for every request.","The third report is about a bitter {{28}} over Sir Paul McCartney’s latest {{29}}. The singer is listing 19 old Lennon- McCartney Beatles tracks as written by Paul McCartney and John Lennon, claiming that these songs were, in effect, written by him. John Lennon’s widow, Yoko Ono is furious and has called in the {{30}}."],"grading":{"spelling":"lenient","caseSensitive":false,"note":"A második és a harmadik feladatnál a javítás fő szempontja az, hogy a tanuló ki tudja- e emelni a szövegből a kérdezett információt vagy sem. Ezért a megoldások elbírálásánál általában ragaszkodnunk kell azokhoz a jelentésekhez, amelyeket szövegben elhangzott szavak hordoznak. Ennek megfelelően például még elfogadhatjuk a választ, ha a szó szerinti legal row helyett legal argument vagy album helyett record vagy CD szerepel a megoldásban (ezek szinte szinonímák), de nem felel meg például az abandoned helyett (a már határozottan más jelentésű) *banned vagy a more than 4 hours helyett egyszerűen az, hogy *4 hours. Fontos azonban, hogy mindkét feladatnál – mivel mondatkiegészítésről van szó – csak olyan megoldásokat fogadhatunk el, amelyek hibátlanul illeszkednek a megadott mondatokba. Ennek megfelelően például a 21. itemnél ragaszkodnunk kell a keep//stay calm alakhoz (a *calm önmagában nem lenne jó), a 22. itemnél az abandoned alakhoz (az *abandon nem lenne jó). Az egyetlen engedményt itt a többes szám elmaradásának tolerálásával tehetjük – mintegy úgy felfogva a hibát, mintha helyesírási hiba lenne. Így például elfogadhatjuk a guidelines helyett a guideline vagy a lawyers helyett a lawyer alakokat is. Azoknál az itemeknél, ahol a kért információ jellege és/vagy a feladatlap tipográfiája két vagy több szó beírását követeli meg, csak a teljes megoldás fogadható el. Így nem tekinthetjük helyesnek a harmadik feladatban azt, ha a kért (és a feladatlapon tipográfiailag is jelölt) suspected criminals helyett csak *criminals, criminal investigations helyett *investigations vagy legal row helyett csak *row szerepel a megoldásban. Bár a második feladat esetében ezt a feladatlap külön nem jelöli, értelmileg hiányos, és ezért nem elfogadható például a Surgeon General helyett a *Surgeon, a physical activity helyett az *activity, a 9 million helyett a *9, a 30 pounds helyett a *30 vagy a 120 billion dollars helyett a *120 vagy a *120 billion megoldás."},"items":[{"n":0,"example":true,"accept":["endanger"]},{"n":18,"accept":["heart attacks"]},{"n":19,"accept":["emotional upset"]},{"n":20,"accept":["blood pressure"]},{"n":21,"accept":["keep calm","stay calm"]},{"n":22,"accept":["abandoned"]},{"n":23,"accept":["suspected criminals"]},{"n":24,"accept":["evidence"]},{"n":25,"accept":["criminal investigations"]},{"n":26,"accept":["victim"]},{"n":27,"accept":["fee"]},{"n":28,"accept":["legal row","legal argument","argument","quarrel","battle","legal quarrel","legal battle"]},{"n":29,"accept":["album","record","CD"]},{"n":30,"accept":["lawyers"]}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
