insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2006-febr-kozep-H3$mtr$, $mtr$2006-febr-kozep$mtr$, $mtr$listening$mtr$, 3, $mtr$text$mtr$, $mtr$mondatkiegészítés hallás után$mtr$, 7, 9, $mtr${"id":"2006-febr-kozep-H3","number":3,"kind":"text","layout":"stems","examType":"mondatkiegészítés hallás után","points":7,"instructions":["In this section you are going to hear a joke about the best beers in the world.","Your task will be to fill in the gaps in the answers.","First, you will have some time to study the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers.","At the end, you will have some more time to check your work."],"audio":{"file":"k_angol_06febr_fl.mp3","start":1314.3,"end":1800,"clip":"hang/k_angol_06febr_fl_H3.mp3"},"items":[{"n":0,"example":true,"stem":"What product of theirs are the Scottish proud of? They are proud of their {{gap}}.","accept":["whisky"]},{"n":19,"stem":"Where was the international beer festival held? It was held in {{gap}}."},{"n":20,"stem":"Where did the four presidents go out after the festival? They went out to a {{gap}}."},{"n":21,"stem":"What did the Spaniard say about the beer Corona? He said that it was the {{gap}}."},{"n":22,"stem":"What did the American president say about the beer Budweiser? He said that it was the {{gap}}."},{"n":23,"stem":"What did the Belgian president say about the beer Amstel? He said that it was the only beer made with real mountain {{gap}}."},{"n":24,"stem":"What did the Irish president order? He ordered a {{gap}}."},{"n":25,"stem":"What was the Irish president’s opinion about Corona, Budweiser and Amstel? His opinion was that these drinks aren’t {{gap}}."}],"grading":{"spelling":"lenient"}}$mtr$::jsonb, $mtr${"file":"k_angol_06febr_fl.mp3","start":1314