insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2006-maj-kozep-L3$mtr$, $mtr$2006-maj-kozep$mtr$, $mtr$language$mtr$, 3, $mtr$text$mtr$, $mtr$szóképzés (zárójeles szó)$mtr$, 9, 7, $mtr${"id":"2006-maj-kozep-L3","number":3,"kind":"text","layout":"inline","examType":"szóképzés (zárójeles szó)","points":9,"instructions":["You are going to read an article about the Mona Lisa. Some words are missing from the text.","Use the words in brackets to form the words that fit in the gaps (17-25).","Then write these words on the dotted lines after the text in the appropriate form.","There might be cases where you do not have to change the word in brackets.","Write only one word in each space."],"title":"THE MONA LISA","body":["The Mona Lisa was one of Leonardo's {{0}} paintings, and he carried it with him until his {{17}}. Today, it is regarded as the most {{18}} painting in the world, and is {{19}} by many thousands of people every year.","Whose is this {{20}} face? Throughout the centuries many {{21}} have been made, but the most likely candidate is Lisa Gherardini, the wife of a Florentine silk merchant.","Another more unlikely - but popular - theory is that the painting was a self portrait. There are {{22}} similarities between the {{23}} of the Mona Lisa and that of the artist's self portrait painted many years later. Could this be why Leonardo gave the subject such a mysterious smile?","Today, the Mona Lisa looks rather dull, in dark shades of brown and yellow. {{24}} this is due to a special layer covering the paint, which has yellowed over the years. It is possible that the painting was once brighter and more {{25}} than it is now.","The Mona Lisa was stolen from the Louvre in 1911. The thief was caught by the police two years later, and the painting was safely returned."],"grading":{"spelling":"strict"},"items":[{"n":0,"prompt":"favour","example":true,"accept":["favourite"]},{"n":17,"prompt":"die"},{"n":18,"prompt":"fame"},{"n":19,"prompt":"visit"},{"n":20,"prompt":"please"},{"n":21,"prompt":"suggest"},{"n":22,"prompt":"certain"},{"n":23,"prompt":"express"},{"n":24,"prompt":"probable"},{"n":25,"prompt":"colour"}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2006-maj-kozep-L3$mtr$, $mtr${"id":"2006-maj-kozep-L3","number":3,"kind":"text","layout":"inline","examType":"szóképzés (zárójeles szó)","points":9,"instructions":["You are going to read an article about the Mona Lisa. Some words are missing from the text.","Use the words in brackets to form the words that fit in the gaps (17-25).","Then write these words on the dotted lines after the text in the appropriate form.","There might be cases where you do not have to change the word in brackets.","Write only one word in each space."],"title":"THE MONA LISA","body":["The Mona Lisa was one of Leonardo's {{0}} paintings, and he carried it with him until his {{17}}. Today, it is regarded as the most {{18}} painting in the world, and is {{19}} by many thousands of people every year.","Whose is this {{20}} face? Throughout the centuries many {{21}} have been made, but the most likely candidate is Lisa Gherardini, the wife of a Florentine silk merchant.","Another more unlikely - but popular - theory is that the painting was a self portrait. There are {{22}} similarities between the {{23}} of the Mona Lisa and that of the artist's self portrait painted many years later. Could this be why Leonardo gave the subject such a mysterious smile?","Today, the Mona Lisa looks rather dull, in dark shades of brown and yellow. {{24}} this is due to a special layer covering the paint, which has yellowed over the years. It is possible that the painting was once brighter and more {{25}} than it is now.","The Mona Lisa was stolen from the Louvre in 1911. The thief was caught by the police two years later, and the painting was safely returned."],"grading":{"spelling":"strict","maxWords":1},"items":[{"n":0,"prompt":"favour","example":true,"accept":["favourite"]},{"n":17,"prompt":"die","accept":["death"]},{"n":18,"prompt":"fame","accept":["famous"]},{"n":19,"prompt":"visit","accept":["visited"]},{"n":20,"prompt":"please","accept":["pleasant",