insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2006-okt-kozep-L2$mtr$, $mtr$2006-okt-kozep$mtr$, $mtr$language$mtr$, 2, $mtr$bank$mtr$, $mtr$szóbank (szavak visszahelyezése)$mtr$, 10, 6, $mtr${"id":"2006-okt-kozep-L2","number":2,"kind":"bank","layout":"inline","examType":"szóbank (szavak visszahelyezése)","points":10,"instructions":["You are going to read an article about Henry VIII. Some words are missing from the text.","Your task is to choose the most appropriate word from the list (A-M) for each gap (7-16) in the text. Write the letter of the appropriate word in the white box.","There is one extra word that you do not need to use."],"title":"THE ROYAL HUNTING WHISTLE","body":["A silver hunting whistle, which probably belonged to Henry VIII, has been {{0}} during a metal detectors’ club gathering. The whistle is engraved with motifs {{7}} link it to the king’s first wife, Catherine of Aragon. It is being studied at the British Museum.","The finder, Keith Stuart, 62, was {{8}} part in the club event in a field on the Isle of Wight, and is now {{9}} to be told the whistle’s value after experts have examined it thoroughly. Archeologists have {{10}} it to the 16th century. The whistle, 2½ inches long, is {{11}} with pomegranates, the emblem of Catherine of Aragon.","Historians believe that Henry hunted on the Isle of Wight, and the whistle may have been dropped during a {{12}}.","Mr Stuart, a former milkman, said the whistle was only a {{13}} inches below the soil at Shalfleet. He thought it {{14}} a toy gun or cannon, and did not consider it important. {{15}}, Mr Stuart later showed it to Frank Bashford, the coroner’s officer, who identified the {{16}} as silver and indicated that it was an antique huntsman’s whistle.","When Mr Stuart researched the emblem, the link with Henry VIII was suggested."],"bank":[{"key":"A","text":"DATED"},{"key":"B","text":"DECORATED"},{"key":"C","text":"FEW"},{"key":"D","text":"FOUND"},{"key":"E","text":"HOWEVER"},{"key":"F","text":"METAL"},{"key":"G","text":"RESEMBLED"},{"key":"H","text":"TAKING"},{"key":"I","text":"THAT"},{"key":"K","text":"THEIR"},{"key":"L","text":"VISIT"},{"key":"M","text":"WAITING"}],"items":[{"n":0,"example":true,"answer":"D"},{"n":7},{"n":8},{"n":9},{"n":10},{"n":11},{"n":12},{"n":13},{"n":14},{"n":15},{"n":16}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2006-okt-kozep-L2$mtr$, $mtr${"id":"2006-okt-kozep-L2","number":2,"kind":"bank","layout":"inline","examType":"szóbank (szavak visszahelyezése)","points":10,"instructions":["You are going to read an article about Henry VIII. Some words are missing from the text.","Your task is to choose the most appropriate word from the list (A-M) for each gap (7-16) in the text. Write the letter of the appropriate word in the white box.","There is one extra word that you do not need to use."],"title":"THE ROYAL HUNTING WHISTLE","body":["A silver hunting whistle, which probably belonged to Henry VIII, has been {{0}} during a metal detectors’ club gathering. The whistle is engraved with motifs {{7}} link it to the king’s first wife, Catherine of Aragon. It is being studied at the British Museum.","The finder, Keith Stuart, 62, was {{8}} part in the club event in a field on the Isle of Wight, and is now {{9}} to be told the whistle’s value after experts have examined it thoroughly. Archeologists have {{10}} it to the 16th century. The whistle, 2½ inches long, is {{11}} with pomegranates, the emblem of Catherine of Aragon.","Historians believe that Henry hunted on the Isle of Wight, and the whistle may have been dropped during a {{12}}.","Mr Stuart, a former milkman, said the whistle was only a {{13}} inches below the soil at Shalfleet. He thought it {{14}} a toy gun or cannon, and did not consider it important. {{15}}, Mr Stuart later showed it to Frank Bashford, the coroner’s officer, who identified the {{16}} as silver and indicated that it was an antique huntsman’s whistle.","When Mr Stuart researched the emblem, the link with Henry VIII was suggested."],"bank":[{"key":"A","text":"DATED"},{"key":"B","text":"DECORATED"},{"key":"C","text":"FEW"},{"key":"D","text":"FOUND"},{"key":"E","text":"HOWEVER"},{"key":"F","text":"METAL"},{"key":"G","text":"RESEMBLED"},{"key":"H","text":"TAKING"},{"key":"I","text":"THAT"},{"key":"K","text":"THEIR"},{"key":"L","text":"VISIT"},{"key":"M","text":"WAITING"}],"items":[{"n":0,"example":true,"answer":"D"},{"n":7,"answer":"I"},{"n":8,"answer":"H"},{"n":9,"answer":"M"},{"n":10,"answer":"A"},{"n":11,"answer":"B"},{"n":12,"answer":"L"},{"n":13,"answer":"C"},{"n":14,"answer":"G"},{"n":15,"answer":"E"},{"n":16,"answer":"F"}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2006-okt-kozep-L3$mtr$, $mtr$2006-okt-kozep$mtr$, $mtr$language$mtr$, 3, $mtr$text$mtr$, $mtr$nyílt cloze (egy szó)$mtr$, 9, 7, $mtr${"id":"2006-okt-kozep-L3","number":3,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":9,"instructions":["You are going to read a short article about Lost, the famous TV series. Some words are missing from the text.","Your task is to write the missing words – one word for each gap - on the dotted lines (17-25) after the text."],"title":"IN NEVER NEVER LAND","body":["A modern Hitchcock thriller; that sums up Lost – {{0}} popular series on Star Movies every Saturday {{17}} 7 p.m. It is {{18}} 48 people left on a remote island in the Pacific Ocean, after {{19}} flight breaks apart in mid-air and crashes on the island. The survivors include couples, friends and enemies. They {{20}} all forced to come together with one aim: to survive at all cost.","Their faces reflect panic, anxiety {{21}} hopelessness as they try to bring order out of the chaos under the leadership of Jack, a doctor, played {{22}} Matthew Fox. He treats the sick and the wounded, and takes the initiative for survival techniques.","In Lost, which has been nominated for 12 Emmy awards, each scene is full {{23}} suspense as the island itself seems {{24}} hide its own frightening secrets. Even the survivors have their own horrifying stories. For instance, Kate, who has just escaped the police, often remembers her past and {{25}} does Locke, the strange guy with a passion for adventure.","Will they escape from the lost world? Wait and see."],"grading":{"spelling":"strict"},"items":[{"n":0,"example":true,"accept":["the"]},{"n":17},{"n":18},{"n":19},{"n":20},{"n":21},{"n":22},{"n":23},{"n":24},{"n":25}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2006-okt-kozep-L3$mtr$, $mtr${"id":"2006-okt-kozep-L3","number":3,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":9,"instructions":["You are going to read a short article about Lost, the famous TV series. Some words are missing from the text.","Your task is to write the missing words – one word for each gap - on the dotted lines (17-25) after the text."],"title":"IN NEVER NEVER LAND","body":["A modern Hitchcock thriller; that sums up Lost – {{0}} popular series on Star Movies every Saturday {{17}} 7 p.m. It is {{18}} 48 people left on a remote island in the Pacific Ocean, after {{19}} flight breaks apart in mid-air and crashes on the island. The survivors include couples, friends and enemies. They {{20}} all forced to come together with one aim: to survive at all cost.","Their faces reflect panic, anxiety {{21}} hopelessness as they try to bring order out of the chaos under the leadership of Jack, a doctor, played {{22}} Matthew Fox. He treats the sick and the wounded, and takes the initiative for survival techniques.","In Lost, which has been nominated for 12 Emmy awards, each scene is full {{23}} suspense as the island itself seems {{24}} hide its own frightening secrets. Even the survivors have their own horrifying stories. For instance, Kate, who has just escaped the police, often remembers her past and {{25}} does Locke, the strange guy with a passion for adventure.","Will they escape from the lost world? Wait and see."],"grading":{"spelling":"strict","maxWords":1},"items":[{"n":0,"example":true,"accept":["the"]},{"n":17,"accept":["at","from"]},{"n":18,"accept":["about"]},{"n":19,"accept":["their","a"]},{"n":20,"accept":["are"]},{"n":21,"accept":["and"]},{"n":22,"accept":["by"]},{"n":23,"accept":["of"]},{"n":24,"accept":["to"]},{"n":25,"accept":["so"]}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2006-okt-kozep-H1$mtr$, $mtr$2006-okt-kozep$mtr$, $mtr$listening$mtr$, 1, $mtr$text$mtr$, $mtr$mondatkiegészítés hallás után$mtr$, 9, 8, $mtr${"id":"2006-okt-kozep-H1","number":1,"kind":"text","layout":"stems","examType":"mondatkiegészítés hallás után","points":9,"instructions":["In this section, you are going to hear an anecdote about Albert Einstein.","Your task is to fill in the gaps with ONE single word.","First, you will have some time to study the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers.","At the end, you will have some more time to check your work."],"audio":{"file":"k_angol_06okt_fl.mp3","start":0,"end":750.61,"clip":"hang/k_angol_06okt_fl_H1.mp3"},"items":[{"n":0,"example":true,"stem":"Albert Einstein was a famous {{gap}}","accept":["physicist"]},{"n":1,"stem":"Einstein's theory changed the way that scientists understand {{gap}} and time."},{"n":2,"stem":"The first part of his theory was born in {{gap}}."},{"n":3,"stem":"Einstein became a {{gap}} of Theoretical Physics at Princeton University."},{"n":4,"stem":"Einstein toured the various {{gap}} in the United States."},{"n":5,"stem":"Einstein's chauffeur, Harry, was always seated in the {{gap}} row."},{"n":6,"stem":"Harry told Einstein that he would be able to deliver the {{gap}} perfectly."},{"n":7,"stem":"While Harry was speaking to the audience, Einstein was enjoying a {{gap}}."},{"n":8,"stem":"Unfortunately, one of the research {{gap}} asked Harry a question."},{"n":9,"stem":"The question was difficult because it involved complex {{gap}} and equations."}],"grading":{"spelling":"lenient"}}$mtr$::jsonb, $mtr${"file":"k_angol_06okt_fl.mp3","start":0,"end":750.61,"clip":"hang/k_angol_06okt_fl_H1.mp3"