insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2007-maj-kozep-L2$mtr$, $mtr$2007-maj-kozep$mtr$, $mtr$language$mtr$, 2, $mtr$bank$mtr$, $mtr$szóbank (szavak visszahelyezése)$mtr$, 9, 6, $mtr${"id":"2007-maj-kozep-L2","number":2,"kind":"bank","layout":"inline","examType":"szóbank (szavak visszahelyezése)","points":9,"instructions":["You are going to read an article about a man who wanted to disappear. Some words are missing from the text.","Your task is to choose the most appropriate word from the list (A-L) for each gap (7-15) in the text. Write the letter of the appropriate word in the white box.","There is one extra word that you do not need to use."],"title":"MAN RUNS AFTER LOSING BET","body":["A man staged his own disappearance in the Bighorn Mountains after {{0}} $40,000 on a Super Bowl bet, police said Monday.","Marvin Hackworth, 46, was reported {{7}} on Feb 6, the day after the Super Bowl, according to the Big Horn County Sheriff's Office. Search and rescue teams spent two days {{8}} for him in the Bighorn Mountains in north-central Wyoming. He had told his wife he wanted to \"clear his head\" {{9}} losing the money, the sheriff's office said in a statement. The search was suspended Wednesday evening as there was no evidence of {{10}} he might have been. On Friday, police received a call from a person {{11}} herself as Hackworth's daughter, saying she had {{12}} a voice mail message from her father saying he was OK. Police traced the call to a town in Nebraska, and a few hours later they {{13}} Hackworth. It turned out that Hackworth had {{14}} a new pick up truck in the mountains before the Super Bowl in order to \"disappear for a while\" in case he lost the bet.","Hackworth said he knew he had to do something, {{15}} he had serious gambling losses. Hackworth also told the sheriff he was seeking counseling help for a \"gambling problem\"."],"bank":[{"key":"A","text":"AFTER"},{"key":"B","text":"BECAUSE"},{"key":"C","text":"BUT"},{"key":"D","text":"FOUND"},{"key":"E","text":"HIDDEN"},{"key":"F","text":"IDENTIFYING"},{"key":"G","text":"LOSING"},{"key":"H","text":"LOOKING"},{"key":"I","text":"MISSING"},{"key":"K","text":"RECEIVED"},{"key":"L","text":"WHERE"}],"items":[{"n":0,"example":true,"answer":"G"},{"n":7},{"n":8},{"n":9},{"n":10},{"n":11},{"n":12},{"n":13},{"n":14},{"n":15}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2007-maj-kozep-L2$mtr$, $mtr${"id":"2007-maj-kozep-L2","number":2,"kind":"bank","layout":"inline","examType":"szóbank (szavak visszahelyezése)","points":9,"instructions":["You are going to read an article about a man who wanted to disappear. Some words are missing from the text.","Your task is to choose the most appropriate word from the list (A-L) for each gap (7-15) in the text. Write the letter of the appropriate word in the white box.","There is one extra word that you do not need to use."],"title":"MAN RUNS AFTER LOSING BET","body":["A man staged his own disappearance in the Bighorn Mountains after {{0}} $40,000 on a Super Bowl bet, police said Monday.","Marvin Hackworth, 46, was reported {{7}} on Feb 6, the day after the Super Bowl, according to the Big Horn County Sheriff's Office. Search and rescue teams spent two days {{8}} for him in the Bighorn Mountains in north-central Wyoming. He had told his wife he wanted to \"clear his head\" {{9}} losing the money, the sheriff's office said in a statement. The search was suspended Wednesday evening as there was no evidence of {{10}} he might have been. On Friday, police received a call from a person {{11}} herself as Hackworth's daughter, saying she had {{12}} a voice mail message from her father saying he was OK. Police traced the call to a town in Nebraska, and a few hours later they {{13}} Hackworth. It turned out that Hackworth had {{14}} a new pick up truck in the mountains before the Super Bowl in order to \"disappear for a while\" in case he lost the bet.","Hackworth said he knew he had to do something, {{15}} he had serious gambling losses. Hackworth also told the sheriff he was seeking counseling help for a \"gambling problem\"."],"bank":[{"key":"A","text":"AFTER"},{"key":"B","text":"BECAUSE"},{"key":"C","text":"BUT"},{"key":"D","text":"FOUND"},{"key":"E","text":"HIDDEN"},{"key":"F","text":"IDENTIFYING"},{"key":"G","text":"LOSING"},{"key":"H","text":"LOOKING"},{"key":"I","text":"MISSING"},{"key":"K","text":"RECEIVED"},{"key":"L","text":"WHERE"}],"items":[{"n":0,"example":true,"answer":"G"},{"n":7,"answer":"I"},{"n":8,"answer":"H"},{"n":9,"answer":"A"},{"n":10,"answer":"L"},{"n":11,"answer":"F"},{"n":12,"answer":"K"},{"n":13,"answer":"D"},{"n":14,"answer":"E"},{"n":15,"answer":"B"}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2007-maj-kozep-L3$mtr$, $mtr$2007-maj-kozep$mtr$, $mtr$language$mtr$, 3, $mtr$text$mtr$, $mtr$nyílt cloze (egy szó)$mtr$, 10, 7, $mtr${"id":"2007-maj-kozep-L3","number":3,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":10,"instructions":["You are going to read a text about an old couple. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (16-25) after the text.","Use only one word in each gap."],"title":"STILL IN LOVE AFTER 77 VALENTINE'S DAYS","body":["Fred Landis has a Valentine's Day ritual. Sometime, somewhere, he'll lean over to {{0}} wife, Gwen, and say, \"I love you.\" They say he's been doing that on Valentine's Days {{16}} 1928, when they got married.","In October, Fred, 102, and Gwen, 101, celebrated {{17}} 77th wedding anniversary. It is almost a record as the longest current marriage, according {{18}} the 2006 edition of Guinness World Records, is 78 years, 296 days.","On Valentine's Day 2006, Fred will say \"I love you\" a bit louder {{19}} he used to because Gwen is hard of hearing. Fred also has health problems, and that has kept {{20}} from writing poetry for her. Gwen says Fred wrote poems to her during their courtship, a gesture {{21}} may have won her heart.","They met in 1924 as college students in Seattle. Fred attended a church where Gwen's father was the pastor. Gwen remembers receiving $800 {{22}} their relatives, then losing it all in the stock-market crash {{23}} following year. The Landises spent the next four decades working and raising four children. Fred was the pastor at several small churches in the Northwest. Gwen played {{24}} piano and organ and taught Sunday school. He retired in 1970, and they {{25}} lived in Salem since then. They moved to a retirement center in 1994. They have eight grandchildren and 19 great-grandchildren."],"grading":{"spelling":"strict"},"items":[{"n":0,"example":true,"accept":["his"]},{"n":16},{"n":17},{"n":18},{"n":19},{"n":20},{"n":21},{"n":22},{"n":23},{"n":24},{"n":25}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2007-maj-kozep-L3$mtr$, $mtr${"id":"2007-maj-kozep-L3","number":3,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":10,"instructions":["You are going to read a text about an old couple. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (16-25) after the text.","Use only one word in each gap."],"title":"STILL IN LOVE AFTER 77 VALENTINE'S DAYS","body":["Fred Landis has a Valentine's Day ritual. Sometime, somewhere, he'll lean over to {{0}} wife, Gwen, and say, \"I love you.\" They say he's been doing that on Valentine's Days {{16}} 1928, when they got married.","In October, Fred, 102, and Gwen, 101, celebrated {{17}} 77th wedding anniversary. It is almost a record as the longest current marriage, according {{18}} the 2006 edition of Guinness World Records, is 78 years, 296 days.","On Valentine's Day 2006, Fred will say \"I love you\" a bit louder {{19}} he used to because Gwen is hard of hearing. Fred also has health problems, and that has kept {{20}} from writing poetry for her. Gwen says Fred wrote poems to her during their courtship, a gesture {{21}} may have won her heart.","They met in 1924 as college students in Seattle. Fred attended a church where Gwen's father was the pastor. Gwen remembers receiving $800 {{22}} their relatives, then losing it all in the stock-market crash {{23}} following year. The Landises spent the next four decades working and raising four children. Fred was the pastor at several small churches in the Northwest. Gwen played {{24}} piano and organ and taught Sunday school. He retired in 1970, and they {{25}} lived in Salem since then. They moved to a retirement center in 1994. They have eight grandchildren and 19 great-grandchildren."],"grading":{"spelling":"strict","maxWords":1},"items":[{"n":0,"example":true,"accept":["his"]},{"n":16,"accept":["since"]},{"n":17,"accept":["their"]},{"n":18,"accept":["to"]},{"n":19,"accept":["than"]},{"n":20,"accept":["him"]},{"n":21,"accept":["that","which"]},{"n":22,"accept":["from"]},{"n":23,"accept":["the"]},{"n":24,"accept":["both","the"]},{"n":25,"accept":["have"]}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
