insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2008-maj-emelt-H1$mtr$, $mtr$2008-maj-emelt$mtr$, $mtr$listening$mtr$, 1, $mtr$choice$mtr$, $mtr$igaz / hamis / a szöveg nem mondja (A/B/C)$mtr$, 11, 9, $mtr${"id":"2008-maj-emelt-H1","number":1,"kind":"choice","layout":"stems","examType":"igaz / hamis / a szöveg nem mondja (A/B/C)","points":11,"instructions":["In this section you are going to hear about Raoul Derosiers, a man with X-ray vision.","Your task will be to decide whether the following statements are true, false or we do not know because the text does not say, and write the appropriate letter into the boxes on the right. Write A if the statement is true, write B if the statement is false, and write C if the text does not say.","First, you will have some time to study the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers.","At the end, you will have some more time to check your work."],"audio":{"file":"e_angol_08maj_fl.mp3","start":0,"end":635.64,"clip":"hang/e_angol_08maj_fl_H1.mp3"},"items":[{"n":0,"example":true,"stem":"Derosiers is a Canadian businessman.","answer":"A"},{"n":1,"stem":"Water witching is the same as dowsing."},{"n":2,"stem":"Derosiers couldn't locate where the pains in his body were."},{"n":3,"stem":"The doctor that he turned to was an old friend of his."},{"n":4,"stem":"The sleeping pills didn't ease his pains at all."},{"n":5,"stem":"Derosiers' cousin was afraid that his business would fail."},{"n":6,"stem":"He managed to help his cousin immediately."},{"n":7,"stem":"The two men were in a barn when Derosiers felt terrible pains."},{"n":8,"stem":"He told his cousin how deep the water was to be found."},{"n":9,"stem":"The water was found exactly where he had predicted."},{"n":10,"stem":"His cousin invited him to become his partner."},{"n":11,"stem":"Unfortunately, Derosiers' X-ray vision didn't always work properly."}],"options":[{"key":"A","text":"TRUE"},{"key":"B","text":"FALSE"},{"key":"C","text":"THE TEXT DOES NOT SAY"}]}$mtr$::jsonb, $mtr${"file":"e_angol_08maj_fl.mp3","start":0,"end":635.64,"clip":"hang/e_angol_08maj_fl_H1.mp3"}$mtr$::jsonb)
