insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2009-maj-emelt-L2$mtr$, $mtr$2009-maj-emelt$mtr$, $mtr$language$mtr$, 2, $mtr$text$mtr$, $mtr$szóképzés (zárójeles szó)$mtr$, 10, 6, $mtr${"id":"2009-maj-emelt-L2","number":2,"kind":"text","layout":"inline","examType":"szóképzés (zárójeles szó)","points":10,"instructions":["You are going to read an article about an interesting job opportunity. Some words are missing from the text.","Use the words in brackets to form the words that fit in the gaps (11-20).","There might be cases when you do not have to change the word in brackets.","Use only one word for each gap."],"title":"THE BEST JOB IN THE WORLD","body":["Desperate to grab what's being called the “Best Job in the World”, thousands of {{0}} from across the globe have submitted video {{11}} to the Queensland tourism department in Australia for its latest advertised {{12}} - a $150,000 contract to relax on Hamilton Island in the Great Barrier Reef for six months while writing a blog to promote the island.","{{13}} to the advertisement has been mind-boggling. More than a million {{14}} have logged onto the website that advertises the job since it was {{15}} on Monday.","On Thursday an {{16}} team of 10 people were sifting through the 2,000 videos the department had already received, with tens of thousands more expected before the February 22 deadline.","In exchange for the tempting salary, free {{17}} in an oceanfront villa and airfare from the winner's home country, the {{18}} will be required to perform such {{19}} tasks as strolling the island's white sand beaches, snorkelling its crystal clear waters and exploring other islands along the reef.","The job is part of a $1.1 million campaign to advertise the {{20}} of north- eastern Queensland and the winner will be required to post videos and photos on a weekly blog to help promote the area."],"grading":{"spelling":"strict"},"items":[{"n":0,"prompt":"hope","example":true,"accept":["hopefuls"]},{"n":11,"prompt":"apply"},{"n":12,"prompt":"vacant"},{"n":13,"prompt":"respond"},{"n":14,"prompt":"visit"},{"n":15,"prompt":"public"},{"n":16,"prompt":"exhaust"},{"n":17,"prompt":"accommodate"},{"n":18,"prompt":"employ"},{"n":19,"prompt":"tire"},{"n":20,"prompt":"charm"}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2009-maj-emelt-L2$mtr$, $mtr${"id":"2009-maj-emelt-L2","number":2,"kind":"text","layout":"inline","examType":"szóképzés (zárójeles szó)","points":10,"instructions":["You are going to read an article about an interesting job opportunity. Some words are missing from the text.","Use the words in brackets to form the words that fit in the gaps (11-20).","There might be cases when you do not have to change the word in brackets.","Use only one word for each gap."],"title":"THE BEST JOB IN THE WORLD","body":["Desperate to grab what's being called the “Best Job in the World”, thousands of {{0}} from across the globe have submitted video {{11}} to the Queensland tourism department in Australia for its latest advertised {{12}} - a $150,000 contract to relax on Hamilton Island in the Great Barrier Reef for six months while writing a blog to promote the island.","{{13}} to the advertisement has been mind-boggling. More than a million {{14}} have logged onto the website that advertises the job since it was {{15}} on Monday.","On Thursday an {{16}} team of 10 people were sifting through the 2,000 videos the department had already received, with tens of thousands more expected before the February 22 deadline.","In exchange for the tempting salary, free {{17}} in an oceanfront villa and airfare from the winner's home country, the {{18}} will be required to perform such {{19}} tasks as strolling the island's white sand beaches, snorkelling its crystal clear waters and exploring other islands along the reef.","The job is part of a $1.1 million campaign to advertise the {{20}} of north- eastern Queensland and the winner will be required to post videos and photos on a weekly blog to help promote the area."],"grading":{"spelling":"strict","maxWords":1},"items":[{"n":0,"prompt":"hope","example":true,"accept":["hopefuls"]},{"n":11,"prompt":"apply","accept":["applications"]},{"n":12,"prompt":"vacant","accept":["vacancy"]},{"n":13,"p