insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2009-maj-kozep-L3$mtr$, $mtr$2009-maj-kozep$mtr$, $mtr$language$mtr$, 3, $mtr$text$mtr$, $mtr$nyílt cloze (egy szó)$mtr$, 10, 7, $mtr${"id":"2009-maj-kozep-L3","number":3,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":10,"instructions":["You are going to read a humorous story about an examination. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (20-29) after the text.","Use only one word in each gap."],"title":"BIRDS","body":["Janet was a biology major at a big American university. Her biology professor announced {{0}} exam for the following week on birds. \"You will {{20}} to know everything about every type of bird {{21}} exists,\" he said. Janet spent the week studying beaks, wings {{22}} feathers of dozens of bird species.","On the day of the exam, the professor {{23}} standing behind a table with five paper bags on it. Under each bag was a model of a bird. The professor lifted the first bag a bit {{24}} reveal only the legs, and asked the class to {{25}} down the type of bird. Janet got very angry, because she could {{26}} even guess the type of bird. {{27}} the professor got to the third bag, Janet stood up, walked up to the table, and threw {{28}} crumpled test paper onto the table. She said, \"This is the {{29}} ridiculous test I have ever seen and you are an IDIOT!\"","The professor said, \"Just hold it right there, what is your name?\" Janet raised her dress to her knees and said, \"You tell me!\""],"grading":{"spelling":"strict"},"items":[{"n":0,"example":true,"accept":["an"]},{"n":20},{"n":21},{"n":22},{"n":23},{"n":24},{"n":25},{"n":26},{"n":27},{"n":28},{"n":29}]}$mtr$::jsonb, null)
