insert into public.exams (id, year, session, level, meta) values ($mtr$2009-okt-kozep$mtr$, 2009, $mtr$október$mtr$, $mtr$közép$mtr$, $mtr${"formatVersion":1,"id":"2009-okt-kozep","year":2009,"session":"október","level":"közép","examDate":"2009-10-22","code":"0804","sourceFiles":{"paper":"2009. Középszintű október-novemberi érettségi írásbeli feladatok és javítási-értékelési útmutatók/k_angol_09okt_fl.pdf","key":"2009. Középszintű október-novemberi érettségi írásbeli feladatok és javítási-értékelési útmutatók/k_angol_09okt_ut.pdf","audio":"2009. Középszintű október-novemberi érettségi írásbeli feladatok és javítási-értékelési útmutatók/k_angol_09okt_fl.mp3"},"sections":[{"id":"reading","title":"I. Olvasott szöveg értése","minutes":60,"maxTaskPoints":29,"maxExamPoints":33,"conversion":{"0":0,"1":1,"2":2,"3":3,"4":5,"5":6,"6":7,"7":8,"8":9,"9":10,"10":11,"11":13,"12":14,"13":15,"14":16,"15":17,"16":18,"17":19,"18":20,"19":22,"20":23,"21":24,"22":25,"23":26,"24":27,"25":28,"26":30,"27":31,"28":32,"29":33},"taskIds":["2009-okt-kozep-R1","2009-okt-kozep-R2","2009-okt-kozep-R3","2009-okt-kozep-R4"]},{"id":"language","title":"II. Nyelvhelyesség","minutes":30,"maxTaskPoints":26,"maxExamPoints":18,"conversion":{"0":0,"1":1,"2":1,"3":2,"4":3,"5":3,"6":4,"7":5,"8":6,"9":6,"10":7,"11":8,"12":8,"13":9,"14":10,"15":10,"16":11,"17":12,"18":12,"19":13,"20":14,"21":15,"22":15,"23":16,"24":17,"25":17,"26":18},"taskIds":["2009-okt-kozep-L1","2009-okt-kozep-L2","2009-okt-kozep-L3"]},{"id":"listening","title":"III. Hallott szöveg értése","minutes":30,"maxTaskPoints":25,"maxExamPoints":33,"conversion":{"0":0,"1":1,"2":3,"3":4,"4":5,"5":7,"6":8,"7":9,"8":11,"9":12,"10":13,"11":15,"12":16,"13":17,"14":18,"15":20,"16":21,"17":22,"18":24,"19":25,"20":26,"21":28,"22":29,"23":30,"24":32,"25":33},"taskIds":["2009-okt-kozep-H1","2009-okt-kozep-H2","2009-okt-kozep-H3"]}]}$mtr$::jsonb)
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2009-okt-kozep-R1$mtr$, $mtr$2009-okt-kozep$mtr$, $mtr$reading$mtr$, 1, $mtr$text$mtr$, $mtr$rövid válasz olvasott szöveg alapján$mtr$, 9, 1, $mtr${"id":"2009-okt-kozep-R1","number":1,"kind":"text","layout":"stems","examType":"rövid válasz olvasott szöveg alapján","points":9,"instructions":["Read this short article on a meteorite impact.","Your task is to give short answers (maximum four words) to the questions (1-9) that follow."],"title":"Space Rock Makes a Crash Landing","body":["A grapefruit-size meteorite crashed through the roof of a house in New Zealand this spring, hit the ceiling, slammed into a couch and rolled under a table. Experts say the extremely hot rock was traveling about 500 kilometers an hour when it crashed through the roof. Its landing made a terrific explosion.","Astronomer Joel Schiff of the University of Auckland said, \"It is most likely a chip off an asteroid and is older than anything else on Earth. \"In fact, the meteorite is about 4.5 billion years old. \"It is one of the few physical records of the early solar system,\" Schiff said.","According to experts, the space rock was probably traveling 50,000 kilometers an hour when it reached Earth's atmosphere. The atmosphere slowed it down. Most likely the space rock came to Earth from an asteroid belt located between Mars and Jupiter, some 700 million kilometers away.","Luckily no one was hurt when the meteorite landed, but it could mean money from the heavens for homeowner Brenda Archer. Experts say the space rock—only the ninth known meteorite to land in New Zealand—is probably worth more than U.S. $30,000!","But don't expect to get rich on meteorites. Most space rocks entering the Earth's atmosphere burn up during their journey."],"grading":{"spelling":"keywords"},"items":[{"n":0,"example":true,"stem":"When did this crash landing happen? {{gap}}","accept":["This spring"]},{"n":1,"stem":"Where did the rock stop in the house? {{gap}}"},{"n":2,"stem":"What is the job of the person who believes the rock broke off an asteroid? {{gap}}"},{"n":3,"stem":"What is the age of the rock? {{gap}}"},{"n":4,"stem":"What reduced the speed of the rock before it hit the house? {{gap}}"},{"n":5,"stem":"What distance did the rock travel? {{gap}}"},{"n":6,"stem":"How many meteorites have landed in New Zealand that we know about? {{gap}}"},{"n":7,"stem":"Who does the house belong to? {{gap}}"},{"n":8,"stem":"What is the probable value of the meteorite? {{gap}}"},{"n":9,"stem":"What happens to most space rocks when they reach the Earth’s atmosphere? {{gap}}"}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2009-okt-kozep-R1$mtr$, $mtr${"id":"2009-okt-kozep-R1","number":1,"kind":"text","layout":"stems","examType":"rövid válasz olvasott szöveg alapján","points":9,"instructions":["Read this short article on a meteorite impact.","Your task is to give short answers (maximum four words) to the questions (1-9) that follow."],"title":"Space Rock Makes a Crash Landing","body":["A grapefruit-size meteorite crashed through the roof of a house in New Zealand this spring, hit the ceiling, slammed into a couch and rolled under a table. Experts say the extremely hot rock was traveling about 500 kilometers an hour when it crashed through the roof. Its landing made a terrific explosion.","Astronomer Joel Schiff of the University of Auckland said, \"It is most likely a chip off an asteroid and is older than anything else on Earth. \"In fact, the meteorite is about 4.5 billion years old. \"It is one of the few physical records of the early solar system,\" Schiff said.","According to experts, the space rock was probably traveling 50,000 kilometers an hour when it reached Earth's atmosphere. The atmosphere slowed it down. Most likely the space rock came to Earth from an asteroid belt located between Mars and Jupiter, some 700 million kilometers away.","Luckily no one was hurt when the meteorite landed, but it could mean money from the heavens for homeowner Brenda Archer. Experts say the space rock—only the ninth known meteorite to land in New Zealand—is probably worth more than U.S. $30,000!","But don't expect to get rich on meteorites. Most space rocks entering the Earth's atmosphere burn up during their journey."],"grading":{"spelling":"keywords","caseSensitive":false,"maxWords":4},"items":[{"n":0,"example":true,"stem":"When did this crash landing happen? {{gap}}","accept":["This spring"]},{"n":1,"stem":"Where did the rock stop in the house? {{gap}}","key":"Under a table. / On the floor.","keywords":[["under","table"],["floor"]]},{"n":2,"stem":"What is the job of the person who believes the rock broke off an asteroid? {{gap}}","key":"(He's a(n)) astronomer/scientist.","keywords":[["astronomer"],["scientist"]]},{"n":3,"stem":"What is the age of the rock? {{gap}}","key":"4.5 billion years.","keywords":[["4","5","billion","years"]]},{"n":4,"stem":"What reduced the speed of the rock before it hit the house? {{gap}}","key":"The (Earth’s) atmosphere.","keywords":[["atmosphere"]]},{"n":5,"stem":"What distance did the rock travel? {{gap}}","key":"(About) 700 million kilometres.","keywords":[["700","million","kilometres"]]},{"n":6,"stem":"How many meteorites have landed in New Zealand that we know about? {{gap}}","key":"9.","keywords":[["9"],["nine"]]},{"n":7,"stem":"Who does the house belong to? {{gap}}","key":"Brenda Archer.","keywords":[["brenda","archer"]]},{"n":8,"stem":"What is the probable value of the meteorite? {{gap}}","key":"$30,000.","keywords":[["dollars","30000"]]},{"n":9,"stem":"What happens to most space rocks when they reach the Earth’s atmosphere? {{gap}}","key":"They burn up.","keywords":[["burn","up"]]}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2009-okt-kozep-R2$mtr$, $mtr$2009-okt-kozep$mtr$, $mtr$reading$mtr$, 2, $mtr$choice$mtr$, $mtr$igaz / hamis / nincs elég információ (A/B/C)$mtr$, 7, 2, $mtr${"id":"2009-okt-kozep-R2","number":2,"kind":"choice","layout":"stems","examType":"igaz / hamis / nincs elég információ (A/B/C)","points":7,"instructions":["Read this text about Kate’s blind date and the sentences (10-16) following it.","Mark each sentence A if it is true according to the text, B if it is false, C if there isn’t enough information in the text to say if it is true or not."],"title":"“My best blind date”","body":["“When I turned 30, my grandma, with whom I am very close, became paranoid that I’d never get married, like 30 is over the hill or something. Just to quiet her, I agreed to go out with the grandson of a friend of hers, whom she knew well and claimed was ‘a very handsome lawyer.’ I, however, was certain he would be a total loser and couldn’t believe I agreed to the date. My friends and I joked about it during the weeks leading up to the date, and I had extremely low expectations. When he came to meet me outside my house, I almost fainted; he looked great. During the date I also found out he was very intelligent, well-educated and loves Woody Allen movies as much as I do. We had a great dinner, even better conversation—and there was a definite spark. We kept seeing each other after that, and each date was better than the last. We got engaged about a month ago, and of course my grandma takes all the credit!” – Kate, 30"],"options":[{"key":"A","text":"TRUE"},{"key":"B","text":"FALSE"},{"key":"C","text":"NOT ENOUGH INFORMATION"}],"items":[{"n":0,"example":true,"stem":"Kate and her grandmother get on well.","answer":"A"},{"n":10,"stem":"Kate’s grandmother was afraid that Kate would not be able to find a husband."},{"n":11,"stem":"The grandmother had never seen the young man before."},{"n":12,"stem":"Kate only agreed to meet the young man to please her grandmother."},{"n":13,"stem":"He arrived at her place by car."},{"n":14,"stem":"At first she did not find the man attractive."},{"n":15,"stem":"The young man was not very interested in Woody Allen movies."},{"n":16,"stem":"They had dinner in an expensive restaurant."}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2009-okt-kozep-R2$mtr$, $mtr${"id":"2009-okt-kozep-R2","number":2,"kind":"choice","layout":"stems","examType":"igaz / hamis / nincs elég információ (A/B/C)","points":7,"instructions":["Read this text about Kate’s blind date and the sentences (10-16) following it.","Mark each sentence A if it is true according to the text, B if it is false, C if there isn’t enough information in the text to say if it is true or not."],"title":"“My best blind date”","body":["“When I turned 30, my grandma, with whom I am very close, became paranoid that I’d never get married, like 30 is over the hill or something. Just to quiet her, I agreed to go out with the grandson of a friend of hers, whom she knew well and claimed was ‘a very handsome lawyer.’ I, however, was certain he would be a total loser and couldn’t believe I agreed to the date. My friends and I joked about it during the weeks leading up to the date, and I had extremely low expectations. When he came to meet me outside my house, I almost fainted; he looked great. During the date I also found out he was very intelligent, well-educated and loves Woody Allen movies as much as I do. We had a great dinner, even better conversation—and there was a definite spark. We kept seeing each other after that, and each date was better than the last. We got engaged about a month ago, and of course my grandma takes all the credit!” – Kate, 30"],"options":[{"key":"A","text":"TRUE"},{"key":"B","text":"FALSE"},{"key":"C","text":"NOT ENOUGH INFORMATION"}],"items":[{"n":0,"example":true,"stem":"Kate and her grandmother get on well.","answer":"A"},{"n":10,"stem":"Kate’s grandmother was afraid that Kate would not be able to find a husband.","answer":"A"},{"n":11,"stem":"The grandmother had never seen the young man before.","answer":"B"},{"n":12,"stem":"Kate only agreed to meet the young man to please her grandmother.","answer":"A"},{"n":13,"stem":"He arrived at her place by car.","answer":"C"},{"n":14,"stem":"At first she did not find the man attractive.","answer":"B"},{"n":15,"stem":"The young man was not very interested in Woody Allen movies.","answer":"B"},{"n":16,"stem":"They had dinner in an expensive restaurant.","answer":"C"}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2009-okt-kozep-R3$mtr$, $mtr$2009-okt-kozep$mtr$, $mtr$reading$mtr$, 3, $mtr$bank$mtr$, $mtr$mondatrész visszahelyezése szövegbe$mtr$, 7, 3, $mtr${"id":"2009-okt-kozep-R3","number":3,"kind":"bank","layout":"inline","examType":"mondatrész visszahelyezése szövegbe","points":7,"instructions":["Read this story about a goldfish named Albert Einstein.","Some parts of sentences have been left out from the text.","Your task is to fill in the gaps (17-23) from the list (A-I) below.","Remember that there is one extra letter that you do not need."],"title":"Pet Fish Learn New Tricks","body":["Albert Einstein, a goldfish, is {{0}} He has learned to take food from his owner's hand, swim through hoops and tubes, {{17}} It all started when Jack Brown, 9, won two goldfish at a school fair. Soon he noticed that the fish would react to his movements {{18}} He wondered if they were smarter than he'd realized. He and his dad decided to train one of them, Albert. They used techniques {{19}} \"We wanted to show that fish can be interesting pets, not just decorations,\" said Jack's father, David Brown. The Browns bought a \"finger soccer\" kit and put weights on the tiny net and ball so they would stay at the bottom of the tank.","First Albert got treated to some tasty food every time he swam toward the net. The fish liked the treat, {{20}} Once Albert learned to go toward the net, Jack and his dad added a new step - ball handling. In the end, Albert learned {{21}}","The trainer needs to have patience, the father-son team says. It may take five or six training sessions a day for three weeks {{22}}","Just like kids, individual fish learn at different speeds!","The Browns set up a website so other people could see how much fun they were having with their fish project. They heard from so many people who wanted to train their pet fish {{23}} a small business that sells fish-training books and equipment."],"bank":[{"key":"A","text":"to push the ball into a goal."},{"key":"B","text":"so it learned to repeat the action to get more treats."},{"key":"C","text":"whenever he came near the tank."},{"key":"D","text":"that the Browns started Fish School,"},{"key":"E","text":"and even put a miniature soccer ball into a goal!"},{"key":"F","text":"and they were interesting"},{"key":"G","text":"not an ordinary pet goldfish."},{"key":"H","text":"to teach a fish something new."},{"key":"I","text":"that work for other animals like dogs."}],"items":[{"n":0,"example":true,"answer":"G"},{"n":17},{"n":18},{"n":19},{"n":20},{"n":21},{"n":22},{"n":23}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2009-okt-kozep-R3$mtr$, $mtr${"id":"2009-okt-kozep-R3","number":3,"kind":"bank","layout":"inline","examType":"mondatrész visszahelyezése szövegbe","points":7,"instructions":["Read this story about a goldfish named Albert Einstein.","Some parts of sentences have been left out from the text.","Your task is to fill in the gaps (17-23) from the list (A-I) below.","Remember that there is one extra letter that you do not need."],"title":"Pet Fish Learn New Tricks","body":["Albert Einstein, a goldfish, is {{0}} He has learned to take food from his owner's hand, swim through hoops and tubes, {{17}} It all started when Jack Brown, 9, won two goldfish at a school fair. Soon he noticed that the fish would react to his movements {{18}} He wondered if they were smarter than he'd realized. He and his dad decided to train one of them, Albert. They used techniques {{19}} \"We wanted to show that fish can be interesting pets, not just decorations,\" said Jack's father, David Brown. The Browns bought a \"finger soccer\" kit and put weights on the tiny net and ball so they would stay at the bottom of the tank.","First Albert got treated to some tasty food every time he swam toward the net. The fish liked the treat, {{20}} Once Albert learned to go toward the net, Jack and his dad added a new step - ball handling. In the end, Albert learned {{21}}","The trainer needs to have patience, the father-son team says. It may take five or six training sessions a day for three weeks {{22}}","Just like kids, individual fish learn at different speeds!","The Browns set up a website so other people could see how much fun they were having with their fish project. They heard from so many people who wanted to train their pet fish {{23}} a small business that sells fish-training books and equipment."],"bank":[{"key":"A","text":"to push the ball into a goal."},{"key":"B","text":"so it learned to repeat the action to get more treats."},{"key":"C","text":"whenever he came near the tank."},{"key":"D","text":"that the Browns started Fish School,"},{"key":"E","text":"and even put a miniature soccer ball into a goal!"},{"key":"F","text":"and they were interesting"},{"key":"G","text":"not an ordinary pet goldfish."},{"key":"H","text":"to teach a fish something new."},{"key":"I","text":"that work for other animals like dogs."}],"items":[{"n":0,"example":true,"answer":"G"},{"n":17,"answer":"E"},{"n":18,"answer":"C"},{"n":19,"answer":"I"},{"n":20,"answer":"B"},{"n":21,"answer":"A"},{"n":22,"answer":"H"},{"n":23,"answer":"D"}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2009-okt-kozep-R4$mtr$, $mtr$2009-okt-kozep$mtr$, $mtr$reading$mtr$, 4, $mtr$text$mtr$, $mtr$mondat vagy összefoglaló kiegészítése a szöveg alapján$mtr$, 6, 4, $mtr${"id":"2009-okt-kozep-R4","number":4,"kind":"text","layout":"inline","examType":"mondat vagy összefoglaló kiegészítése a szöveg alapján","points":6,"instructions":["Read this description of a near-accident and then read the gapped sentences (24-29) that follow.","Your task is to fill the gaps with one or two words based on the information in the text."],"title":"Driving to the speed limit doesn’t necessarily mean you’re driving safely","body":["Recently while driving on a residential road near my home the following incident occurred. I was in second gear as I turned into the road and in the normal course of events would have perhaps gone up to third to cruise at 30mph.","It was 3pm and there was a lot of activity as children were coming home from school. On the nearside pavement 60 yards away were three girls, 10 to 12 years old, chatting. I’m not sure what it was that rang alarm bells about those three in particular. Maybe it was the intensity of their conversation and the impression that they didn’t appear to be looking around or taking in any other information from their surroundings.","I stayed at 25 mph and moved out as far as I could to the middle of the road. I also placed a finger over the horn and my right heel in front of the brake pedal. As I drew nearer I slowed to 20 mph. When I got within 2 or 3 car lengths from the girls, one turned rapidly, jumped off the pavement and ran across the road. She never looked up or to her right or left − she just went.","I hit the brake and came to a stop about 4 or 5 feet away from her. What saved her life was not what I was doing at the time, which was applying the brakes − but what I had done 50 yards previously; slowing down, moving out and above all, concentrating on her. If I had been doing 30 mph that day I could have hit her. I could have claimed legitimately that I wasn’t speeding and that it wasn’t my fault. The fact that I had slowed to 20 mph guaranteed that whatever she did I could avoid her.","The writer describes how he managed to … avoid… an accident recently.","It was early {{24}} with many children in the street.","Three girls were busy {{25}} on the pavement.","The {{26}} moved further away from the side of the road.","When one girl jumped into the road without looking, the car was moving at a speed of {{27}}.","When the driver stopped, the distance between the girl and the car was only a few {{28}}.","The writer stresses that driving safely means more than just keeping the rules and not {{29}}."],"grading":{"spelling":"lenient"},"items":[{"n":24},{"n":25},{"n":26},{"n":27},{"n":28},{"n":29}]}$mtr$::jsonb, null)
