strict","maxWords":1},"items":[{"n":0,"example":true,"accept":["although"]},{"n":17,"accept":["as"]},{"n":18,"accept":["took"]},{"n":19,"accept":["on"]},{"n":20,"accept":["the"]},{"n":21,"accept":["than"]},{"n":22,"accept":["who"]},{"n":23,"accept":["to","and"]},{"n":24,"accept":["there"]},{"n":25,"accept":["are"]},{"n":26,"accept":["by"]}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
