insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2010-maj-kozep-H3$mtr$, $mtr$2010-maj-kozep$mtr$, $mtr$listening$mtr$, 3, $mtr$text$mtr$, $mtr$mondatkiegészítés hallás után$mtr$, 9, 10, $mtr${"id":"2010-maj-kozep-H3","number":3,"kind":"text","layout":"stems","examType":"mondatkiegészítés hallás után","points":9,"instructions":["In this section, you will hear an American man talking about himself and his activities.","Your task is to complete the sentences with one word or number in each gap.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_10maj_fl.mp3","start":1167.4,"end":1795.3,"clip":"hang/k_angol_10maj_fl_H3.mp3"},"items":[{"n":0,"example":true,"stem":"Zach Anderson is {{gap}} years old.","accept":["35"]},{"n":17,"stem":"His older son is already going to Hungarian {{gap}}."},{"n":18,"stem":"Hungarian people take {{gap}} more seriously than American people."},{"n":19,"stem":"FÉK is a(n) AIDS and drug awareness {{gap}}."},{"n":20,"stem":"Besides AIDS and drug awareness, Zach also talks about topics such as self-image, depression and even {{gap}}."},{"n":21,"stem":"SpeakOut is FÉK's summer English {{gap}}."},{"n":22,"stem":"The only time Zach talks about religion in the high schools he visits is when students ask him about his {{gap}}."},{"n":23,"stem":"The student Zach is talking about felt very {{gap}} because of his drug addiction."},{"n":24,"stem":"The FÉK meetings are held in a Budapest coffee house every {{gap}} night."},{"n":25,"stem":"The boy felt strange in the coffee house because he felt unusually {{gap}}."}],"grading":{"spelling":"lenient"}}$mtr$::jsonb, $mtr${"file":"k_angol_10maj_fl.mp3","start":1167.4,"end":1795.3,"clip":"h