, one of 830 such sites throughout the world."],"grading":{"spelling":"strict","maxWords":1},"items":[{"n":0,"prompt":"attract","example":true,"accept":["attractions"]},{"n":11,"prompt":"threat","accept":["threat"]},{"n":12,"prompt":"sure","accept":["ensure","insure"]},{"n":13,"prompt":"surround","accept":["surrounding"]},{"n":14,"prompt":"complete","accept":["completed","complete"]},{"n":15,"prompt":"fund","accept":["funding","funds"]},{"n":16,"prompt":"embarrass","accept":["embarrassment"]},{"n":17,"prompt":"develop","accept":["developed"]},{"n":18,"prompt":"confident","accept":["confidence"]},{"n":19,"prompt":"consult","accept":["consultation","consultations"]},{"n":20,"prompt":"consider","accept":["consideration"]}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
