insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2010-okt-kozep-H3$mtr$, $mtr$2010-okt-kozep$mtr$, $mtr$listening$mtr$, 3, $mtr$multi$mtr$, $mtr$kettős választás (A, B vagy mindkettő)$mtr$, 7, 10, $mtr${"id":"2010-okt-kozep-H3","number":3,"kind":"multi","layout":"stems","examType":"kettős választás (A, B vagy mindkettő)","points":7,"instructions":["In this section you are going to hear an interview with a scientist about killer bees.","Your task will be to circle the letter(s) of the correct answer(s) in the boxes on the right. Please note that in this task both answers may be correct. However, there is always at least one correct answer. This means you might have to circle one or two letters.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_10okt_fl.mp3","start":1130.59,"end":1795.09,"clip":"hang/k_angol_10okt_fl_H3.mp3"},"items":[{"n":0,"example":true,"stem":"Killer bees …","options":[{"key":"A","text":"is the name of a horror movie."},{"key":"B","text":"are real bees."}],"answer":["B"]},{"n":19,"stem":"Killer bees …","options":[{"key":"A","text":"are coming to the US from the south."},{"key":"B","text":"will arrive in the US in the 2010s."}]},{"n":20,"stem":"Killer bees often attack …","options":[{"key":"A","text":"honey bees."},{"key":"B","text":"in groups."}]},{"n":21,"stem":"When you are attacked, the only thing you can do is ...","options":[{"key":"A","text":"run as fast as you can."},{"key":"B","text":"duck under water."}]},{"n":22,"stem":"The sting of a killer bee ...","options":[{"key":"A","text":"is not more dangerous than a honey bee's."},{"key":"B","text":"causes the death of at least 8,000 people every year."}]},{"n":23,"stem":"Killer bees ...","options":[{"key":"A","text":"make honey just like honey bees."},{"key":"B","text":"eat the honey made by honey bees."}]},{"n":24,"stem":"Honey bees tend to sting when ...","options":[{"key":"A","text":"they are frightened."},{"key":"B","text":"people cough or sneeze."}]},{"n":25,"stem":"Scientists ...","options":[{"key":"A","text":"find it difficult to distinguish killer bees from honey bees."},{"key":"B","text":"have already found a solution to the problem."}]}]}$mtr$::jsonb, $mtr${"file":"k_angol_10okt_fl.mp3","start":1130.59,"end":1795.09,"clip":"hang/k_angol_10okt_fl_H3.mp3"}$mtr$::jsonb)
