insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2011-maj-kozep-H2$mtr$, $mtr$2011-maj-kozep$mtr$, $mtr$listening$mtr$, 2, $mtr$fix$mtr$, $mtr$hibás szó javítása hallás után$mtr$, 8, 9, $mtr${"id":"2011-maj-kozep-H2","number":2,"kind":"fix","layout":"stems","examType":"hibás szó javítása hallás után","points":8,"instructions":["In this part of the test you will hear a news report about a man who wanted to cut the cost of flying.","Your task will be to find one incorrect word (or number) in each of the following sentences, cross it out, and write the correct one on the line after the sentence.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_11maj_fl.mp3","start":775.42,"end":1293.62,"clip":"hang/k_angol_11maj_fl_H2.mp3"},"items":[{"n":0,"text":"The man’s mother and father live in Chicago.","example":true,"fixes":[{"wrong":"chicago","accept":["Dallas"]}]},{"n":9,"text":"He said he decided to visit his parents because he was bored."},{"n":10,"text":"The price of a first class air-ticket would have been higher than the price of sending a crate."},{"n":11,"text":"Mr McKinley had nothing to eat or drink during the 50-hour journey."},{"n":12,"text":"On the plane, somebody noticed that there was a man sitting inside the crate."},{"n":13,"text":"He had lied that the crate contained a computer and books."},{"n":14,"text":"The deliveryman thought there was a dog inside the crate."},{"n":15,"text":"Mr McKinley was arrested and jailed three hours after his trip."},{"n":16,"text":"The District Attorney said Mr McKinley violated the law of security."}],"grading":{"spelling":"lenient"}}$mtr$::jsonb, $mtr${"file":"k_angol_11maj_fl.mp3","start":775.42,"end":1293.62,"clip":"hang/