insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2011-okt-kozep-R1$mtr$, $mtr$2011-okt-kozep$mtr$, $mtr$reading$mtr$, 1, $mtr$bank$mtr$, $mtr$rövid szövegek párosítása állításokhoz$mtr$, 7, 1, $mtr${"id":"2011-okt-kozep-R1","number":1,"kind":"bank","layout":"stems","examType":"rövid szövegek párosítása állításokhoz","points":7,"instructions":["Read what each person said on the phone as an excuse for not going to work, and then read the notes the secretary wrote down.","Match each excuse (1-7) with the notes (A-I). There is an extra sentence that you do not need."],"bank":[{"key":"A","text":"Rajif had to travel abroad."},{"key":"B","text":"Pamela has had an accident."},{"key":"C","text":"Jack is looking for something."},{"key":"D","text":"Paul has been taken to the police station."},{"key":"E","text":"Kate has to visit her grandmother."},{"key":"F","text":"Sue cannot leave the flat."},{"key":"G","text":"Andrew has to find a mechanic."},{"key":"H","text":"Mary didn’t check the calendar."},{"key":"I","text":"Frank overslept."}],"items":[{"n":0,"example":true,"stem":"\"I can't find my shoes. None of the shoes at home are my size.\"","answer":"C"},{"n":1,"stem":"\"I fell over my dog and we had to call an ambulance. I’m still in hospital.\""},{"n":2,"stem":"\"I 've been arrested as a result of mistaken identity. There has been a robbery in the neighbourhood. They won’t let me go.\""},{"n":3,"stem":"\"My car suddenly broke down. I just can’t start the engine, so I’m trying to find someone to repair it.\""},{"n":4,"stem":"\"My cat unplugged my alarm clock. He knocked it off the bedside table. I’ve just woken up.\""},{"n":5,"stem":"\"I had to take my grandmother's ashes to India. I thought I would be back in time but my flight was delayed.\""},{"n":6,"stem":"\"I forgot what day of the week it was. I’ve just realized it’s Monday. It often happens when you have so much to do at home!\""},{"n":7,"stem":"\"My boyfriend's snake’s escaped and I don’t want to risk being bitten. I have to wait in the bedroom until my boyfriend gets home.\""}]}$mtr$::jsonb, null)
