insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2012-maj-kozep-L2$mtr$, $mtr$2012-maj-kozep$mtr$, $mtr$language$mtr$, 2, $mtr$text$mtr$, $mtr$szóképzés (zárójeles szó)$mtr$, 9, 6, $mtr${"id":"2012-maj-kozep-L2","number":2,"kind":"text","layout":"inline","examType":"szóképzés (zárójeles szó)","points":9,"instructions":["You are going to read an article about an adventurous cow. Some words are missing from the text.","Use the words in brackets to form the words that fit in the gaps (9-17).","There might be cases when you do not have to change the word in brackets.","Use only one word for each gap."],"title":"OH DEER!","body":["A cow called Yvonne, who has been on the run in Germany for nearly 10 months, has now found a home with a herd of deer. Dozens of {{0}} have reported sightings and say the cow now {{9}} thinks she’s a deer. Yvonne’s fight for {{10}}","began when she escaped from a Bavarian sausage maker almost 10 months ago. Soon afterwards, the {{11}} press picked up the story and reported that {{12}} had been given permission to shoot the cow. Animal rights campaigners in Germany are protesting against the {{13}} and have since organised a widespread search, which started at the weekend. {{14}} of people travelled to Bavaria to help with the search and even brought {{15}}","cow and its calf with them to help trick Yvonne into leaving the woods. {{16}}, they had no luck and the cow still remains on the run. Michael Aufhauser, an Austrian multimillionaire and animal {{17}}, has agreed to buy the smart animal from the sausage maker as soon as the cow is captured, but it seems Yvonne really enjoys life with the deer.","(http://www.metro.co.uk)"],"grading":{"spelling":"strict"},"items":[{"n":0,"prompt":"witness","example":true,"accept":["witnesses"]},{"n":9,"prompt":"clear"},{"n":10,"prompt":"independent"},{"n":11,"prompt":"local"},{"n":12,"prompt":"hunt"},{"n":13,"prompt":"decide"},{"n":14,"prompt":"hundred"},{"n":15,"prompt":"other"},{"n":16,"prompt":"fortunately"},{"n":17,"prompt":"love"}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2012-maj-kozep-L2$mtr$, $mtr${"id":"2012-maj-kozep-L2","number":2,"kind":"text","layout":"inline","examType":"szóképzés (zárójeles szó)","points":9,"instructions":["You are going to read an article about an adventurous cow. Some words are missing from the text.","Use the words in brackets to form the words that fit in the gaps (9-17).","There might be cases when you do not have to change the word in brackets.","Use only one word for each gap."],"title":"OH DEER!","body":["A cow called Yvonne, who has been on the run in Germany for nearly 10 months, has now found a home with a herd of deer. Dozens of {{0}} have reported sightings and say the cow now {{9}} thinks she’s a deer. Yvonne’s fight for {{10}}","began when she escaped from a Bavarian sausage maker almost 10 months ago. Soon afterwards, the {{11}} press picked up the story and reported that {{12}} had been given permission to shoot the cow. Animal rights campaigners in Germany are protesting against the {{13}} and have since organised a widespread search, which started at the weekend. {{14}} of people travelled to Bavaria to help with the search and even brought {{15}}","cow and its calf with them to help trick Yvonne into leaving the woods. {{16}}, they had no luck and the cow still remains on the run. Michael Aufhauser, an Austrian multimillionaire and animal {{17}}, has agreed to buy the smart animal from the sausage maker as soon as the cow is captured, but it seems Yvonne really enjoys life with the deer.","(http://www.metro.co.uk)"],"grading":{"spelling":"strict","maxWords":1},"items":[{"n":0,"prompt":"witness","example":true,"accept":["witnesses"]},{"n":9,"prompt":"clear","accept":["clearly"]},{"n":10,"prompt":"independent","accept":["independence"]},{"n":11,"prompt":"local","accept":["local"]},{"n":12,"prompt":"hunt","accept":["hunters","huntsmen"]},{"n":13,"prompt":"decide","accept":["decision"]},{"n":14,"prompt":"hundred","accept":["hundreds"]