insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2012-maj-kozep-L3$mtr$, $mtr$2012-maj-kozep$mtr$, $mtr$language$mtr$, 3, $mtr$text$mtr$, $mtr$nyílt cloze (egy szó)$mtr$, 9, 7, $mtr${"id":"2012-maj-kozep-L3","number":3,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":9,"instructions":["You are going to read an article about a famous dog trainer. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (18-26) after the text.","Use only one word in each gap."],"title":"THE DOG WHISPERER","body":["“There is nothing better than taking a pack of 40 dogs to the beach {{0}} a walk,” says Cesar Millan. On a typical day at work he {{18}} on his running shoes and takes a four-hour jog through the mountains with 40 dogs - dogs large and small, young and old, and none {{19}} them on leashes. Amazingly, most of the dogs belong {{20}} him. The rest are troubled dogs sent to Millan to learn good behavior.","Millan, star of the National Geographic Channel’s show Dog Whisperer, has a special gift for working with these animals. “My grandfather taught me at an early age {{21}} to work against nature,” he explains. In nature, dogs are pack animals. They form a group and follow one leader. Millan’s specialty is teaching people {{22}} be pack leaders for their dogs. Studying dogs on the farm {{23}} he spent his childhood, Millan realized they need a {{24}} of exercise to be calm. He explains his approach: “Exercise and discipline first, and then friendship and love!”","At his Dog Psychology Center in Los Angeles, Millan also works with \"dangerous\" dogs {{25}} behavior, often a result of ill-treatment, makes {{26}} difficult to find homes for them. He teaches them to be loving, gentle pets.","(http://kids.nationalgeographic.com)"],"grading":{"spelling":"strict"},"items":[{"n":0,"example":true,"accept":["for"]},{"n":18},{"n":19},{"n":20},{"n":21},{"n":22},{"n":23},{"n":24},{"n":25},{"n":26}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2012-maj-kozep-L3$mtr$, $mtr${"id":"2012-maj-kozep-L3","number":3,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":9,"instructions":["You are going to read an article about a famous dog trainer. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (18-26) after the text.","Use only one word in each gap."],"title":"THE DOG WHISPERER","body":["“There is nothing better than taking a pack of 40 dogs to the beach {{0}} a walk,” says Cesar Millan. On a typical day at work he {{18}} on his running shoes and takes a four-hour jog through the mountains with 40 dogs - dogs large and small, young and old, and none {{19}} them on leashes. Amazingly, most of the dogs belong {{20}} him. The rest are troubled dogs sent to Millan to learn good behavior.","Millan, star of the National Geographic Channel’s show Dog Whisperer, has a special gift for working with these animals. “My grandfather taught me at an early age {{21}} to work against nature,” he explains. In nature, dogs are pack animals. They form a group and follow one leader. Millan’s specialty is teaching people {{22}} be pack leaders for their dogs. Studying dogs on the farm {{23}} he spent his childhood, Millan realized they need a {{24}} of exercise to be calm. He explains his approach: “Exercise and discipline first, and then friendship and love!”","At his Dog Psychology Center in Los Angeles, Millan also works with \"dangerous\" dogs {{25}} behavior, often a result of ill-treatment, makes {{26}} difficult to find homes for them. He teaches them to be loving, gentle pets.","(http://kids.nationalgeographic.com)"],"grading":{"spelling":"strict","maxWords":1},"items":[{"n":0,"example":true,"accept":["for"]},{"n":18,"accept":["puts","pulls"]},{"n":19,"accept":["of"]},{"n":20,"accept":["to"]},{"n":21,"accept":["not","never"]},{"n":22,"accept":["to"]},{"n":23,"accept":["where"]},{"n":24,"accept":