insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2012-okt-kozep-L2$mtr$, $mtr$2012-okt-kozep$mtr$, $mtr$language$mtr$, 2, $mtr$choice$mtr$, $mtr$feleletválasztós szövegkiegészítés (A-D)$mtr$, 10, 6, $mtr${"id":"2012-okt-kozep-L2","number":2,"kind":"choice","layout":"inline","examType":"feleletválasztós szövegkiegészítés (A-D)","points":10,"instructions":["You are going to read an article about crows. Some words are missing from the text.","Choose the most appropriate answer from the options (A-D) for each gap (10-19) in the text."],"title":"A MISUNDERSTOOD BIRD","body":["Crows are often misunderstood, and their intelligence level {{0}} greatly underrated. The crow, however, doesn’t deserve the bad reputation {{10}} we humans have given it.","Humans make and use tools to ensure that {{11}} lives are comfortable. What a lot of people don’t know about the crow {{12}} that this bird has a talent which is actually one of the defining characteristics {{13}} being human: the ability to make and use tools. This surprising discovery suggests that the crow has as high a level of intelligence {{14}} a chimp.","Crows will use sticks to get bugs or other food out of small cracks. They can even bend a piece of wire into a hook {{15}} they need one for the task at hand. They {{16}} to drop hard shelled nuts onto sidewalks to crack them. And if this is {{17}} successful, they throw them into a direct line of traffic so a passing car will crack the nut. In addition to this, they {{18}} changing traffic lights and pedestrian crossing signals for safe time periods when they can get their meal {{19}} the danger of being run over by passing cars.","(http://www.squidoo.com)"],"items":[{"n":0,"options":[{"key":"A","text":"was"},{"key":"B","text":"has"},{"key":"C","text":"is"},{"key":"D","text":"can"}],"example":true,"answer":"C"},{"n":10,"options":[{"key":"A","text":"as"},{"key":"B","text":"that"},{"key":"C","text":"what"},{"key":"D","text":"why"}]},{"n":11,"options":[{"key":"A","text":"there"},{"key":"B","text":"these"},{"key":"C","text":"then"},{"key":"D","text":"their"}]},{"n":12,"options":[{"key":"A","text":"-"},{"key":"B","text":"might"},{"key":"C","text":"is"},{"key":"D","text":"like"}]},{"n":13,"options":[{"key":"A","text":"to"},{"key":"B","text":"how"},{"key":"C","text":"at"},{"key":"D","text":"of"}]},{"n":14,"options":[{"key":"A","text":"than"},{"key":"B","text":"as"},{"key":"C","text":"then"},{"key":"D","text":"but"}]},{"n":15,"options":[{"key":"A","text":"so"},{"key":"B","text":"unless"},{"key":"C","text":"if"},{"key":"D","text":"though"}]},{"n":16,"options":[{"key":"A","text":"have learnt"},{"key":"B","text":"had learnt"},{"key":"C","text":"shall learn"},{"key":"D","text":"would learn"}]},{"n":17,"options":[{"key":"A","text":"fully"},{"key":"B","text":"not"},{"key":"C","text":"ever"},{"key":"D","text":"just"}]},{"n":18,"options":[{"key":"A","text":"watch"},{"key":"B","text":"look"},{"key":"C","text":"see"},{"key":"D","text":"find"}]},{"n":19,"options":[{"key":"A","text":"except"},{"key":"B","text":"accept"},{"key":"C","text":"without"},{"key":"D","text":"over"}]}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2012-okt-kozep-L2$mtr$, $mtr${"id":"2012-okt-kozep-L2","number":2,"kind":"choice","layout":"inline","examType":"feleletválasztós szövegkiegészítés (A-D)","points":10,"instructions":["You are going to read an article about crows. Some words are missing from the text.","Choose the most appropriate answer from the options (A-D) for each gap (10-19) in the text."],"title":"A MISUNDERSTOOD BIRD","body":["Crows are often misunderstood, and their intelligence level {{0}} greatly underrated. The crow, however, doesn’t deserve the bad reputation {{10}} we humans have given it.","Humans make and use tools to ensure that {{11}} lives are comfortable. What a lot of people don’t know about the crow {{12}} that this bird has a talent which is actually one of the defining characteristics {{13}} being human: the ability to make and use tools. This surprising discovery suggests that the crow has as high a level of intelligence {{14}} a chimp.","Crows will use sticks to get bugs or other food out of small cracks. They can even bend a piece of wire into a hook {{15}} they need one for the task at hand. They {{16}} to drop hard shelled nuts onto sidewalks to crack them. And if this is {{17}} successful, they throw them into a direct line of traffic so a passing car will crack the nut. In addition to this, they {{18}} changing traffic lights and pedestrian crossing signals for safe time periods when they can get their meal {{19}} the danger of being run over by passing cars.","(http://www.squidoo.com)"],"items":[{"n":0,"options":[{"key":"A","text":"was"},{"key":"B","text":"has"},{"key":"C","text":"is"},{"key":"D","text":"can"}],"example":true,"answer":"C"},{"n":10,"options":[{"key":"A","text":"as"},{"key":"B","text":"that"},{"key":"C","text":"what"},{"key":"D","text":"why"}],"answer":"B"},{"n":11,"options":[{"key":"A","text":"there"},{"key":"B","text":"these"},{"key":"C","text":"then"},{"key":"D","text":"their"}],"answer":"D"},{"n":12,"options":[{"key":"A","text":"-"},{"key":"B","text":"might"},{"key":"C","text":"is"},{"key":"D","text":"like"}],"answer":"C"},{"n":13,"options":[{"key":"A","text":"to"},{"key":"B","text":"how"},{"key":"C","text":"at"},{"key":"D","text":"of"}],"answer":"D"},{"n":14,"options":[{"key":"A","text":"than"},{"key":"B","text":"as"},{"key":"C","text":"then"},{"key":"D","text":"but"}],"answer":"B"},{"n":15,"options":[{"key":"A","text":"so"},{"key":"B","text":"unless"},{"key":"C","text":"if"},{"key":"D","text":"though"}],"answer":"C"},{"n":16,"options":[{"key":"A","text":"have learnt"},{"key":"B","text":"had learnt"},{"key":"C","text":"shall learn"},{"key":"D","text":"would learn"}],"answer":"A"},{"n":17,"options":[{"key":"A","text":"fully"},{"key":"B","text":"not"},{"key":"C","text":"ever"},{"key":"D","text":"just"}],"answer":"B"},{"n":18,"options":[{"key":"A","text":"watch"},{"key":"B","text":"look"},{"key":"C","text":"see"},{"key":"D","text":"find"}],"answer":"A"},{"n":19,"options":[{"key":"A","text":"except"},{"key":"B","text":"accept"},{"key":"C","text":"without"},{"key":"D","text":"over"}],"answer":"C"}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2012-okt-kozep-L3$mtr$, $mtr$2012-okt-kozep$mtr$, $mtr$language$mtr$, 3, $mtr$text$mtr$, $mtr$nyílt cloze (egy szó)$mtr$, 8, 7, $mtr${"id":"2012-okt-kozep-L3","number":3,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":8,"instructions":["You are going to read an article about a strange emergency call. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (20-27) after the text.","Use only one word in each gap."],"title":"CAT DIALS 999","body":["Police responding to a 999 call from a house in Swansea realised they'd been called {{0}} Ginger the cat when they showed up on the doorstep.","Retired lecturer Howard Moss, 64, got out of bed at 2.30 a.m. to find two policemen on his doorstep answering an emergency call {{20}} had been made from his house. As Mr. Moss insisted he’d been asleep since midnight, the officers searched the house and found Ginger sleeping next {{21}} the phone, which was slightly off the hook. Later, computer checks proved the call had come {{22}} his home in Swansea.","Mr. Moss said: “One {{23}} the officers noticed Ginger asleep on the phone table. The phone was off the hook and Ginger had a paw on the phone keyboard. They quickly came to the only possible conclusion: that {{24}} was Ginger who made the 999 call.”","“Ginger didn’t understand {{25}} all the fuss was about,' Mr. Moss added. “He just jumped down off the table.”","Luckily, South Wales Police had {{26}} good sense of humour. They confirmed that an emergency call {{27}} received in the early hours of Tuesday, which turned out to be the result of a family cat sleeping on the phone. A spokesperson added: “It was a purrfect ending for everyone.”","(http://www.bbc.co.uk)"],"grading":{"spelling":"strict"},"items":[{"n":0,"example":true,"accept":["by"]},{"n":20},{"n":21},{"n":22},{"n":23},{"n":24},{"n":25},{"n":26},{"n":27}]}$mtr$::jsonb, null)
