insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2012-okt-kozep-H2$mtr$, $mtr$2012-okt-kozep$mtr$, $mtr$listening$mtr$, 2, $mtr$choice$mtr$, $mtr$igaz / hamis / a szöveg nem mondja (A/B/C)$mtr$, 9, 9, $mtr${"id":"2012-okt-kozep-H2","number":2,"kind":"choice","layout":"stems","examType":"igaz / hamis / a szöveg nem mondja (A/B/C)","points":9,"instructions":["In this section you will hear an interview with Chris Young, an American country singer.","Your task will be to decide whether the following statements are true, false or we do not know because the text does not say, and write the appropriate letter in the boxes on the right. Write A if the statement is true, write B if the statement is false, and write C if the text does not say.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_12okt_fl.mp3","start":453.77,"end":1060.33,"clip":"hang/k_angol_12okt_fl_H2.mp3"},"items":[{"n":0,"example":true,"stem":"“He’s my dad” is about Chris Young’s stepfather.","answer":"A"},{"n":8,"stem":"Chris Young is an only child."},{"n":9,"stem":"Chris looks very much like his stepdad."},{"n":10,"stem":"Chris Young’s mother knew that Michael would make a good father for Chris."},{"n":11,"stem":"Chris started singing when he was nine."},{"n":12,"stem":"Chris was thinking of becoming a lawyer when he was in high school."},{"n":13,"stem":"Chris is still taking voice lessons."},{"n":14,"stem":"Anyone can go to Chris Young’s Fan Club Party without paying."},{"n":15,"stem":"Chris has never forgotten the words of a song since the dinner party incident."},{"n":16,"stem":"Chris doesn’t think that a contract for a record is important to him."}],"options":[{"key":"A","text":"TRUE"},{"key":"B","text":"FALSE"},{"key":"C","text":"THE TEXT DOES NOT SAY"}]}$mtr$::jsonb, $mtr${"file":"k_angol_12okt_fl.mp3","start":453.77,"end":1060.33,"clip":"hang/k_angol_12okt_fl_H2.mp3"}$mtr$::jsonb)
insert into public.task_keys (task_id, task) values ($mtr$2012-okt-kozep-H2$mtr$, $mtr${"id":"2012-okt-kozep-H2","number":2,"kind":"choice","layout":"stems","examType":"igaz / hamis / a szöveg nem mondja (A/B/C)","points":9,"instructions":["In this section you will hear an interview with Chris Young, an American country singer.","Your task will be to decide whether the following statements are true, false or we do not know because the text does not say, and write the appropriate letter in the boxes on the right. Write A if the statement is true, write B if the statement is false, and write C if the text does not say.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_12okt_fl.mp3","start":453.77,"end":1060.33,"clip":"hang/k_angol_12okt_fl_H2.mp3"},"items":[{"n":0,"example":true,"stem":"“He’s my dad” is about Chris Young’s stepfather.","answer":"A"},{"n":8,"stem":"Chris Young is an only child.","answer":"B"},{"n":9,"stem":"Chris looks very much like his stepdad.","answer":"B"},{"n":10,"stem":"Chris Young’s mother knew that Michael would make a good father for Chris.","answer":"C"},{"n":11,"stem":"Chris started singing when he was nine.","answer":"A"},{"n":12,"stem":"Chris was thinking of becoming a lawyer when he was in high school.","answer":"A"},{"n":13,"stem":"Chris is still taking voice lessons.","answer":"B"},{"n":14,"stem":"Anyone can go to Chris Young’s Fan Club Party without paying.","answer":"A"},{"n":15,"stem":"Chris has never forgotten the words of a song since the dinner party incident.","answer":"C"},{"n":16,"stem":"Chris doesn’t think that a contract for a record is important to him.","answer":"B"}],"options":[{"key":"A","text":"TRUE"},{"key":"B","text":"FALSE"},{"key":"C","text":"THE TEXT DOES NOT SAY"}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2012-okt-kozep-H3$mtr$, $mtr$2012-okt-kozep$mtr$, $mtr$listening$mtr$, 3, $mtr$choice$mtr$, $mtr$feleletválasztás hallás után$mtr$, 8, 10, $mtr${"id":"2012-okt-kozep-H3","number":3,"kind":"choice","layout":"stems","examType":"feleletválasztás hallás után","points":8,"instructions":["In this section you are going to hear Brian Hill, who is giving some tourists information about a national park in Christchurch, New Zealand.","Your task is to write the letter of the correct answer into the boxes on the right.","First, you will have some time to study the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers.","At the end, you will have some more time to check your work."],"audio":{"file":"k_angol_12okt_fl.mp3","start":1060.33,"end":1795.71,"clip":"hang/k_angol_12okt_fl_H3.mp3"},"items":[{"n":0,"example":true,"stem":"Brian Hill works for ….","options":[{"key":"A","text":"Crown Plaza Hotel."},{"key":"B","text":"Willowbank Wildlife Reserve."},{"key":"C","text":"Christchurch Tourist Information Centre."}],"answer":"B"},{"n":17,"stem":"Christchurch…","options":[{"key":"A","text":"is the biggest city in New Zealand."},{"key":"B","text":"has more inhabitants than the capital of New Zealand."},{"key":"C","text":"has more than one million people."}]},{"n":18,"stem":"“Wild New Zealand” shows animals…","options":[{"key":"A","text":"which were originally brought in from other countries."},{"key":"B","text":"like goats and sheep."},{"key":"C","text":"which make up the unique New Zealand wildlife."}]},{"n":19,"stem":"The Kea …","options":[{"key":"A","text":"likes honey."},{"key":"B","text":"is a dinosaur."},{"key":"C","text":"is a Maori symbol."}]},{"n":20,"stem":"You can visit the park …","options":[{"key":"A","text":"before nine in the morning."},{"key":"B","text":"after ten in the evening."},{"key":"C","text":"without a guide."}]},{"n":21,"stem":"The night tours …","options":[{"key":"A","text":"start if there are more than fifteen visitors."},{"key":"B","text":"last for 90 minutes."},{"key":"C","text":"are more interesting than the daytime tours."}]},{"n":22,"stem":"Ko Tane performances …","options":[{"key":"A","text":"are held in the afternoon."},{"key":"B","text":"introduce visitors to Maori culture."},{"key":"C","text":"are rather frightening."}]},{"n":23,"stem":"You must…","options":[{"key":"A","text":"pay for the minibus ride."},{"key":"B","text":"buy tickets at the entrance."},{"key":"C","text":"book tickets in advance."}]},{"n":24,"stem":"Tickets ….","options":[{"key":"A","text":"for students are cheaper than for seniors."},{"key":"B","text":"for six-year-olds cost nothing."},{"key":"C","text":"cost less if you buy them through Brian."}]}]}$mtr$::jsonb, $mtr${"file":"k_angol_12okt_fl.mp3","start":1060.33,"end":1795.71,"clip":"hang/k_angol_12okt_fl_H3.mp3"}$mtr$::jsonb)
