ess.’","(www.dailymail.co.uk)"],"grading":{"spelling":"strict","maxWords":1},"items":[{"n":0,"example":true,"accept":["be"]},{"n":20,"accept":["that","which"]},{"n":21,"accept":["has"]},{"n":22,"accept":["so","meaning"]},{"n":23,"accept":["more"]},{"n":24,"accept":["made","cooked","prepared","produced","baked"]},{"n":25,"accept":["who"]},{"n":26,"accept":["whose"]},{"n":27,"accept":["as","with"]},{"n":28,"accept":["would","might","could"]}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2013-maj-emelt-L4$mtr$, $mtr$2013-maj-emelt$mtr$, $mtr$language$mtr$, 4, $mtr$lines$mtr$, $mtr$soronkénti hibakeresés (felesleges szó vagy helyes sor)$mtr$, 12, 8, $mtr${"id":"2013-maj-emelt-L4","number":4,"kind":"lines","layout":"lines","examType":"soronkénti hibakeresés (felesleges szó vagy helyes sor)","points":12,"instructions":["You are going to read an article about a rare meteorological phenomenon. In most lines there is one word that should not be there. It is either grammatically incorrect or does not fit in with the sense of the text.","Read the text and then copy the extra word in the space provided after each line.","Some lines are correct. Indicate these lines with a tick (9).","The task begins with two examples (0)."],"title":"AUSTRALIAN TOWN HIT BY RAINING FISH","intro":"","items":[{"n":"0a","example":true,"text":"Residents in a remote desert and town in Australia, 326 miles from","answer":"and"},{"n":"0b","example":true,"text":"the nearest river, are recovering after witnessing two days of fish","answer":null},{"n":29,"text":"raining from the sky. Lajamanu in the Northern Territory, which"},{"n":30,"text":"population 669, has yet seen hundreds of small white fish fall from"},{"n":31,"text":"rain clouds with many still alive. Weather experts in Australia"},{"n":32,"text":"believe the fish were sucked it up in a thunderstorm before being"},{"n":33,"text":"dumped over the tiny town. Mark Kersemakers, the highly senior"},{"n":34,"text":"forecaster at the Australian Bureau of Meteorology, said: “It could"},{"n":35,"text":"have been scooped the fish up to 40,000 to 50,000 feet in the air."},{"n":36,"text":"At once they get up into the system they are pretty much frozen."},{"n":37,"text":"After some time they are being released.” It is the third time in"},{"n":38,"text":"less than 30 years so that Lajamanu has been bombarded by falling"},{"n":39,"text":"fish, according to Northern Territory News. The paper was reported"},{"n":40,"text":"a similar extraordinary phenomena in 1974 and 2004."}],"outro":"(www.telegraph.co.uk)"}$mtr$::jsonb, null)
