insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2013-maj-kozep-H1$mtr$, $mtr$2013-maj-kozep$mtr$, $mtr$listening$mtr$, 1, $mtr$text$mtr$, $mtr$rövid válasz hallás után$mtr$, 8, 8, $mtr${"id":"2013-maj-kozep-H1","number":1,"kind":"text","layout":"stems","examType":"rövid válasz hallás után","points":8,"instructions":["In this part of the test you will hear a news report about a pair of twins.","Your task will be to give short answers to the questions below.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_13maj_fl.mp3","start":0,"end":543.62,"clip":"hang/k_angol_13maj_fl_H1.mp3"},"items":[{"n":0,"example":true,"stem":"When were the twins in this story born? {{gap}}","accept":["in the 1930s"]},{"n":1,"stem":"What happened when they were born? {{gap}}"},{"n":2,"stem":"How far away were the two towns where they were raised? {{gap}}"},{"n":3,"stem":"What was different about the names of the twin brothers? {{gap}}"},{"n":4,"stem":"What did both of them do for a living? {{gap}}"},{"n":5,"stem":"What did both of them have a natural talent for? {{gap}}"},{"n":6,"stem":"Where did both of them regularly perform? {{gap}}"},{"n":7,"stem":"Which of their relatives did not have exactly the same name? {{gap}}"},{"n":8,"stem":"How old were the twins when they were eventually reunited? {{gap}}"}],"grading":{"spelling":"keywords"}}$mtr$::jsonb, $mtr${"file":"k_angol_13maj_fl.mp3","start":0,"end":543.62,"clip":"hang/k_angol_13maj_fl_H1.mp3"}$mtr$::jsonb)
