insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2014-maj-emelt-H2$mtr$, $mtr$2014-maj-emelt$mtr$, $mtr$listening$mtr$, 2, $mtr$choice$mtr$, $mtr$igaz / hamis / a szöveg nem mondja (A/B/C)$mtr$, 10, 10, $mtr${"id":"2014-maj-emelt-H2","number":2,"kind":"choice","layout":"stems","examType":"igaz / hamis / a szöveg nem mondja (A/B/C)","points":10,"instructions":["In this section, you will hear the story of the first Ford Mustang.","Your task is to decide whether the following statements are true, false or we do not know because the text does not say, and write the appropriate letter in the boxes on the right. Write A if the statement is true, write B if the statement is false, and write C if the text does not say.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"e_angol_14maj_fl.mp3","start":573.86,"end":1160.61,"clip":"hang/e_angol_14maj_fl_H2.mp3"},"items":[{"n":0,"example":true,"stem":"Gail Wise bought the car two days before it officially went on sale.","answer":"A"},{"n":11,"stem":"Gail had been looking forward to buying a Mustang for months."},{"n":12,"stem":"Gail was used to cars with their roofs taken off."},{"n":13,"stem":"The Ford Thunderbird would have been cheaper."},{"n":14,"stem":"Her dad didn’t trust the salesman very much."},{"n":15,"stem":"The next day Gail drove downtown because she wanted everyone to look at her."},{"n":16,"stem":"Gail’s husband, Tom was an extremely careful driver."},{"n":17,"stem":"Tom put a lot of energy and effort into repairing the car."},{"n":18,"stem":"If it hadn’t been for Tom, Gail would have sold the Mustang."},{"n":19,"stem":"The car hadn’t been exposed to bad weather conditions."},{"n":20,"stem":"Besides taking the Mustang to car shows, the couple never drive their car now."}],"options":[{"key":"A","text":"TRUE"},{"key":"B","text":"FALSE"},{"key":"C","text":"THE TEXT DOES NOT SAY"}]}$mtr$::jsonb, $mtr${"file":"e_angol_14maj_fl.mp3","start":573.86,"end":1160.61,"clip":"hang/e_angol_14maj_fl_H2.mp3"}$mtr$::jsonb)
