insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2014-okt-kozep-H3$mtr$, $mtr$2014-okt-kozep$mtr$, $mtr$listening$mtr$, 3, $mtr$choice$mtr$, $mtr$igaz / hamis / a szöveg nem mondja (A/B/C)$mtr$, 12, 10, $mtr${"id":"2014-okt-kozep-H3","number":3,"kind":"choice","layout":"stems","examType":"igaz / hamis / a szöveg nem mondja (A/B/C)","points":12,"instructions":["In this section you will hear an interview with a president of an American company called ‘Twice is Nice’ or TWIN for short.","Your task will be to decide whether the following statements are true, false or we do not know because the text does not say, and write the appropriate letter in the boxes on the right. Write A if the statement is true, write B if the statement is false, and write C if the text does not say.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_14okt_fl.mp3","start":1206.45,"end":1795.37,"clip":"hang/k_angol_14okt_fl_H3.mp3"},"items":[{"n":0,"example":true,"stem":"The Phoenix-based company deals with cloning cats.","answer":"A"},{"n":14,"stem":"Cats can be cloned even before the death of the donor cat."},{"n":15,"stem":"The biopsy – removing some cells from the donor cat − is done at the company."},{"n":16,"stem":"The fresh new cells are stored on ice."},{"n":17,"stem":"On the average, only one in four implantation attempts is successful."},{"n":18,"stem":"The new cat is born about 60 days after a successful implantation."},{"n":19,"stem":"A kitten cannot eat solid food for about 8 months."},{"n":20,"stem":"The price of a clone of your cat is $50,000."},{"n":21,"stem":"You have to pay the full price only when you get the new cat."},{"n":22,"stem":"The interviewer thinks that this price is rather high."},{"n":23,"stem":"The company does about a hundred clonings a year at the moment."},{"n":24,"stem":"The company has been experimenting with cloning dogs for 5 years."},{"n":25,"stem":"TWIN expects to be able to clone dogs in about a year."}],"options":[{"key":"A","text":"TRUE"},{"key":"B","text":"FALSE"},{"key":"C","text":"THE TEXT DOES NOT SAY"}]}$mtr$::jsonb, $mtr${"file":"k_angol_14okt_fl.mp3","start":1206.45,"end":1795.37,"clip":"hang/k_angol_14okt_fl_H3.mp3"}$mtr$::jsonb)
