insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2015-maj-emelt-H1$mtr$, $mtr$2015-maj-emelt$mtr$, $mtr$listening$mtr$, 1, $mtr$multi$mtr$, $mtr$kettős választás (A, B vagy mindkettő)$mtr$, 7, 9, $mtr${"id":"2015-maj-emelt-H1","number":1,"kind":"multi","layout":"stems","examType":"kettős választás (A, B vagy mindkettő)","points":7,"instructions":["In this section you will hear a radio report about what we might be putting on our plates in 20 years’ time.","Your task will be to circle the letter or letters of the correct answer or answers in the boxes on the right. Please note that in this task both answers may be correct. This means that you will have to circle either A or B, or both A and B.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"e_angol_15maj_fl.mp3","start":0,"end":510.04,"clip":"hang/e_angol_15maj_fl_H1.mp3"},"items":[{"n":0,"example":true,"stem":"The issue of how we will feed ourselves in the future seriously worries organisations such as the ...","options":[{"key":"A","text":"United Nations."},{"key":"B","text":"British government."}],"answer":["A","B"]},{"n":1,"stem":"The price of meat might be …","options":[{"key":"A","text":"twice as much as it is now in a few years’ time."},{"key":"B","text":"one of the reasons why we are looking for new food sources."}]},{"n":2,"stem":"Insects might be a good solution because they …","options":[{"key":"A","text":"are just as nourishing as meat."},{"key":"B","text":"contain more protein than meat."}]},{"n":3,"stem":"Compared to raising cattle, raising insects is …","options":[{"key":"A","text":"not as expensive."},{"key":"B","text":"more environmentally friendly."}]},{"n":4,"stem":"There are probably about 1,400 species of insects that are …","options":[{"key":"A","text":"suitable for eating."},{"key":"B","text":"part of a diet somewhere in the world."}]},{"n":5,"stem":"Morgaine Gaye says that insects will probably be …","options":[{"key":"A","text":"roasted and served on a plate."},{"key":"B","text":"used as ingredients in burgers and sausages."}]},{"n":6,"stem":"According to Morgaine Gaye …","options":[{"key":"A","text":"every third person in the world regularly eats insects."},{"key":"B","text":"wasps are a Japanese speciality."}]},{"n":7,"stem":"Morgaine Gaye says that insects will become a popular part of Western diet if …","options":[{"key":"A","text":"people cannot see that they are eating insects."},{"key":"B","text":"they are given a new name."}]}]}$mtr$::jsonb, $mtr${"file":"e_angol_15maj_fl.mp3","start":0,"end":510.04,"clip":"hang/e_angol_15maj_fl_H1.mp3"}$mtr$::jsonb)
