insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2015-okt-emelt-H1$mtr$, $mtr$2015-okt-emelt$mtr$, $mtr$listening$mtr$, 1, $mtr$choice$mtr$, $mtr$igaz / hamis / a szöveg nem mondja (A/B/C)$mtr$, 12, 9, $mtr${"id":"2015-okt-emelt-H1","number":1,"kind":"choice","layout":"stems","examType":"igaz / hamis / a szöveg nem mondja (A/B/C)","points":12,"instructions":["In this section you will hear some information about the White House in Washington D.C.","Your task will be to decide whether the following statements are true, false or we do not know because the text does not say, and write the appropriate letter in the boxes on the right. Write A if the statement is true, write B if the statement is false, and write C if the text does not say.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"e_angol_15okt_fl.mp3","start":0,"end":713.94,"clip":"hang/e_angol_15okt_fl_H1.mp3"},"items":[{"n":0,"example":true,"stem":"The decision about the capital city of the U.S.A. was made in the late 1700s.","answer":"A"},{"n":1,"stem":"The spot for the new city was chosen by George Washington himself."},{"n":2,"stem":"The exact site for the “President’s House” was picked by George Washington himself."},{"n":3,"stem":"Thomas Jefferson didn’t use his real name to enter for the competition for the best design."},{"n":4,"stem":"After winning the contest, James Hoban moved to the U.S. from Ireland."},{"n":5,"stem":"The first president who actually lived in the building was George Washington."},{"n":6,"stem":"British soldiers set fire to the building in 1814."},{"n":7,"stem":"During the consecutive renovations, presidents were always anxious to preserve the original character of the building."},{"n":8,"stem":"Jacqueline Kennedy spent her own money to redecorate the White House."},{"n":9,"stem":"The building got its current official name only in the 19th century."},{"n":10,"stem":"The president and his family have two floors exclusively for their private use."},{"n":11,"stem":"The White House gives at least two dinner parties every week."},{"n":12,"stem":"About 6,000 people visit the White House every day."}],"options":[{"key":"A","text":"TRUE"},{"key":"B","text":"FALSE"},{"key":"C","text":"THE TEXT DOES NOT SAY"}]}$mtr$::jsonb, $mtr${"file":"e_angol_15okt_fl.mp3","start":0,"end":713.94,"clip":"hang/e_angol_15okt_fl_H1.mp3"}$mtr$::jsonb)
insert into public.task_keys (task_id, task) values ($mtr$2015-okt-emelt-H1$mtr$, $mtr${"id":"2015-okt-emelt-H1","number":1,"kind":"choice","layout":"stems","examType":"igaz / hamis / a szöveg nem mondja (A/B/C)","points":12,"instructions":["In this section you will hear some information about the White House in Washington D.C.","Your task will be to decide whether the following statements are true, false or we do not know because the text does not say, and write the appropriate letter in the boxes on the right. Write A if the statement is true, write B if the statement is false, and write C if the text does not say.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"e_angol_15okt_fl.mp3","start":0,"end":713.94,"clip":"hang/e_angol_15okt_fl_H1.mp3"},"items":[{"n":0,"example":true,"stem":"The decision about the capital city of the U.S.A. was made in the late 1700s.","answer":"A"},{"n":1,"stem":"The spot for the new city was chosen by George Washington himself.","answer":"A"},{"n":2,"stem":"The exact site for the “President’s House” was picked by George Washington himself.","answer":"B"},{"n":3,"stem":"Thomas Jefferson didn’t use his real name to enter for the competition for the best design.","answer":"A"},{"n":4,"stem":"After winning the contest, James Hoban moved to the U.S. from Ireland.","answer":"C"},{"n":5,"stem":"The first president who actually lived in the building was George Washington.","answer":"B"},{"n":6,"stem":"British soldiers set fire to the building in 1814.","answer":"A"},{"n":7,"stem":"During the consecutive renovations, presidents were always anxious to preserve the original character of the building.","answer":"B"},{"n":8,"stem":"Jacqueline Kennedy spent her own money to redecorate the White House.","answer":"C"},{"n":9,"stem":"The building got its current official name only in the 19th century.","answer":"B"},{"n":10,"stem":"The president and his family have two floors exclusively for their private use.","answer":"A"},{"n":11,"stem":"The White House gives at least two dinner parties every week.","answer":"C"},{"n":12,"stem":"About 6,000 people visit the White House every day.","answer":"A"}],"options":[{"key":"A","text":"TRUE"},{"key":"B","text":"FALSE"},{"key":"C","text":"THE TEXT DOES NOT SAY"}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
