insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2015-okt-kozep-L2$mtr$, $mtr$2015-okt-kozep$mtr$, $mtr$language$mtr$, 2, $mtr$bank$mtr$, $mtr$szóbank (szavak visszahelyezése)$mtr$, 11, 6, $mtr${"id":"2015-okt-kozep-L2","number":2,"kind":"bank","layout":"inline","examType":"szóbank (szavak visszahelyezése)","points":11,"instructions":["You are going to read an article about the world’s ugliest animal. Some words are missing from the text.","Your task is to choose the most appropriate word from the list (A-N) for each gap (11-21) in the text. Write the letter of the appropriate word in the white box.","Each word can be used once.","There is one extra word that you do not need to use."],"title":"BLOBFISH CROWNED THE WORLD’S UGLIEST ANIMAL","body":["Everyone goes crazy for pandas, but what about the {{0}} aesthetic wonders of the animal world? The Ugly Animal Preservation Society (UAPS) aims to support endangered animals that are unpleasant to look {{11}} through a national campaign that combines comedy and education. In an online competition, the blobfish, a fat, gelatinous mass {{12}} near the southeast coast of Australia, was voted as the world’s ugliest animal and {{13}} the society’s official mascot. UAPS chief biologist Simon Watt {{14}} us more: ‘The campaign’s aim is to give ugly animals {{15}} by extinction a voice, and it has been supported by {{16}} celebrities as Stephen Fry and Simon Pegg. There are {{17}} many people trying to save cute animals. Ugly animals need {{18}} attention than cute animals. We’ve needed an ugly face for endangered animals {{19}} a long time and I’ve been amazed by the public’s reaction.’ UAPS {{20}} the campaign will encourage young people to get involved in conservation projects and {{21}} deal with the problem of nature’s aesthetically-challenged animals.","(http://metro.co.uk)"],"bank":[{"key":"A","text":"AT"},{"key":"B","text":"BECAME"},{"key":"C","text":"LESS"},{"key":"D","text":"FOR"},{"key":"E","text":"FOUND"},{"key":"F","text":"HELP"},{"key":"G","text":"HOPES"},{"key":"H","text":"MORE"},{"key":"I","text":"SUCH"},{"key":"K","text":"TALKED"},{"key":"L","text":"THREATENED"},{"key":"M","text":"TOLD"},{"key":"N","text":"TOO"}],"items":[{"n":0,"example":true,"answer":"C"},{"n":11},{"n":12},{"n":13},{"n":14},{"n":15},{"n":16},{"n":17},{"n":18},{"n":19},{"n":20},{"n":21}]}$mtr$::jsonb, null)
