insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2016-maj-kozep-H2$mtr$, $mtr$2016-maj-kozep$mtr$, $mtr$listening$mtr$, 2, $mtr$text$mtr$, $mtr$rövid válasz hallás után$mtr$, 9, 9, $mtr${"id":"2016-maj-kozep-H2","number":2,"kind":"text","layout":"stems","examType":"rövid válasz hallás után","points":9,"instructions":["In this section, you are going to hear a true story about Muhammad Ali, the famous boxer.","Your task is to give short answers to the questions below using the exact words you hear.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_16maj_fl.mp3","start":474.09,"end":1023.66,"clip":"hang/k_angol_16maj_fl_H2.mp3"},"items":[{"n":0,"example":true,"stem":"When did Ali change his name? In {{gap}}","accept":["1964"]},{"n":9,"stem":"What was the religious movement that Ali joined called? It was called the {{gap}}"},{"n":10,"stem":"What two animals did Ali mention in his statement? He mentioned a(n) {{gap}} and a(n) {{gap}}","gapCount":2},{"n":11,"stem":"What did Ali and his friend decide to visit? They decided to visit a(n) {{gap}}"},{"n":12,"stem":"Where did they leave their bikes? They left their bikes {{gap}}"},{"n":13,"stem":"What did they eat? They ate hot dogs and {{gap}}"},{"n":14,"stem":"Where in the basement did Ali find Joe Martin? He found him in the {{gap}}"},{"n":15,"stem":"After they filled out a police report, what did Joe Martin hand Ali? He handed him a(n) {{gap}}"},{"n":16,"stem":"What did Joe Martin teach Ali? He taught him the {{gap}}"},{"n":17,"stem":"What did Ali win in 1960? He won {{gap}}"}],"grading":{"spelling":"keywords"}}$mtr$::jsonb, $mtr${"file":"k_angol_16maj_fl.mp3","start":474.09,"end":1023.66,"clip":"ha