insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2016-okt-emelt-L2$mtr$, $mtr$2016-okt-emelt$mtr$, $mtr$language$mtr$, 2, $mtr$text$mtr$, $mtr$nyílt cloze (egy szó)$mtr$, 12, 6, $mtr${"id":"2016-okt-emelt-L2","number":2,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":12,"instructions":["You are going to read an article about a box of precious stones that lay hidden in the French Alps for decades. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (11-22) after the text.","Use only one word in each gap."],"title":"FROZEN TREASURE FOUND IN THE FRENCH ALPS","body":["A treasure of precious jewels has been found {{0}} a young alpinist on the ice caps of Mont Blanc, {{11}} it was probably lost decades ago among the wreckage of a crashed airliner.","Local police chief Sylvain Merly confirmed that about a hundred small precious stones were found in a metallic box in the ice caps known {{12}} Bossons. Merly said the stones were separated in plastic bags that were stamped \"Made in India.\" A local jeweler estimates the treasure to {{13}} worth around $250,000. The diamonds, emeralds, sapphires and rubies are believed {{14}} have come from one of two Air India planes {{15}} crashed in the French Alps in 1950 and 1966.","The young male climber who stumbled across the lost treasure wishes to {{16}} anonymous. French authorities are contacting {{17}} Indian counterparts to trace the owners of the jewels. {{18}} someone claims the gems, they will be returned to the young mountaineer.","Merly said that as the ice caps change, debris from the plane crashes rises to the surface periodically. Climbers have encountered all manner of artefacts including newspapers, a jet engine and human remains {{19}} the years. In 2012, a bag of Indian diplomatic mail marked \"ministry of external affairs\" {{20}} discovered.","Arnaud Christmann, another alpinist familiar {{21}} the area, said he feared the discovery would trigger \"a gold rush\" to the area. He asked \"for some respect {{22}} the crash victims\" and regretted the \"spirit of treasure hunters\" that motivated some mountain climbers.","(www.nbcnews.com)"],"grading":{"spelling":"strict"},"items":[{"n":0,"example":true,"accept":["by"]},{"n":11},{"n":12},{"n":13},{"n":14},{"n":15},{"n":16},{"n":17},{"n":18},{"n":19},{"n":20},{"n":21},{"n":22}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2016-okt-emelt-L2$mtr$, $mtr${"id":"2016-okt-emelt-L2","number":2,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":12,"instructions":["You are going to read an article about a box of precious stones that lay hidden in the French Alps for decades. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (11-22) after the text.","Use only one word in each gap."],"title":"FROZEN TREASURE FOUND IN THE FRENCH ALPS","body":["A treasure of precious jewels has been found {{0}} a young alpinist on the ice caps of Mont Blanc, {{11}} it was probably lost decades ago among the wreckage of a crashed airliner.","Local police chief Sylvain Merly confirmed that about a hundred small precious stones were found in a metallic box in the ice caps known {{12}} Bossons. Merly said the stones were separated in plastic bags that were stamped \"Made in India.\" A local jeweler estimates the treasure to {{13}} worth around $250,000. The diamonds, emeralds, sapphires and rubies are believed {{14}} have come from one of two Air India planes {{15}} crashed in the French Alps in 1950 and 1966.","The young male climber who stumbled across the lost treasure wishes to {{16}} anonymous. French authorities are contacting {{17}} Indian counterparts to trace the owners of the jewels. {{18}} someone claims the gems, they will be returned to the young mountaineer.","Merly said that as the ice caps change, debris from the plane crashes rises to the surface periodically. Climbers have encountered all manner of artefacts including newspapers, a jet engine and human remains {{19}} the years. In 2012, a bag of Indian diplomatic mail marked \"ministry of external affairs\" {{20}} discovered.","Arnaud Christmann, another alpinist familiar {{21}} the area, said he feared the discovery would trigger \"a gold rush\" to the area. He asked \"for some respect {{22}} the crash victims\" and regretted the \"spirit of treasure hunters\" that motivated some mountain climbers.","(www.nbcnews.com)"],"grading":{"spelling":"strict","maxWords":1},"items":[{"n":0,"example":true,"accept":["by"]},{"n":11,"accept":["where","and"]},{"n":12,"accept":["as"]},{"n":13,"accept":["be"]},{"n":14,"accept":["to"]},{"n":15,"accept":["that","which"]},{"n":16,"accept":["remain","stay"]},{"n":17,"accept":["their"]},{"n":18,"accept":["unless"]},{"n":19,"accept":["over"]},{"n":20,"accept":["was"]},{"n":21,"accept":["with"]},{"n":22,"accept":["for"]}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2016-okt-emelt-L3$mtr$, $mtr$2016-okt-emelt$mtr$, $mtr$language$mtr$, 3, $mtr$choice$mtr$, $mtr$feleletválasztós szövegkiegészítés (A-D)$mtr$, 10, 7, $mtr${"id":"2016-okt-emelt-L3","number":3,"kind":"choice","layout":"inline","examType":"feleletválasztós szövegkiegészítés (A-D)","points":10,"instructions":["You are going to read an article about the history of tea bags. Some words are missing from the text.","Choose the most appropriate answer from the options (A-D) for each gap (23-32) in the text."],"title":"THE TEA BAG","body":["The purpose of the tea bag is {{0}} in the belief that for tea to taste its best, the leaves {{23}} to be removed from the hot water at the end of a specific brewing period. The earliest examples of removable infusing devices for holding tea {{24}} metal tea eggs and tea balls.","Needless {{25}}, it was in America, with its love of labour-saving devices, that tea bags were first developed. In 1908, Thomas Sullivan, a New York tea merchant, started to send samples of tea to his customers in small silken bags. Some assumed that these were {{26}} to be used in the same way as the metal infusers, by putting the entire bag into the pot, rather than {{27}} out the contents. It was thus {{28}} accident that the tea bag was born! During the 1920s tea bags were developed for commercial production, and they grew in popularity in the USA.","{{29}} Americans took to tea bags with enthusiasm, the British were naturally cautious about such a radical change in their tea-making methods. The material shortages of World War Two also delayed the mass adoption of tea bags in Britain, and it was not until the 1950s that they really {{30}} off. The 1950s were a time when all sorts of household gadgets {{31}} promoted as eliminating tedious household chores. Tea bags gained popularity {{32}} they removed the need to empty out the used tea leaves from the pot. In the early 1960s, tea bags made up less than 3 per cent of the British market but by 2007 this had increased to 96 per cent.","(www.tea.co.uk)"],"items":[{"n":0,"options":[{"key":"A","text":"based"},{"key":"B","text":"found"},{"key":"C","text":"rooted"},{"key":"D","text":"made"}],"example":true,"answer":"C"},{"n":23,"options":[{"key":"A","text":"has"},{"key":"B","text":"should"},{"key":"C","text":"ought"},{"key":"D","text":"must"}]},{"n":24,"options":[{"key":"A","text":"was"},{"key":"B","text":"had been"},{"key":"C","text":"have been"},{"key":"D","text":"were"}]},{"n":25,"options":[{"key":"A","text":"telling"},{"key":"B","text":"saying"},{"key":"C","text":"to tell"},{"key":"D","text":"to say"}]},{"n":26,"options":[{"key":"A","text":"suggested"},{"key":"B","text":"told"},{"key":"C","text":"supposed"},{"key":"D","text":"preferred"}]},{"n":27,"options":[{"key":"A","text":"emptied"},{"key":"B","text":"emptying"},{"key":"C","text":"have emptied"},{"key":"D","text":"to empty"}]},{"n":28,"options":[{"key":"A","text":"through"},{"key":"B","text":"with"},{"key":"C","text":"by"},{"key":"D","text":"from"}]},{"n":29,"options":[{"key":"A","text":"But while"},{"key":"B","text":"However,"},{"key":"C","text":"In spite of"},{"key":"D","text":"Nonetheless,"}]},{"n":30,"options":[{"key":"A","text":"got"},{"key":"B","text":"took"},{"key":"C","text":"put"},{"key":"D","text":"went"}]},{"n":31,"options":[{"key":"A","text":"had been"},{"key":"B","text":"should be"},{"key":"C","text":"would have"},{"key":"D","text":"were being"}]},{"n":32,"options":[{"key":"A","text":"since"},{"key":"B","text":"because of"},{"key":"C","text":"consequently"},{"key":"D","text":"despite"}]}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2016-okt-emelt-L3$mtr$, $mtr${"id":"2016-okt-emelt-L3","number":3,"kind":"choice","layout":"inline","examType":"feleletválasztós szövegkiegészítés (A-D)","points":10,"instructions":["You are going to read an article about the history of tea bags. Some words are missing from the text.","Choose the most appropriate answer from the options (A-D) for each gap (23-32) in the text."],"title":"THE TEA BAG","body":["The purpose of the tea bag is {{0}} in the belief that for tea to taste its best, the leaves {{23}} to be removed from the hot water at the end of a specific brewing period. The earliest examples of removable infusing devices for holding tea {{24}} metal tea eggs and tea balls.","Needless {{25}}, it was in America, with its love of labour-saving devices, that tea bags were first developed. In 1908, Thomas Sullivan, a New York tea merchant, started to send samples of tea to his customers in small silken bags. Some assumed that these were {{26}} to be used in the same way as the metal infusers, by putting the entire bag into the pot, rather than {{27}} out the contents. It was thus {{28}} accident that the tea bag was born! During the 1920s tea bags were developed for commercial production, and they grew in popularity in the USA.","{{29}} Americans took to tea bags with enthusiasm, the British were naturally cautious about such a radical change in their tea-making methods. The material shortages of World War Two also delayed the mass adoption of tea bags in Britain, and it was not until the 1950s that they really {{30}} off. The 1950s were a time when all sorts of household gadgets {{31}} promoted as eliminating tedious household chores. Tea bags gained popularity {{32}} they removed the need to empty out the used tea leaves from the pot. In the early 1960s, tea bags made up less than 3 per cent of the British market but by 2007 this had increased to 96 per cent.","(www.tea.co.uk)"],"items":[{"n":0,"options":[{"key":"A","text":"based"},{"key":"B","text":"found"},{"key":"C","text":"rooted"},{"key":"D","text":"made"}],"example":true,"answer":"C"},{"n":23,"options":[{"key":"A","text":"has"},{"key":"B","text":"should"},{"key":"C","text":"ought"},{"key":"D","text":"must"}],"answer":"C"},{"n":24,"options":[{"key":"A","text":"was"},{"key":"B","text":"had been"},{"key":"C","text":"have been"},{"key":"D","text":"were"}],"answer":"D"},{"n":25,"options":[{"key":"A","text":"telling"},{"key":"B","text":"saying"},{"key":"C","text":"to tell"},{"key":"D","text":"to say"}],"answer":"D"},{"n":26,"options":[{"key":"A","text":"suggested"},{"key":"B","text":"told"},{"key":"C","text":"supposed"},{"key":"D","text":"preferred"}],"answer":"C"},{"n":27,"options":[{"key":"A","text":"emptied"},{"key":"B","text":"emptying"},{"key":"C","text":"have emptied"},{"key":"D","text":"to empty"}],"answer":"B"},{"n":28,"options":[{"key":"A","text":"through"},{"key":"B","text":"with"},{"key":"C","text":"by"},{"key":"D","text":"from"}],"answer":"C"},{"n":29,"options":[{"key":"A","text":"But while"},{"key":"B","text":"However,"},{"key":"C","text":"In spite of"},{"key":"D","text":"Nonetheless,"}],"answer":"A"},{"n":30,"options":[{"key":"A","text":"got"},{"key":"B","text":"took"},{"key":"C","text":"put"},{"key":"D","text":"went"}],"answer":"B"},{"n":31,"options":[{"key":"A","text":"had been"},{"key":"B","text":"should be"},{"key":"C","text":"would have"},{"key":"D","text":"were being"}],"answer":"D"},{"n":32,"options":[{"key":"A","text":"since"},{"key":"B","text":"because of"},{"key":"C","text":"consequently"},{"key":"D","text":"despite"}],"answer":"A"}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2016-okt-emelt-L4$mtr$, $mtr$2016-okt-emelt$mtr$, $mtr$language$mtr$, 4, $mtr$lines$mtr$, $mtr$soronkénti hibakeresés (felesleges szó vagy helyes sor)$mtr$, 13, 8, $mtr${"id":"2016-okt-emelt-L4","number":4,"kind":"lines","layout":"lines","examType":"soronkénti hibakeresés (felesleges szó vagy helyes sor)","points":13,"instructions":["You are going to read the story of Lady Godiva, an English noblewoman who lived in the 11th century. In most lines there is one word that should not be there. It is either grammatically incorrect or does not fit in with the sense of the text.","Read the text and then copy the extra word in the space provided after each line.","Some lines are correct. Indicate these lines with a tick ().","The task begins with two examples (0)."],"title":"LADY GODIVA","intro":"","items":[{"n":"0a","example":true,"text":"Lady Godiva irritated her husband by persistently begging to him","answer":"to"},{"n":"0b","example":true,"text":"to reduce the taxes on the people of Coventry. To silence her, he","answer":null},{"n":33,"text":"declared he would rather do so only if she rode naked through the"},{"n":34,"text":"town's market place. The 17-year-oldGodiva called his bluff and by"},{"n":35,"text":"the next day, she set out for the town on horseback, completelynaked."},{"n":36,"text":"However, by concealing the most of her body with her long, thick"},{"n":37,"text":"hair, she preserved both of her own modesty and her husband's"},{"n":38,"text":"pride, enabling for him to reduce the taxes without loss of face."},{"n":39,"text":"A later version of this tale suggests that how Lady Godiva told"},{"n":40,"text":"the townspeople so that they should remain indoors, behind"},{"n":41,"text":"shuttered windows, if they wanted their taxes be reduced."},{"n":42,"text":"Everyone had obeyed except a tailor called Tom. This curious"},{"n":43,"text":"citizen who peeped through his curtains he was instantly struck"},{"n":44,"text":"blind (or, in some versions, dead). Poor Tom, blind or dead as the"},{"n":45,"text":"case may be, left the phrase \"a peeping Tom\" as if a permanent"}],"outro":"legacy to the English language. (Pawprints anecdotes)"}$mtr$::jsonb, null)
