insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2016-okt-kozep-L3$mtr$, $mtr$2016-okt-kozep$mtr$, $mtr$language$mtr$, 3, $mtr$text$mtr$, $mtr$nyílt cloze (egy szó)$mtr$, 11, 7, $mtr${"id":"2016-okt-kozep-L3","number":3,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":11,"instructions":["You are going to read an article about a duchess who is planning to give away her fortune because she wants to marry a public servant. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (19-29) after the text.","Use only one word in each gap."],"title":"IN THE NAME OF LOVE","body":["The Duchess of Alba, who is {{0}} of the richest women in Spain, owns a dozen castles whose walls are hung with works {{19}} Goya, Velazquez and Titian, and is a distant relative of Winston Churchill and Diana, Princess of Wales. Now, however, {{20}} 18th Duchess of Alba is giving away her enormous personal fortune in {{21}} to be free to marry a public servant.","According to Guinness World Records, Maria del Rosario has more titles {{22}} any noble on Earth: she is a duchess seven times, a countess 22 and a marquesa 24 times. As head of the 539-year-old House of Alba, her privileges include {{23}} having to kneel before the Pope {{24}} the right to ride on horseback into Seville cathedral.","But the children of the duchess, 85, {{25}} until now blocked her plans to marry Alfonso Diez, 24 years her junior. Her six children, who – as she likes to point out – are all divorced, {{26}} all born from her first marriage. She plans to overcome her children's opposition by giving {{27}} their inheritance in advance.","The duchess's personal wealth {{28}} estimated at around $2 billion, and she has {{29}} able to give her children a palace each, as well as a chunk of the thousands of hectares of Spain that she owns.","(Guardian News & Media)"],"grading":{"spelling":"strict"},"items":[{"n":0,"example":true,"accept":["one"]},{"n":19},{"n":20},{"n":21},{"n":22},{"n":23},{"n":24},{"n":25},{"n":26},{"n":27},{"n":28},{"n":29}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2016-okt-kozep-L3$mtr$, $mtr${"id":"2016-okt-kozep-L3","number":3,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":11,"instructions":["You are going to read an article about a duchess who is planning to give away her fortune because she wants to marry a public servant. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (19-29) after the text.","Use only one word in each gap."],"title":"IN THE NAME OF LOVE","body":["The Duchess of Alba, who is {{0}} of the richest women in Spain, owns a dozen castles whose walls are hung with works {{19}} Goya, Velazquez and Titian, and is a distant relative of Winston Churchill and Diana, Princess of Wales. Now, however, {{20}} 18th Duchess of Alba is giving away her enormous personal fortune in {{21}} to be free to marry a public servant.","According to Guinness World Records, Maria del Rosario has more titles {{22}} any noble on Earth: she is a duchess seven times, a countess 22 and a marquesa 24 times. As head of the 539-year-old House of Alba, her privileges include {{23}} having to kneel before the Pope {{24}} the right to ride on horseback into Seville cathedral.","But the children of the duchess, 85, {{25}} until now blocked her plans to marry Alfonso Diez, 24 years her junior. Her six children, who – as she likes to point out – are all divorced, {{26}} all born from her first marriage. She plans to overcome her children's opposition by giving {{27}} their inheritance in advance.","The duchess's personal wealth {{28}} estimated at around $2 billion, and she has {{29}} able to give her children a palace each, as well as a chunk of the thousands of hectares of Spain that she owns.","(Guardian News & Media)"],"grading":{"spelling":"strict","maxWords":1},"items":[{"n":0,"example":true,"accept":["one"]},{"n":19,"accept":["by"]},{"n":20,"accept":["the"]},{"n":21,"accept":["order"]},{"n":22,"accept":["than"]},{"n":23,"accept":["not","never"]},{"n":24,"accept":["and","plus"]},{"n":25,"accept":["have"]},{"n":26,"accept":["were"]},{"n":27,"accept":["them"]},{"n":28,"accept":["is"]},{"n":29,"accept":["been"]}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
