insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2016-okt-kozep-H3$mtr$, $mtr$2016-okt-kozep$mtr$, $mtr$listening$mtr$, 3, $mtr$text$mtr$, $mtr$rövid válasz hallás után$mtr$, 8, 10, $mtr${"id":"2016-okt-kozep-H3","number":3,"kind":"text","layout":"stems","examType":"rövid válasz hallás után","points":8,"instructions":["In this section, you are going to hear a strange but true story about an aggressive cat called Cuppy.","Your task will be to give short answers to the questions below using the exact words you hear.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_16okt_fl.mp3","start":1220.09,"end":1795.4,"clip":"hang/k_angol_16okt_fl_H3.mp3"},"items":[{"n":0,"example":true,"stem":"Where was the incident first shown? It was shown {{gap}}","accept":["on TV Stateside"]},{"n":18,"stem":"What number did the two women call? They called {{gap}}"},{"n":19,"stem":"What piece of clothing did Cuppy attack? The younger woman’s {{gap}}"},{"n":20,"stem":"Where did the two women hide? In the {{gap}}"},{"n":21,"stem":"What department did the police suggest they should call? The {{gap}}"},{"n":22,"stem":"What did Cuppy refuse to do? To {{gap}}"},{"n":23,"stem":"Why did Cuppy finally leave the house? Because he {{gap}}"},{"n":24,"stem":"How long had Cuppy been with the family? For {{gap}}"},{"n":25,"stem":"Who would be outraged if the owners carried out their plan? Animal {{gap}}"}],"grading":{"spelling":"keywords"}}$mtr$::jsonb, $mtr${"file":"k_angol_16okt_fl.mp3","start":1220.09,"end":1795.4,"clip":"hang/k_angol_16okt_fl_H3.mp3"}$mtr$::jsonb)
