insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2017-maj-emelt-L2$mtr$, $mtr$2017-maj-emelt$mtr$, $mtr$language$mtr$, 2, $mtr$choice$mtr$, $mtr$feleletválasztós szövegkiegészítés (A-D)$mtr$, 9, 6, $mtr${"id":"2017-maj-emelt-L2","number":2,"kind":"choice","layout":"inline","examType":"feleletválasztós szövegkiegészítés (A-D)","points":9,"instructions":["You are going to read an article about a newly revealed interest of the Queen. Some words are missing from the text.","Choose the most appropriate answer from the options (A-D) for each gap (9-17) in the text."],"title":"LOCH NESS MONSTER WAS NEARLY NAMED AFTER THE QUEEN","body":["The Loch Ness Monster could have been named after the Queen if it was ever found, amazing new documents {{0}}. A proposal to get ‘Nessie’ named after Her Majesty was sent to Buckingham Palace in the 1960s when a scientist discovered the Queen {{9}} with the legend.","Recently discovered papers show that Sir Peter Scott, the first person {{10}} an investigation into the existence of the mythical Scottish Highlands creature, asked the Queen {{11}} to have the monster named ‘Elizabeth Nessiae’ if it was ever eventually found. His {{12}} came after he found out Her Royal Highness was “very interested” in the existence of the prehistoric animal, The Independent reports.","Martin Charteris, who was the Queen’s private secretary {{13}}, said in a reply to Sir Peter’s letter that there would have to be “absolutely indisputable evidence” of its existence before it was named after the monarch. He said: “It {{14}} very regrettable to connect Her Majesty in any way with something which ultimately turned out to be a hoax. {{15}} the animal does prove to exist, I am not at all sure that it will be generally very {{16}} to name it after Her Majesty {{17}} it has for so many years been known as ‘The Monster’.”","(http://www.mirror.co.uk)"],"items":[{"n":0,"options":[{"key":"A","text":"are revealing"},{"key":"B","text":"were revealed"},{"key":"C","text":"reveal"},{"key":"D","text":"has revealed"}],"example":true,"answer":"C"},{"n":9,"options":[{"key":"A","text":"fascinated"},{"key":"B","text":"was fascinated"},{"key":"C","text":"was fascinating"},{"key":"D","text":"has been fascinated"}]},{"n":10,"options":[{"key":"A","text":"launched"},{"key":"B","text":"to be launched"},{"key":"C","text":"has launched"},{"key":"D","text":"to launch"}]},{"n":11,"options":[{"key":"A","text":"if she would agree"},{"key":"B","text":"that she agreed"},{"key":"C","text":"that she had agreed"},{"key":"D","text":"if she will agree"}]},{"n":12,"options":[{"key":"A","text":"recognition"},{"key":"B","text":"response"},{"key":"C","text":"requirement"},{"key":"D","text":"request"}]},{"n":13,"options":[{"key":"A","text":"at the time"},{"key":"B","text":"at the same time"},{"key":"C","text":"in the meantime"},{"key":"D","text":"at all times"}]},{"n":14,"options":[{"key":"A","text":"had to be"},{"key":"B","text":"must be"},{"key":"C","text":"would be"},{"key":"D","text":"is to be"}]},{"n":15,"options":[{"key":"A","text":"After all"},{"key":"B","text":"Even if"},{"key":"C","text":"Although"},{"key":"D","text":"Regardless"}]},{"n":16,"options":[{"key":"A","text":"improper"},{"key":"B","text":"fantastic"},{"key":"C","text":"sympathetic"},{"key":"D","text":"appropriate"}]},{"n":17,"options":[{"key":"A","text":"since"},{"key":"B","text":"so"},{"key":"C","text":"yet"},{"key":"D","text":"unless"}]}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2017-maj-emelt-L2$mtr$, $mtr${"id":"2017-maj-emelt-L2","number":2,"kind":"choice","layout":"inline","examType":"feleletválasztós szövegkiegészítés (A-D)","points":9,"instructions":["You are going to read an article about a newly revealed interest of the Queen. Some words are missing from the text.","Choose the most appropriate answer from the options (A-D) for each gap (9-17) in the text."],"title":"LOCH NESS MONSTER WAS NEARLY NAMED AFTER THE QUEEN","body":["The Loch Ness Monster could have been named after the Queen if it was ever found, amazing new documents {{0}}. A proposal to get ‘Nessie’ named after Her Majesty was sent to Buckingham Palace in the 1960s when a scientist discovered the Queen {{9}} with the legend.","Recently discovered papers show that Sir Peter Scott, the first person {{10}} an investigation into the existence of the mythical Scottish Highlands creature, asked the Queen {{11}} to have the monster named ‘Elizabeth Nessiae’ if it was ever eventually found. His {{12}} came after he found out Her Royal Highness was “very interested” in the existence of the prehistoric animal, The Independent reports.","Martin Charteris, who was the Queen’s private secretary {{13}}, said in a reply to Sir Peter’s letter that there would have to be “absolutely indisputable evidence” of its existence before it was named after the monarch. He said: “It {{14}} very regrettable to connect Her Majesty in any way with something which ultimately turned out to be a hoax. {{15}} the animal does prove to exist, I am not at all sure that it will be generally very {{16}} to name it after Her Majesty {{17}} it has for so many years been known as ‘The Monster’.”","(http://www.mirror.co.uk)"],"items":[{"n":0,"options":[{"key":"A","text":"are revealing"},{"key":"B","text":"were revealed"},{"key":"C","text":"reveal"},{"key":"D","text":"has revealed"}],"example":true,"answer":"C"},{"n":9,"options":[{"key":"A","text":"fascinated"},{"key":"B","text":"was fascinated"},{"key":"C","text":"was fascinating"},{"key":"D","text":"has been fascinated"}],"answer":"B"},{"n":10,"options":[{"key":"A","text":"launched"},{"key":"B","text":"to be launched"},{"key":"C","text":"has launched"},{"key":"D","text":"to launch"}],"answer":"D"},{"n":11,"options":[{"key":"A","text":"if she would agree"},{"key":"B","text":"that she agreed"},{"key":"C","text":"that she had agreed"},{"key":"D","text":"if she will agree"}],"answer":"A"},{"n":12,"options":[{"key":"A","text":"recognition"},{"key":"B","text":"response"},{"key":"C","text":"requirement"},{"key":"D","text":"request"}],"answer":"D"},{"n":13,"options":[{"key":"A","text":"at the time"},{"key":"B","text":"at the same time"},{"key":"C","text":"in the meantime"},{"key":"D","text":"at all times"}],"answer":"A"},{"n":14,"options":[{"key":"A","text":"had to be"},{"key":"B","text":"must be"},{"key":"C","text":"would be"},{"key":"D","text":"is to be"}],"answer":"C"},{"n":15,"options":[{"key":"A","text":"After all"},{"key":"B","text":"Even if"},{"key":"C","text":"Although"},{"key":"D","text":"Regardless"}],"answer":"B"},{"n":16,"options":[{"key":"A","text":"improper"},{"key":"B","text":"fantastic"},{"key":"C","text":"sympathetic"},{"key":"D","text":"appropriate"}],"answer":"D"},{"n":17,"options":[{"key":"A","text":"since"},{"key":"B","text":"so"},{"key":"C","text":"yet"},{"key":"D","text":"unless"}],"answer":"A"}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2017-maj-emelt-L3$mtr$, $mtr$2017-maj-emelt$mtr$, $mtr$language$mtr$, 3, $mtr$text$mtr$, $mtr$nyílt cloze (egy szó)$mtr$, 7, 7, $mtr${"id":"2017-maj-emelt-L3","number":3,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":7,"instructions":["You are going to read an article about the danger of selfies. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (18-24) after the text.","Use only one word in each gap."],"title":"SELFIE MADNESS: TOO MANY DYING TO GET THE PICTURE","body":["The rise of selfie photography in some of the world’s most beautiful and dangerous places has resulted {{0}} a string of gruesome deaths worldwide.","The act of taking a picture of oneself with a mobile phone, placing the subject centre-stage, has exploded in popularity in recent years, with everyone {{18}} Britain’s Queen Elizabeth to President Barack Obama joining in.","But the selfie has also inspired an epidemic of risk taking and offensive public behaviour, pushing the boundaries of safety and decency, whether by dangling from a skyscraper {{19}} by posing with explosives.","Several governments have now begun treating the selfie {{20}} a serious threat to public safety, leading them to launch public education campaigns {{21}} to those against smoking and binge drinking.","Dozens of selfie-related deaths and injuries in early 2015 led Russia’s Interior Ministry to launch a campaign warning mobile phone snappers about the danger of, {{22}} other things, posing for a selfie with a lion.","“A cool selfie could cost you your life,” reads a poster from the campaign, {{23}} includes safety videos and information booklets.","The European Union has proposed a law to criminalise social media posts containing pictures of landmarks {{24}} as the Eiffel Tower in Paris or Rome’s Trevi Fountain.","(http://in.reuters.com)"],"grading":{"spelling":"strict"},"items":[{"n":0,"example":true,"accept":["in"]},{"n":18},{"n":19},{"n":20},{"n":21},{"n":22},{"n":23},{"n":24}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2017-maj-emelt-L3$mtr$, $mtr${"id":"2017-maj-emelt-L3","number":3,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":7,"instructions":["You are going to read an article about the danger of selfies. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (18-24) after the text.","Use only one word in each gap."],"title":"SELFIE MADNESS: TOO MANY DYING TO GET THE PICTURE","body":["The rise of selfie photography in some of the world’s most beautiful and dangerous places has resulted {{0}} a string of gruesome deaths worldwide.","The act of taking a picture of oneself with a mobile phone, placing the subject centre-stage, has exploded in popularity in recent years, with everyone {{18}} Britain’s Queen Elizabeth to President Barack Obama joining in.","But the selfie has also inspired an epidemic of risk taking and offensive public behaviour, pushing the boundaries of safety and decency, whether by dangling from a skyscraper {{19}} by posing with explosives.","Several governments have now begun treating the selfie {{20}} a serious threat to public safety, leading them to launch public education campaigns {{21}} to those against smoking and binge drinking.","Dozens of selfie-related deaths and injuries in early 2015 led Russia’s Interior Ministry to launch a campaign warning mobile phone snappers about the danger of, {{22}} other things, posing for a selfie with a lion.","“A cool selfie could cost you your life,” reads a poster from the campaign, {{23}} includes safety videos and information booklets.","The European Union has proposed a law to criminalise social media posts containing pictures of landmarks {{24}} as the Eiffel Tower in Paris or Rome’s Trevi Fountain.","(http://in.reuters.com)"],"grading":{"spelling":"strict","maxWords":1},"items":[{"n":0,"example":true,"accept":["in"]},{"n":18,"accept":["from"]},{"n":19,"accept":["or"]},{"n":20,"accept":["as","like"]},{"n":21,"accept":["similar","comparable","corresponding","linked","connected","related"]},{"n":22,"accept":["among","amongst"]},{"n":23,"accept":["which"]},{"n":24,"accept":["such"]}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2017-maj-emelt-L4$mtr$, $mtr$2017-maj-emelt$mtr$, $mtr$language$mtr$, 4, $mtr$lines$mtr$, $mtr$soronkénti hibakeresés (felesleges szó vagy helyes sor)$mtr$, 11, 8, $mtr${"id":"2017-maj-emelt-L4","number":4,"kind":"lines","layout":"lines","examType":"soronkénti hibakeresés (felesleges szó vagy helyes sor)","points":11,"instructions":["You are going to read an article about an unusual café. In most lines there is one word that should not be there. It is either grammatically incorrect or does not fit in with the sense of the text.","Read the text and then copy the extra word in the space provided after each line.","Some lines are correct. Indicate these lines with a tick ().","The task begins with two examples (0)."],"title":"THE REAL JUNK FOOD PROJECT","intro":"","items":[{"n":"0a","example":true,"text":"A “junk food” café, which serves on meals entirely from leftovers,","answer":"on"},{"n":"0b","example":true,"text":"has been set up by two women who are fed up with waste.","answer":null},{"n":25,"text":"Gaby Holmes and Natalie Crean, both of 23, are the driving"},{"n":26,"text":"force well behind The Real Junk Food Café, which has opened in"},{"n":27,"text":"Liverpool. They say it is shameful that just 35% of food ends up in"},{"n":28,"text":"the bin, at a time when no food banks are crying out for donations."},{"n":29,"text":"Waste food supplies are donated by greengrocers, caterers"},{"n":30,"text":"and small supermarkets. The two women decide it what they will"},{"n":31,"text":"cook on the basis out of what produce they’ve been given. People"},{"n":32,"text":"pay what they can for the food. The social concept café also"},{"n":33,"text":"accepts creative donations instead of cash in stock exchange for"},{"n":34,"text":"food. Gaby said: “It’s absurd so that millions of people are starving"},{"n":35,"text":"and millions of food items likely go to the bin every single day.”"}],"outro":"(http://www.mirror.co.uk)"}$mtr$::jsonb, null)
