insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2017-maj-kozep-H3$mtr$, $mtr$2017-maj-kozep$mtr$, $mtr$listening$mtr$, 3, $mtr$choice$mtr$, $mtr$igaz / hamis / a szöveg nem mondja (A/B/C)$mtr$, 8, 10, $mtr${"id":"2017-maj-kozep-H3","number":3,"kind":"choice","layout":"stems","examType":"igaz / hamis / a szöveg nem mondja (A/B/C)","points":8,"instructions":["In this section you will hear a true story that happened in Columbus, Ohio.","Your task is to decide whether the following statements are true, false or we do not know because the text does not say, and write the appropriate letter in the boxes on the right. Write A if the statement is true, write B if the statement is false, and write C if the text does not say.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_17maj_fl.mp3","start":1323.49,"end":1795.53,"clip":"hang/k_angol_17maj_fl_H3.mp3"},"items":[{"n":0,"example":true,"stem":"Mel Kiser was driving his car on a four-lane highway.","answer":"C"},{"n":17,"stem":"He saw the car in front of him crash into the back of armoured truck."},{"n":18,"stem":"Mr. Kiser hit the first of the bags that had fallen out of the truck."},{"n":19,"stem":"At first a lot of drivers didn’t realise that there was money on the highway."},{"n":20,"stem":"Mr. Kiser picked up as many banknotes as he could, and put them in a plastic bag."},{"n":21,"stem":"Mr. Kiser spent some of the money he’d taken on a new gate and a vacation in Florida."},{"n":22,"stem":"Mr. Kiser received a 10% reward for the money he had returned."},{"n":23,"stem":"It was the highest reward ever offered by the armoured truck company."},{"n":24,"stem":"A newspaper contacted the man who took two bags of money and asked for an interview."}],"options":[{"key":"A","text":"TRUE"},{"key":"B","text":"FALSE"},{"key":"C","text":"THE TEXT DOES NOT SAY"}]}$mtr$::jsonb, $mtr${"file":"k_angol_17maj_fl.mp3","start":1323.49,"end":1795.53,"clip":"hang/k_angol_17maj_fl_H3.mp3"}$mtr$::jsonb)
