insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2017-okt-emelt-L1$mtr$, $mtr$2017-okt-emelt$mtr$, $mtr$language$mtr$, 1, $mtr$text$mtr$, $mtr$szóképzés (zárójeles szó)$mtr$, 8, 5, $mtr${"id":"2017-okt-emelt-L1","number":1,"kind":"text","layout":"inline","examType":"szóképzés (zárójeles szó)","points":8,"instructions":["You are going to read an article about new rules relating to EU nurses working or applying for a job in the UK. Some words are missing from the text.","Use the words in brackets to form the words that fit in the gaps (1-8).","There might be cases when you do not have to change the word in brackets.","Use only one word for each gap."],"title":"EU NURSES FACE ENGLISH LANGUAGE TESTS","body":["Nurses and midwives {{0}} to Britain from the EU will now need to prove they are fluent in English, under new rules. Until now, checks have only been applied to nurses from outside the EU. From now on any nurse applying to join the register from outside the UK will need to have an English language {{1}}. Tests will check listening, reading, writing and speaking {{2}}.","The Nursing and Midwifery Council Chief Executive said: \"The {{3}} to communicate effectively with patients is fundamental to patient {{4}} and is a principle that is central to our code.\" The NMC has more than 690,000 nurses and midwives on its register. Around 66,000 of these come from non-EU countries and 33,000 from the EU.","Katherine Murphy of The Patients Association said: \"Nurses from other countries make an extremely important {{5}} to healthcare in the UK. However, we hear from patients on our National Helpline that there can be real issues with some overseas health {{6}}; including problems with communication and a lack of {{7}} of processes and procedures. The Patients Association calls on all hospitals to {{8}} that their staff meet these new requirements, and that all overseas nurses have the necessary support and training to be able to offer patients safe and effective care.\"","(www.news.bbc.com.uk)"],"grading":{"spelling":"strict"},"items":[{"n":0,"prompt":"come","example":true,"accept":["coming"]},{"n":1,"prompt":"assess"},{"n":2,"prompt":"fluent"},{"n":3,"prompt":"able"},{"n":4,"prompt":"safe"},{"n":5,"prompt":"contribute"},{"n":6,"prompt":"profession"},{"n":7,"prompt":"understand"},{"n":8,"prompt":"sure"}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2017-okt-emelt-L1$mtr$, $mtr${"id":"2017-okt-emelt-L1","number":1,"kind":"text","layout":"inline","examType":"szóképzés (zárójeles szó)","points":8,"instructions":["You are going to read an article about new rules relating to EU nurses working or applying for a job in the UK. Some words are missing from the text.","Use the words in brackets to form the words that fit in the gaps (1-8).","There might be cases when you do not have to change the word in brackets.","Use only one word for each gap."],"title":"EU NURSES FACE ENGLISH LANGUAGE TESTS","body":["Nurses and midwives {{0}} to Britain from the EU will now need to prove they are fluent in English, under new rules. Until now, checks have only been applied to nurses from outside the EU. From now on any nurse applying to join the register from outside the UK will need to have an English language {{1}}. Tests will check listening, reading, writing and speaking {{2}}.","The Nursing and Midwifery Council Chief Executive said: \"The {{3}} to communicate effectively with patients is fundamental to patient {{4}} and is a principle that is central to our code.\" The NMC has more than 690,000 nurses and midwives on its register. Around 66,000 of these come from non-EU countries and 33,000 from the EU.","Katherine Murphy of The Patients Association said: \"Nurses from other countries make an extremely important {{5}} to healthcare in the UK. However, we hear from patients on our National Helpline that there can be real issues with some overseas health {{6}}; including problems with communication and a lack of {{7}} of processes and procedures. The Patients Association calls on all hospitals to {{8}} that their staff meet these new requirements, and that all overseas nurses have the necessary support and training to be able to offer patients safe and effective care.\"","(www.news.bbc.com.uk)"],"grading":{"spelling":"strict","maxWords":1},"items":[{"n":0,"prompt":"come","example":true,"accept":["coming"]},{"n":1,"prompt":"assess","accept":["assessment"]},{"n":2,"prompt":"fluent","accept":["fluency","fluently"]},{"n":3,"prompt":"able","accept":["ability"]},{"n":4,"prompt":"safe","accept":["safety"]},{"n":5,"prompt":"contribute","accept":["contribution"]},{"n":6,"prompt":"profession","accept":["professionals"]},{"n":7,"prompt":"understand","accept":["understanding"]},{"n":8,"prompt":"sure","accept":["ensure","insure"]}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2017-okt-emelt-L2$mtr$, $mtr$2017-okt-emelt$mtr$, $mtr$language$mtr$, 2, $mtr$choice$mtr$, $mtr$feleletválasztós szövegkiegészítés (A-D)$mtr$, 8, 6, $mtr${"id":"2017-okt-emelt-L2","number":2,"kind":"choice","layout":"inline","examType":"feleletválasztós szövegkiegészítés (A-D)","points":8,"instructions":["You are going to read an article about the plans for a new $10 bill. Some words are missing from the text.","Choose the most appropriate answer from the options (A-D) for each gap (9-16) in the text."],"title":"A WOMAN ON THE $10 BILL","body":["In June, 2015, the U.S. Treasury Department announced that the next $10 bill will feature a woman who {{0}} a major role in American history. The new bill is expected {{9}} released in 2020. That year marks the 100th anniversary of the 19th Amendment to the United States Constitution, {{10}} gave women the right to vote.","{{11}} the new note will feature a woman, Alexander Hamilton – who is on the present $10 bill – won't be completely replaced. That could mean the new design will feature a picture of Hamilton and a woman (or women). Hamilton was one of the country’s Founding Fathers. He was among the signers of the U.S. Constitution. The Treasury Department has not decided which woman will be on the $10. First, it is asking the public to share {{12}} opinion at thenew10.treasury.gov.","There are rules about who can be featured on money. By law, no living person may appear on a bill, and George Washington {{13}} always remain on the $1. His wife, Martha Washington, was the last woman to appear on U.S. currency; her portrait was on the $1 silver certificate from 1891 to 1896. After public comments {{14}}, the Treasury Department will make the final decision on what the bill will {{15}} and who will be featured. The bill will have new security features to {{16}} harder to counterfeit. It will also be easier for the blind and visually impaired to handle.","(www.timeforkids.com)"],"items":[{"n":0,"options":[{"key":"A","text":"made"},{"key":"B","text":"did"},{"key":"C","text":"played"},{"key":"D","text":"gave"}],"example":true,"answer":"C"},{"n":9,"options":[{"key":"A","text":"being"},{"key":"B","text":"to have"},{"key":"C","text":"having"},{"key":"D","text":"to be"}]},{"n":10,"options":[{"key":"A","text":"which"},{"key":"B","text":"this"},{"key":"C","text":"what"},{"key":"D","text":"that"}]},{"n":11,"options":[{"key":"A","text":"While"},{"key":"B","text":"Despite"},{"key":"C","text":"However,"},{"key":"D","text":"Since"}]},{"n":12,"options":[{"key":"A","text":"it’s"},{"key":"B","text":"his"},{"key":"C","text":"its"},{"key":"D","text":"theirs"}]},{"n":13,"options":[{"key":"A","text":"need"},{"key":"B","text":"must"},{"key":"C","text":"would"},{"key":"D","text":"has to"}]},{"n":14,"options":[{"key":"A","text":"had been considered"},{"key":"B","text":"will be considered"},{"key":"C","text":"would be considered"},{"key":"D","text":"have been considered"}]},{"n":15,"options":[{"key":"A","text":"look"},{"key":"B","text":"look like"},{"key":"C","text":"like"},{"key":"D","text":"be alike"}]},{"n":16,"options":[{"key":"A","text":"make it"},{"key":"B","text":"make"},{"key":"C","text":"make them"},{"key":"D","text":"make one"}]}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2017-okt-emelt-L2$mtr$, $mtr${"id":"2017-okt-emelt-L2","number":2,"kind":"choice","layout":"inline","examType":"feleletválasztós szövegkiegészítés (A-D)","points":8,"instructions":["You are going to read an article about the plans for a new $10 bill. Some words are missing from the text.","Choose the most appropriate answer from the options (A-D) for each gap (9-16) in the text."],"title":"A WOMAN ON THE $10 BILL","body":["In June, 2015, the U.S. Treasury Department announced that the next $10 bill will feature a woman who {{0}} a major role in American history. The new bill is expected {{9}} released in 2020. That year marks the 100th anniversary of the 19th Amendment to the United States Constitution, {{10}} gave women the right to vote.","{{11}} the new note will feature a woman, Alexander Hamilton – who is on the present $10 bill – won't be completely replaced. That could mean the new design will feature a picture of Hamilton and a woman (or women). Hamilton was one of the country’s Founding Fathers. He was among the signers of the U.S. Constitution. The Treasury Department has not decided which woman will be on the $10. First, it is asking the public to share {{12}} opinion at thenew10.treasury.gov.","There are rules about who can be featured on money. By law, no living person may appear on a bill, and George Washington {{13}} always remain on the $1. His wife, Martha Washington, was the last woman to appear on U.S. currency; her portrait was on the $1 silver certificate from 1891 to 1896. After public comments {{14}}, the Treasury Department will make the final decision on what the bill will {{15}} and who will be featured. The bill will have new security features to {{16}} harder to counterfeit. It will also be easier for the blind and visually impaired to handle.","(www.timeforkids.com)"],"items":[{"n":0,"options":[{"key":"A","text":"made"},{"key":"B","text":"did"},{"key":"C","text":"played"},{"key":"D","text":"gave"}],"example":true,"answer":"C"},{"n":9,"options":[{"key":"A","text":"being"},{"key":"B","text":"to have"},{"key":"C","text":"having"},{"key":"D","text":"to be"}],"answer":"D"},{"n":10,"options":[{"key":"A","text":"which"},{"key":"B","text":"this"},{"key":"C","text":"what"},{"key":"D","text":"that"}],"answer":"A"},{"n":11,"options":[{"key":"A","text":"While"},{"key":"B","text":"Despite"},{"key":"C","text":"However,"},{"key":"D","text":"Since"}],"answer":"A"},{"n":12,"options":[{"key":"A","text":"it’s"},{"key":"B","text":"his"},{"key":"C","text":"its"},{"key":"D","text":"theirs"}],"answer":"C"},{"n":13,"options":[{"key":"A","text":"need"},{"key":"B","text":"must"},{"key":"C","text":"would"},{"key":"D","text":"has to"}],"answer":"B"},{"n":14,"options":[{"key":"A","text":"had been considered"},{"key":"B","text":"will be considered"},{"key":"C","text":"would be considered"},{"key":"D","text":"have been considered"}],"answer":"D"},{"n":15,"options":[{"key":"A","text":"look"},{"key":"B","text":"look like"},{"key":"C","text":"like"},{"key":"D","text":"be alike"}],"answer":"B"},{"n":16,"options":[{"key":"A","text":"make it"},{"key":"B","text":"make"},{"key":"C","text":"make them"},{"key":"D","text":"make one"}],"answer":"A"}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2017-okt-emelt-L3$mtr$, $mtr$2017-okt-emelt$mtr$, $mtr$language$mtr$, 3, $mtr$text$mtr$, $mtr$nyílt cloze (egy szó)$mtr$, 8, 7, $mtr${"id":"2017-okt-emelt-L3","number":3,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":8,"instructions":["You are going to read an article about an earlier version of Martin Luther King's famous I Have a Dream speech. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (17-24) after the text.","Use only one word in each gap."],"title":"EARLY 'DREAM' SPEECH FOUND","body":["Martin Luther King electrified the audience with his speech back in 1963 - but it wasn't the first time he {{0}} delivered it. A recording of an earlier version of King's historic I Have a Dream speech, delivered to high school students in Rocky Mount in 1962, {{17}} been discovered.","King gave the 55-minute address months {{18}} he spoke in front of thousands at Washington DC's Lincoln Memorial. In it, the civil rights leader repeated the soon-to-be iconic phrase \"I have a dream\" eight times. King's speech to some 2,000 students was reported by the press {{19}} the time, but an audio recording of the event was {{20}} generally known to exist.","The tape, discovered by Jason Miller, an English professor at North Carolina State University, is believed to be the first ever recording of the speech. He stumbled across it while conducting research on King at a local library, after reading about a transcript of the speech and {{21}} some calls to try to locate a recording. A copy on tape \"mysteriously appeared\" inside a box {{22}} had the words \"Please Do Not Erase\" written on it.","Mr Miller brought in an expert to verify the tape, then {{23}} it restored and transformed to digital format so that it {{24}} be heard. The entire speech is due to be made available online later this year.","(www.news.bbc.com.uk)"],"grading":{"spelling":"strict"},"items":[{"n":0,"example":true,"accept":["had"]},{"n":17},{"n":18},{"n":19},{"n":20},{"n":21},{"n":22},{"n":23},{"n":24}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2017-okt-emelt-L3$mtr$, $mtr${"id":"2017-okt-emelt-L3","number":3,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":8,"instructions":["You are going to read an article about an earlier version of Martin Luther King's famous I Have a Dream speech. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (17-24) after the text.","Use only one word in each gap."],"title":"EARLY 'DREAM' SPEECH FOUND","body":["Martin Luther King electrified the audience with his speech back in 1963 - but it wasn't the first time he {{0}} delivered it. A recording of an earlier version of King's historic I Have a Dream speech, delivered to high school students in Rocky Mount in 1962, {{17}} been discovered.","King gave the 55-minute address months {{18}} he spoke in front of thousands at Washington DC's Lincoln Memorial. In it, the civil rights leader repeated the soon-to-be iconic phrase \"I have a dream\" eight times. King's speech to some 2,000 students was reported by the press {{19}} the time, but an audio recording of the event was {{20}} generally known to exist.","The tape, discovered by Jason Miller, an English professor at North Carolina State University, is believed to be the first ever recording of the speech. He stumbled across it while conducting research on King at a local library, after reading about a transcript of the speech and {{21}} some calls to try to locate a recording. A copy on tape \"mysteriously appeared\" inside a box {{22}} had the words \"Please Do Not Erase\" written on it.","Mr Miller brought in an expert to verify the tape, then {{23}} it restored and transformed to digital format so that it {{24}} be heard. The entire speech is due to be made available online later this year.","(www.news.bbc.com.uk)"],"grading":{"spelling":"strict","maxWords":1},"items":[{"n":0,"example":true,"accept":["had"]},{"n":17,"accept":["has"]},{"n":18,"accept":["before"]},{"n":19,"accept":["at","of"]},{"n":20,"accept":["never","not"]},{"n":21,"accept":["making","placing"]},{"n":22,"accept":["that","which","and"]},{"n":23,"accept":["got","had"]},{"n":24,"accept":["could","can","would","might","may"]}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2017-okt-emelt-L4$mtr$, $mtr$2017-okt-emelt$mtr$, $mtr$language$mtr$, 4, $mtr$lines$mtr$, $mtr$soronkénti hibakeresés (felesleges szó vagy helyes sor)$mtr$, 11, 8, $mtr${"id":"2017-okt-emelt-L4","number":4,"kind":"lines","layout":"lines","examType":"soronkénti hibakeresés (felesleges szó vagy helyes sor)","points":11,"instructions":["You are going to read a story about two friends. In most lines there is one word that should not be there. It is either grammatically incorrect or does not fit in with the sense of the text.","Read the text and then copy the extra word in the space provided after each line.","Some lines are correct. Indicate these lines with a tick ().","The task begins with two examples (0)."],"title":"SAND AND STONE","intro":"A story tells that two friends were walking through the desert. During the journey, they had an argument, and one friend slapped","items":[{"n":"0a","example":true,"text":"the other in the face. Without saying him anything, the one who got","answer":"him"},{"n":"0b","example":true,"text":"slapped wrote in the sand: Today my best friend slapped my face.","answer":null},{"n":25,"text":"They kept on walking, until they have found an oasis, where they"},{"n":26,"text":"decided to take a bath. When the one who had been slapped got"},{"n":27,"text":"stuck in the mire and started to drowning, but his friend saved him."},{"n":28,"text":"After that he recovered from the near drowning, he carved on a"},{"n":29,"text":"stone: Today my best friend saved my life."},{"n":30,"text":"The man who had better slapped and saved his best friend asked"},{"n":31,"text":"from him: \"After I hurt you, you wrote in the sand, and now, you"},{"n":32,"text":"write on a stone, why?\"The other man had replied: \"When someone"},{"n":33,"text":"hurts us, we should not write it down in sand, where the winds of"},{"n":34,"text":"the forgiveness can erase it, but when someone does something"},{"n":35,"text":"good for us all, we must engrave it in stone where no wind can ever"}],"outro":"erase it.\" (www.stephen-knapp.com)"}$mtr$::jsonb, null)
