insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2017-okt-kozep-L3$mtr$, $mtr$2017-okt-kozep$mtr$, $mtr$language$mtr$, 3, $mtr$choice$mtr$, $mtr$feleletválasztós szövegkiegészítés (A-D)$mtr$, 8, 7, $mtr${"id":"2017-okt-kozep-L3","number":3,"kind":"choice","layout":"inline","examType":"feleletválasztós szövegkiegészítés (A-D)","points":8,"instructions":["You are going to read an article about a Star Wars contest. Some words are missing from the text.","Choose the most appropriate answer from the options (A-D) for each gap (18-25) in the text."],"title":"STAR WARS MARATHON","body":["Do you think you’re the biggest Star Wars fan? Think again, as one cinema-goer studied US Navy Seal breathing techniques {{0}} win a Star Wars marathon, sitting through 46 hours of the sci-fi saga.","A cinema in Austin, Texas, challenged fans to sit through the previous trilogies, and then The Force Awakens on repeat {{18}} the last person still awake was identified. The rules were simple: food, drink and toilet breaks are permitted, {{19}} sleeping, illegal drugs and talking and texting will result in disqualification.","Jim Braden, a {{20}} Texan, was the eventual winner of the marathon, {{21}} six other fans to win the precious prizes: a cinema membership for seven years and a seat named in his honour, {{22}} a naming ceremony.","“I wanted to demonstrate my passion,” he {{23}} journalists. Braden, who grew up with Star Wars, also talked about {{24}} he studied US Navy Seal breathing techniques. “We put ourselves through hell mentally and physically,” Braden added. “One other guy complained of {{25}} chest pains and dropped out.”","Although he had watched the latest episode nine times, his review was enthusiastic: “I came out saying that I still enjoyed the movie. That’s how you know it’s good.”","(http://www.independent.co.uk)"],"items":[{"n":0,"options":[{"key":"A","text":"just for"},{"key":"B","text":"hoping that"},{"key":"C","text":"in order to"},{"key":"D","text":"looking forward to"}],"example":true,"answer":"C"},{"n":18,"options":[{"key":"A","text":"if"},{"key":"B","text":"before"},{"key":"C","text":"until"},{"key":"D","text":"unless"}]},{"n":19,"options":[{"key":"A","text":"as"},{"key":"B","text":"but"},{"key":"C","text":"when"},{"key":"D","text":"because"}]},{"n":20,"options":[{"key":"A","text":"40 years old"},{"key":"B","text":"40-year-old"},{"key":"C","text":"of 40 years"},{"key":"D","text":"40-year"}]},{"n":21,"options":[{"key":"A","text":"defeating"},{"key":"B","text":"winning"},{"key":"C","text":"biting"},{"key":"D","text":"defending"}]},{"n":22,"options":[{"key":"A","text":"along with"},{"key":"B","text":"just like"},{"key":"C","text":"alone with"},{"key":"D","text":"altogether"}]},{"n":23,"options":[{"key":"A","text":"said"},{"key":"B","text":"explained"},{"key":"C","text":"told"},{"key":"D","text":"spoke"}]},{"n":24,"options":[{"key":"A","text":"that"},{"key":"B","text":"the cause"},{"key":"C","text":"however"},{"key":"D","text":"how"}]},{"n":25,"options":[{"key":"A","text":"having"},{"key":"B","text":"he had"},{"key":"C","text":"being in"},{"key":"D","text":"suffered"}]}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2017-okt-kozep-L3$mtr$, $mtr${"id":"2017-okt-kozep-L3","number":3,"kind":"choice","layout":"inline","examType":"feleletválasztós szövegkiegészítés (A-D)","points":8,"instructions":["You are going to read an article about a Star Wars contest. Some words are missing from the text.","Choose the most appropriate answer from the options (A-D) for each gap (18-25) in the text."],"title":"STAR WARS MARATHON","body":["Do you think you’re the biggest Star Wars fan? Think again, as one cinema-goer studied US Navy Seal breathing techniques {{0}} win a Star Wars marathon, sitting through 46 hours of the sci-fi saga.","A cinema in Austin, Texas, challenged fans to sit through the previous trilogies, and then The Force Awakens on repeat {{18}} the last person still awake was identified. The rules were simple: food, drink and toilet breaks are permitted, {{19}} sleeping, illegal drugs and talking and texting will result in disqualification.","Jim Braden, a {{20}} Texan, was the eventual winner of the marathon, {{21}} six other fans to win the precious prizes: a cinema membership for seven years and a seat named in his honour, {{22}} a naming ceremony.","“I wanted to demonstrate my passion,” he {{23}} journalists. Braden, who grew up with Star Wars, also talked about {{24}} he studied US Navy Seal breathing techniques. “We put ourselves through hell mentally and physically,” Braden added. “One other guy complained of {{25}} chest pains and dropped out.”","Although he had watched the latest episode nine times, his review was enthusiastic: “I came out saying that I still enjoyed the movie. That’s how you know it’s good.”","(http://www.independent.co.uk)"],"items":[{"n":0,"options":[{"key":"A","text":"just for"},{"key":"B","text":"hoping that"},{"key":"C","text":"in order to"},{"key":"D","text":"looking forward to"}],"example":true,"answer":"C"},{"n":18,"options":[{"key":"A","text":"if"},{"key":"B","text":"before"},{"key":"C","text":"until"},{"key":"D","text":"unless"}],"answer":"C"},{"n":19,"options":[{"key":"A","text":"as"},{"key":"B","text":"but"},{"key":"C","text":"when"},{"key":"D","text":"because"}],"answer":"B"},{"n":20,"options":[{"key":"A","text":"40 years old"},{"key":"B","text":"40-year-old"},{"key":"C","text":"of 40 years"},{"key":"D","text":"40-year"}],"answer":"B"},{"n":21,"options":[{"key":"A","text":"defeating"},{"key":"B","text":"winning"},{"key":"C","text":"biting"},{"key":"D","text":"defending"}],"answer":"A"},{"n":22,"options":[{"key":"A","text":"along with"},{"key":"B","text":"just like"},{"key":"C","text":"alone with"},{"key":"D","text":"altogether"}],"answer":"A"},{"n":23,"options":[{"key":"A","text":"said"},{"key":"B","text":"explained"},{"key":"C","text":"told"},{"key":"D","text":"spoke"}],"answer":"C"},{"n":24,"options":[{"key":"A","text":"that"},{"key":"B","text":"the cause"},{"key":"C","text":"however"},{"key":"D","text":"how"}],"answer":"D"},{"n":25,"options":[{"key":"A","text":"having"},{"key":"B","text":"he had"},{"key":"C","text":"being in"},{"key":"D","text":"suffered"}],"answer":"A"}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2017-okt-kozep-H1$mtr$, $mtr$2017-okt-kozep$mtr$, $mtr$listening$mtr$, 1, $mtr$choice$mtr$, $mtr$igaz / hamis / a szöveg nem mondja (A/B/C)$mtr$, 9, 8, $mtr${"id":"2017-okt-kozep-H1","number":1,"kind":"choice","layout":"stems","examType":"igaz / hamis / a szöveg nem mondja (A/B/C)","points":9,"instructions":["In this section you will hear a true story about two very unusual children.","Your task is to decide whether the following statements are true, false or we do not know because the text does not say, and write the appropriate letter in the boxes on the right. Write A if the statement is true, write B if the statement is false, and write C if the text does not say.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to make your decision about the answers."],"audio":{"file":"k_angol_17okt_fl.mp3","start":0,"end":614.07,"clip":"hang/k_angol_17okt_fl_H1.mp3"},"items":[{"n":0,"example":true,"stem":"Paul and Victoria are two and six years old respectively.","answer":"B"},{"n":1,"stem":"The Waters kids are different from other children as they hardly ever cry."},{"n":2,"stem":"Paul doesn’t even notice when he gets hurt."},{"n":3,"stem":"Paul gets hurt much more often than other kids."},{"n":4,"stem":"Paul’s unusual illness was discovered when he was six months old."},{"n":5,"stem":"Paul’s condition was first discovered by a doctor."},{"n":6,"stem":"In a test, doctors deliberately tried to cause pain to Paul."},{"n":7,"stem":"This illness is a lot more common in boys than girls."},{"n":8,"stem":"Paul was so jealous of his baby sister that sometimes he hit her."},{"n":9,"stem":"Paul and his sister Victoria have the same symptoms."}],"options":[{"key":"A","text":"TRUE"},{"key":"B","text":"FALSE"},{"key":"C","text":"THE TEXT DOES NOT SAY"}]}$mtr$::jsonb, $mtr${"file":"k_angol_17okt_fl.mp3","start":0,"end":614.07,"clip":"hang/k_angol_17okt_fl_H1.mp3"}$mtr$::jsonb)
