insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2017-okt-kozep-H2$mtr$, $mtr$2017-okt-kozep$mtr$, $mtr$listening$mtr$, 2, $mtr$text$mtr$, $mtr$rövid válasz hallás után$mtr$, 8, 9, $mtr${"id":"2017-okt-kozep-H2","number":2,"kind":"text","layout":"stems","examType":"rövid válasz hallás után","points":8,"instructions":["In this section, you are going to hear a strange but true story about a cat called Dusty.","Your task is to give short answers to the questions below.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_17okt_fl.mp3","start":614.07,"end":1156.53,"clip":"hang/k_angol_17okt_fl_H2.mp3"},"items":[{"n":0,"example":true,"stem":"What’s the name of the channel that the reporter, Vic Lee works for? {{gap}}","accept":["ABC"]},{"n":10,"stem":"What does Dusty become at night? {{gap}}"},{"n":11,"stem":"Who is Ethan McLelland? {{gap}}"},{"n":12,"stem":"What is it that Dusty’s victims don’t want to file? {{gap}}"},{"n":13,"stem":"Who are Jean Chu and Jim Coleman? {{gap}}"},{"n":14,"stem":"How many items has Dusty stolen in the past three years? {{gap}}"},{"n":15,"stem":"What did Dusty steal from Kelly McLelland? {{gap}}"},{"n":16,"stem":"What did Animal Planet use to find out about Dusty’s method of stealing? {{gap}}"},{"n":17,"stem":"What is Dusty’s record take for one night? {{gap}}"}],"grading":{"spelling":"keywords"}}$mtr$::jsonb, $mtr${"file":"k_angol_17okt_fl.mp3","start":614.07,"end":1156.53,"clip":"hang/k_angol_17okt_fl_H2.mp3"}$mtr$::jsonb)
