insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2018-maj-emelt-H1$mtr$, $mtr$2018-maj-emelt$mtr$, $mtr$listening$mtr$, 1, $mtr$choice$mtr$, $mtr$igaz / hamis / a szöveg nem mondja (A/B/C)$mtr$, 8, 9, $mtr${"id":"2018-maj-emelt-H1","number":1,"kind":"choice","layout":"stems","examType":"igaz / hamis / a szöveg nem mondja (A/B/C)","points":8,"instructions":["In this section you will hear a woman talk about her favourite singer.","Your task is to decide whether the following statements are true, false or we do not know because the text does not say, and write the appropriate letter in the boxes on the right. Write A if the statement is true, write B if the statement is false, and write C if the text does not say.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","After that, we will play the recording for the second time, but now in shorter sections and with breaks between the sections in order to give you enough time to write down your answers."],"audio":{"file":"e_angol_18maj_fl.mp3","start":0,"end":627.49,"clip":"hang/e_angol_18maj_fl_H1.mp3"},"items":[{"n":0,"example":true,"stem":"The speaker was sure that Seal had had a happy childhood.","answer":"A"},{"n":1,"stem":"Seal didn’t like his foster parents very much."},{"n":2,"stem":"Seal’s biological father must have beaten him quite often."},{"n":3,"stem":"From a very early age, Seal’s parents encouraged him to sing."},{"n":4,"stem":"It was one of Seal’s teachers who got him to sing on stage."},{"n":5,"stem":"When he was studying architecture, Seal lived a comfortable life."},{"n":6,"stem":"Seal’s girlfriend was convinced that he should be a musician."},{"n":7,"stem":"Not only did he sing in the demos, but he also played the bass guitar."},{"n":8,"stem":"Seal stopped writing music for a while to study the works of some musicians."}],"options":[{"key":"A","text":"TRUE"},{"key":"B","text":"FALSE"},{"key":"C","text":"THE TEXT DOES NOT SAY"}]}$mtr$::jsonb, $mtr${"file":"e_angol_18maj_fl.mp3","start":0,"end":627.49,"clip":"hang/e_angol_18maj_fl_H1.mp3"}$mtr$::jsonb)
