insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2018-maj-emelt-H2$mtr$, $mtr$2018-maj-emelt$mtr$, $mtr$listening$mtr$, 2, $mtr$multi$mtr$, $mtr$kettős választás (A, B vagy mindkettő)$mtr$, 8, 10, $mtr${"id":"2018-maj-emelt-H2","number":2,"kind":"multi","layout":"stems","examType":"kettős választás (A, B vagy mindkettő)","points":8,"instructions":["In this section, you will hear a radio interview with Howard Henley, who has 43 presidential statues on his property in Virginia, US.","Your task is to circle the letter(s) of the correct answer(s) in the boxes on the right. Please note that in this task both answers may be correct. However, there is always at least one correct answer. This means you will have to circle one or two letters.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","After that, we will play the recording for the second time, but now in shorter sections and with breaks between the sections in order to give you enough time to write down your answers."],"audio":{"file":"e_angol_18maj_fl.mp3","start":627.49,"end":1300.58,"clip":"hang/e_angol_18maj_fl_H2.mp3"},"items":[{"n":0,"example":true,"stem":"The reporter …","options":[{"key":"A","text":"heard about the crumbling presidential heads on television."},{"key":"B","text":"found out that Howard Henley is the owner the land where the busts are."}],"answer":["B"]},{"n":9,"stem":"The giant busts …","options":[{"key":"A","text":"have damaged noses."},{"key":"B","text":"appeared in a horror movie."}]},{"n":10,"stem":"Virginia’s Presidents Park …","options":[{"key":"A","text":"was the idea of a landowner and a sculptor."},{"key":"B","text":"served as a model for Mount Rushmore National Memorial."}]},{"n":11,"stem":"Virginia’s Presidents Park went bankrupt because …","options":[{"key":"A","text":"there weren’t enough visitors."},{"key":"B","text":"it was far away from other tourist attractions."}]},{"n":12,"stem":"Howard …","options":[{"key":"A","text":"first heard about Presidents Park when it went out of business."},{"key":"B","text":"suggested that the busts should be moved to his own land."}]},{"n":13,"stem":"The busts had to be lifted from their bases and as a result their …","options":[{"key":"A","text":"necks got damaged."},{"key":"B","text":"heads got damaged."}]},{"n":14,"stem":"Howard and his team …","options":[{"key":"A","text":"followed their original transportation plans very carefully."},{"key":"B","text":"totally lacked experience in transporting statues."}]},{"n":15,"stem":"Howard …","options":[{"key":"A","text":"doesn’t have a tourist attraction license."},{"key":"B","text":"never refuses a tourist permission to come and see the busts on his land."}]},{"n":16,"stem":"Howard wants to…","options":[{"key":"A","text":"find a new site for the original Presidents Park model."},{"key":"B","text":"add, among other things, a Secret Service Museum to the original model."}]}]}$mtr$::jsonb, $mtr${"file":"e_angol_18maj_fl.mp3","start":627.49,"end":1300.58,"clip":"hang/e_angol_18maj_fl_H2.mp3"}$mtr$::jsonb)
