insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2018-okt-emelt-H1$mtr$, $mtr$2018-okt-emelt$mtr$, $mtr$listening$mtr$, 1, $mtr$multi$mtr$, $mtr$kettős választás (A, B vagy mindkettő)$mtr$, 8, 9, $mtr${"id":"2018-okt-emelt-H1","number":1,"kind":"multi","layout":"stems","examType":"kettős választás (A, B vagy mindkettő)","points":8,"instructions":["In this section, you will hear a museum guide talking about a famous van Gogh portrait.","Your task will be to circle the letter(s) of the correct answer(s) in the boxes on the right. Please note that in this task both answers may be correct. However, there is always at least one correct answer. This means you will have to circle one or two letters.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to make your decisions about your answers."],"audio":{"file":"e_angol_18okt_fl.mp3","start":0,"end":761.8,"clip":"hang/e_angol_18okt_fl_H1.mp3"},"items":[{"n":0,"example":true,"stem":"The museum guide says that the …","options":[{"key":"A","text":"Van Gogh room is the first stop on the tour."},{"key":"B","text":"collection has several of van Gogh’s portraits."}],"answer":["B"]},{"n":1,"stem":"In his final years, Van Gogh …","options":[{"key":"A","text":"painted more than two dozen self portraits."},{"key":"B","text":"insisted on using the same technique in his paintings."}]},{"n":2,"stem":"Van Gogh painted …","options":[{"key":"A","text":"Self Portrait with Bandaged Ear in the second half of the 1880s."},{"key":"B","text":"at least two versions of the Self Portrait with Bandaged Ear."}]},{"n":3,"stem":"Van Gogh …","options":[{"key":"A","text":"decided to work with Gauguin years before he painted this self-portrait."},{"key":"B","text":"wanted to set up a studio for artists with the help of Gauguin."}]},{"n":4,"stem":"Van Gogh and Gauguin …","options":[{"key":"A","text":"couldn’t work together because they had different opinions on art."},{"key":"B","text":"became involved in a lot of fierce arguments."}]},{"n":5,"stem":"Van Gogh got so angry with Gauguin that he …","options":[{"key":"A","text":"attacked him."},{"key":"B","text":"cut off his friend’s earlobe."}]},{"n":6,"stem":"Self Portrait with Bandaged Ear …","options":[{"key":"A","text":"was painted the day after the terrible incident."},{"key":"B","text":"doesn't actually show the ear that was injured."}]},{"n":7,"stem":"Van Gogh’s two biographers think that he painted this picture to …","options":[{"key":"A","text":"show that he was mentally stable."},{"key":"B","text":"avoid being taken to a madhouse."}]},{"n":8,"stem":"Van Gogh …","options":[{"key":"A","text":"was sent to hospital at the request of his neighbours."},{"key":"B","text":"finally agreed that he should be taken to the local hospital."}]}]}$mtr$::jsonb, $mtr${"file":"e_angol_18okt_fl.mp3","start":0,"end":761.8,"clip":"hang/e_angol_18okt_fl_H1.mp3"}$mtr$::jsonb)
