insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2019-maj-emelt-H2$mtr$, $mtr$2019-maj-emelt$mtr$, $mtr$listening$mtr$, 2, $mtr$choice$mtr$, $mtr$igaz / hamis / a szöveg nem mondja (A/B/C)$mtr$, 9, 10, $mtr${"id":"2019-maj-emelt-H2","number":2,"kind":"choice","layout":"stems","examType":"igaz / hamis / a szöveg nem mondja (A/B/C)","points":9,"instructions":["In this section you will hear a recorded advertisement that appeared on the Internet.","Your task will be to decide whether the following statements are true, false or we do not know because the text does not say, and write the appropriate letter in the boxes on the right. Write A if the statement is true, write B if the statement is false, and write C if the text does not say.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers.","A= TRUE B= FALSE C= THE TEXT DOES NOT SAY"],"audio":{"file":"e_angol_19maj_fl.mp3","start":649.84,"end":1190.64,"clip":"hang/e_angol_19maj_fl_H2.mp3"},"items":[{"n":0,"example":true,"stem":"There are two girls and two boys in the advertiser’s family.","answer":"C"},{"n":7,"stem":"The nanny they are looking for must be childless."},{"n":8,"stem":"The family uses a private plane to travel between their four different homes."},{"n":9,"stem":"One of the nanny’s duties will be to take the children to and from school."},{"n":10,"stem":"The nanny can choose not to eat with the children at mealtimes."},{"n":11,"stem":"Holding a minibus driving licence might be a considerable advantage."},{"n":12,"stem":"The nanny will occasionally be asked to leave the house for a while."},{"n":13,"stem":"It’s absolutely necessary that the applicant should have previous experience in self-defence."},{"n":14,"stem":"The successful candidate will get a month’s salary for the two-week trial period."},{"n":15,"stem":"The nanny who takes the job will have to sign an agreement of secrecy."}],"options":[{"key":"A","text":"TRUE"},{"key":"B","text":"FALSE"},{"key":"C","text":"THE TEXT DOES NOT SAY"}]}$mtr$::jsonb, $mtr${"file":"e_angol_19maj_fl.mp3","start":649.84,"end":1190.64,"clip":"hang/e_angol_19maj_fl_H2.mp3"}$mtr$::jsonb)
