insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2019-maj-kozep-L2$mtr$, $mtr$2019-maj-kozep$mtr$, $mtr$language$mtr$, 2, $mtr$bank$mtr$, $mtr$szóbank (szavak visszahelyezése)$mtr$, 9, 6, $mtr${"id":"2019-maj-kozep-L2","number":2,"kind":"bank","layout":"inline","examType":"szóbank (szavak visszahelyezése)","points":9,"instructions":["You are going to read a joke about an accident. Some words are missing from the text.","Your task is to choose the most appropriate word from the list (A-N) for each gap (9-17) in the text. Write the letter of the appropriate word in the white box.","Each word can be used once.","There are three extra words that you do not need to use."],"title":"FRIENDS IN TROUBLE","body":["A woman and a man get into a car accident. {{0}} of their cars are totally destroyed, but amazingly {{9}} of them is hurt. After they crawl out of the wreckage, the woman says, “Look at our cars – {{10}} nothing left! Thank God we are all right! This must be a sign that we should be friends and not try to put the blame on each {{11}}.” The man replies, “Oh yes, I agree with you completely.” The woman points to a bottle on the ground and says, “And here’s {{12}} miracle. Somehow this bottle of whisky from my back {{13}} didn’t break. Let’s drink this Scotch and {{14}} our good fortune.” Then she hands the bottle to the man. The man nods his head in {{15}}, opens it, and drinks about a third of the bottle to {{16}} his nerves. He then hands it back to the woman. The woman takes the bottle and puts the cap back on. The man asks, “Aren’t you having {{17}}?” The woman replies, “No. I think I’ll just wait for the police ... I’ll let them decide whose fault it was.”","(https://www.reddit.com/)"],"bank":[{"key":"A","text":"AGREEMENT"},{"key":"B","text":"ANOTHER"},{"key":"C","text":"BOTH"},{"key":"D","text":"ANY"},{"key":"E","text":"CALM"},{"key":"F","text":"CELEBRATE"},{"key":"G","text":"EITHER"},{"key":"H","text":"NEITHER"},{"key":"I","text":"OTHER"},{"key":"K","text":"SEAT"},{"key":"L","text":"SIT"},{"key":"M","text":"THEIRS"},{"key":"N","text":"THERE’S"}],"items":[{"n":0,"example":true,"answer":"C"},{"n":9},{"n":10},{"n":11},{"n":12},{"n":13},{"n":14},{"n":15},{"n":16},{"n":17}]}$mtr$::jsonb, null)
