insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2019-okt-emelt-H1$mtr$, $mtr$2019-okt-emelt$mtr$, $mtr$listening$mtr$, 1, $mtr$multi$mtr$, $mtr$kettős választás (A, B vagy mindkettő)$mtr$, 7, 9, $mtr${"id":"2019-okt-emelt-H1","number":1,"kind":"multi","layout":"stems","examType":"kettős választás (A, B vagy mindkettő)","points":7,"instructions":["In this section you will hear a news report about an unusual incident in a British school.","Your task will be to circle the letter or letters of the correct answer or answers in the boxes on the right. Please note that in this task both answers may be correct. This means you will have to circle either A or B, or both A and B.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"e_angol_19okt_fl.mp3","start":0,"end":546.04,"clip":"hang/e_angol_19okt_fl_H1.mp3"},"items":[{"n":0,"example":true,"stem":"This news report is about something that is taking place in the ...","options":[{"key":"A","text":"UK."},{"key":"B","text":"summer."}],"answer":["A","B"]},{"n":1,"stem":"This week, temperatures all over in Britain are …","options":[{"key":"A","text":"pretty high."},{"key":"B","text":"over 30 degrees Celsius."}]},{"n":2,"stem":"Because of the heat last Tuesday, twenty boys in an East Sussex school …","options":[{"key":"A","text":"refused to wear their usual PE shorts."},{"key":"B","text":"turned up wearing shorts."}]},{"n":3,"stem":"Some of the rebels were …","options":[{"key":"A","text":"put in isolation."},{"key":"B","text":"sent home to change."}]},{"n":4,"stem":"In protest, two days later, the boys turned up …","options":[{"key":"A","text":"wearing skirts."},{"key":"B","text":"with their parents."}]},{"n":5,"stem":"The head teacher said …","options":[{"key":"A","text":"she would allow students to wear shorts if the heat continued."},{"key":"B","text":"it was only a small minority that protested."}]},{"n":6,"stem":"One boy told the BBC that the head teacher had eventually allowed them to wear …","options":[{"key":"A","text":"shorts."},{"key":"B","text":"skirts."}]},{"n":7,"stem":"This isn’t the first time boys in Britain have worn … to protest the heat.","options":[{"key":"A","text":"shorts"},{"key":"B","text":"skirts"}]}]}$mtr$::jsonb, $mtr${"file":"e_angol_19okt_fl.mp3","start":0,"end":546.04,"clip":"hang/e_angol_19okt_fl_H1.mp3"}$mtr$::jsonb)
