insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2020-maj-kozep-L3$mtr$, $mtr$2020-maj-kozep$mtr$, $mtr$language$mtr$, 3, $mtr$choice$mtr$, $mtr$feleletválasztós szövegkiegészítés (A-D)$mtr$, 9, 7, $mtr${"id":"2020-maj-kozep-L3","number":3,"kind":"choice","layout":"inline","examType":"feleletválasztós szövegkiegészítés (A-D)","points":9,"instructions":["You are going to read an article about whether men or women are better at multitasking. Some words are missing from the text.","Choose the most appropriate answer from the options (A-D) for each gap (17-25) in the text."],"title":"WHO IS BETTER AT MULTITASKING?","body":["Men were slower and {{0}} organised than women when switching quickly between tasks in tests {{17}} by UK psychologists.","First, they compared 120 women and 120 men in a computer test {{18}} involved switching between tasks like counting and recognising shapes. Men and women were equal when they did one task {{19}} time. But when the tasks were mixed up and the switching became faster, {{20}} women and men slowed down and made more mistakes. However, men were significantly slower.","To make the experiment more relevant to everyday life, the researchers {{21}} a second test. The participants were given eight minutes to complete a series of tasks – locating restaurants on a map, answering a phone call, and deciding how {{22}} search for a lost key in a field.","Completing all these tasks in eight minutes was impossible, {{23}} men and women had to prioritise, organise their time, and keep calm. Women spent more time {{24}} thinking at the beginning, whereas men jumped in too quickly. It suggests that – in a stressful and complex situation – women are more {{25}} to stop and think about what's going on in front of them.","(www.bbc.com/news)"],"items":[{"n":0,"options":[{"key":"A","text":"the less"},{"key":"B","text":"the least"},{"key":"C","text":"less"},{"key":"D","text":"least"}],"example":true,"answer":"C"},{"n":17,"options":[{"key":"A","text":"taken away"},{"key":"B","text":"given up"},{"key":"C","text":"carried out"},{"key":"D","text":"put down"}]},{"n":18,"options":[{"key":"A","text":"which was"},{"key":"B","text":"which"},{"key":"C","text":"what"},{"key":"D","text":"what was"}]},{"n":19,"options":[{"key":"A","text":"in"},{"key":"B","text":"at a"},{"key":"C","text":"on"},{"key":"D","text":"by the"}]},{"n":20,"options":[{"key":"A","text":"each"},{"key":"B","text":"all of"},{"key":"C","text":"every"},{"key":"D","text":"both"}]},{"n":21,"options":[{"key":"A","text":"tried"},{"key":"B","text":"could try"},{"key":"C","text":"will try"},{"key":"D","text":"were trying"}]},{"n":22,"options":[{"key":"A","text":"have they"},{"key":"B","text":"would they"},{"key":"C","text":"they would"},{"key":"D","text":"they have"}]},{"n":23,"options":[{"key":"A","text":"if"},{"key":"B","text":"although"},{"key":"C","text":"when"},{"key":"D","text":"so"}]},{"n":24,"options":[{"key":"A","text":"for"},{"key":"B","text":"by"},{"key":"C","text":"with"},{"key":"D","text":"–"}]},{"n":25,"options":[{"key":"A","text":"quick"},{"key":"B","text":"able"},{"key":"C","text":"suitable"},{"key":"D","text":"often"}]}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2020-maj-kozep-L3$mtr$, $mtr${"id":"2020-maj-kozep-L3","number":3,"kind":"choice","layout":"inline","examType":"feleletválasztós szövegkiegészítés (A-D)","points":9,"instructions":["You are going to read an article about whether men or women are better at multitasking. Some words are missing from the text.","Choose the most appropriate answer from the options (A-D) for each gap (17-25) in the text."],"title":"WHO IS BETTER AT MULTITASKING?","body":["Men were slower and {{0}} organised than women when switching quickly between tasks in tests {{17}} by UK psychologists.","First, they compared 120 women and 120 men in a computer test {{18}} involved switching between tasks like counting and recognising shapes. Men and women were equal when they did one task {{19}} time. But when the tasks were mixed up and the switching became faster, {{20}} women and men slowed down and made more mistakes. However, men were significantly slower.","To make the experiment more relevant to everyday life, the researchers {{21}} a second test. The participants were given eight minutes to complete a series of tasks – locating restaurants on a map, answering a phone call, and deciding how {{22}} search for a lost key in a field.","Completing all these tasks in eight minutes was impossible, {{23}} men and women had to prioritise, organise their time, and keep calm. Women spent more time {{24}} thinking at the beginning, whereas men jumped in too quickly. It suggests that – in a stressful and complex situation – women are more {{25}} to stop and think about what's going on in front of them.","(www.bbc.com/news)"],"items":[{"n":0,"options":[{"key":"A","text":"the less"},{"key":"B","text":"the least"},{"key":"C","text":"less"},{"key":"D","text":"least"}],"example":true,"answer":"C"},{"n":17,"options":[{"key":"A","text":"taken away"},{"key":"B","text":"given up"},{"key":"C","text":"carried out"},{"key":"D","text":"put down"}],"answer":"C"},{"n":18,"options":[{"key":"A","text":"which was"},{"key":"B","text":"which"},{"key":"C","text":"what"},{"key":"D","text":"what was"}],"answer":"B"},{"n":19,"options":[{"key":"A","text":"in"},{"key":"B","text":"at a"},{"key":"C","text":"on"},{"key":"D","text":"by the"}],"answer":"B"},{"n":20,"options":[{"key":"A","text":"each"},{"key":"B","text":"all of"},{"key":"C","text":"every"},{"key":"D","text":"both"}],"answer":"D"},{"n":21,"options":[{"key":"A","text":"tried"},{"key":"B","text":"could try"},{"key":"C","text":"will try"},{"key":"D","text":"were trying"}],"answer":"A"},{"n":22,"options":[{"key":"A","text":"have they"},{"key":"B","text":"would they"},{"key":"C","text":"they would"},{"key":"D","text":"they have"}],"answer":"C"},{"n":23,"options":[{"key":"A","text":"if"},{"key":"B","text":"although"},{"key":"C","text":"when"},{"key":"D","text":"so"}],"answer":"D"},{"n":24,"options":[{"key":"A","text":"for"},{"key":"B","text":"by"},{"key":"C","text":"with"},{"key":"D","text":"–"}],"answer":"D"},{"n":25,"options":[{"key":"A","text":"quick"},{"key":"B","text":"able"},{"key":"C","text":"suitable"},{"key":"D","text":"often"}],"answer":"B"}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
