},{"n":20,"accept":["that","which"]},{"n":21,"accept":["best"]},{"n":22,"accept":["what","everything","anything"]},{"n":23,"accept":["of","showing"]},{"n":24,"accept":["for"]},{"n":25,"accept":["never","hadn’t","hardly","scarcely","barely"]}],"source":"https://www.washingtonpost.com"}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
