insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2021-okt-emelt-H3$mtr$, $mtr$2021-okt-emelt$mtr$, $mtr$listening$mtr$, 3, $mtr$multi$mtr$, $mtr$kettős választás (A, B vagy mindkettő)$mtr$, 8, 11, $mtr${"id":"2021-okt-emelt-H3","number":3,"kind":"multi","layout":"stems","examType":"kettős választás (A, B vagy mindkettő)","points":8,"instructions":["In this section, you will hear an interview with Rowan Atkinson, the famous English comedian.","Your task will be to circle the letter(s) of the correct answer(s) in the boxes on the right. Please note that in this task both answers may be correct. However, there is always at least one correct answer. This means you will have to circle one or two letters.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to make your decision about the answers."],"audio":{"file":"e_angol_21okt_fl.mp3","start":1149.4,"end":1795.66,"clip":"hang/e_angol_21okt_fl_H3.mp3"},"items":[{"n":0,"example":true,"stem":"Mr. Rowan Atkinson is a(n) …","options":[{"key":"A","text":"actor."},{"key":"B","text":"screenwriter."}],"answer":["A","B"]},{"n":18,"stem":"Rowan Atkinson …","options":[{"key":"A","text":"admits that he is not good at multitasking at all."},{"key":"B","text":"can complete some work and start something new without needing any rest."}]},{"n":19,"stem":"Rowan Atkinson says that …","options":[{"key":"A","text":"he was 17 when he saw “Mr. Hulot’s Holiday”."},{"key":"B","text":"a French comedian’s film had an enormous impact on him."}]},{"n":20,"stem":"Rowan Atkinson …","options":[{"key":"A","text":"found it interesting that you need no words to create a funny situation."},{"key":"B","text":"watched “Mr. Hulot’s Holiday” on a videocassette."}]},{"n":21,"stem":"Rowan Atkinson …","options":[{"key":"A","text":"envied his schoolmate who was in charge of the sixth form film society."},{"key":"B","text":"saw “Mr. Hulot’s Holiday” many times over one weekend."}]},{"n":22,"stem":"Rowan Atkinson …","options":[{"key":"A","text":"doesn’t regret studying electrical engineering."},{"key":"B","text":"was researching French Literature in Oxford."}]},{"n":23,"stem":"Rowan Atkinson says that …","options":[{"key":"A","text":"at the age 20, he wanted to discover his theatrical side."},{"key":"B","text":"the people he appreciated very much were in Oxford or Cambridge."}]},{"n":24,"stem":"Rowan Atkinson chose Oxford because …","options":[{"key":"A","text":"the Cambridge application form was longer than the Oxford one."},{"key":"B","text":"his father had been there."}]},{"n":25,"stem":"Rowan Atkinson …","options":[{"key":"A","text":"was using a strange language and was making funny faces during his first show."},{"key":"B","text":"had practised pulling faces in front of a mirror for days before his performance."}]}]}$mtr$::jsonb, $mtr${"file":"e_angol_21okt_fl.mp3","start":1149.4,"end":1795.66,"clip":"hang/e_angol_21okt_fl_H3.mp3"}$mtr$::jsonb)
