insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2021-okt-kozep-L2$mtr$, $mtr$2021-okt-kozep$mtr$, $mtr$language$mtr$, 2, $mtr$text$mtr$, $mtr$szóképzés (zárójeles szó)$mtr$, 9, 6, $mtr${"id":"2021-okt-kozep-L2","number":2,"kind":"text","layout":"inline","examType":"szóképzés (zárójeles szó)","points":9,"instructions":["You are going to read an article about the origins of the @ sign. Some words are missing from the text.","Use the words in brackets to form the words that fit in the gaps (9-17).","There might be cases when you do not have to change the word in brackets.","Use only one word for each gap."],"title":"A WELL-KNOWN SIGN","body":["In Dutch the @ sign is called a “monkey tail”, in {{0}} a “maggot”, in Danish an “elephant’s trunk”, and in {{9}} a “snail”. Appearing everywhere now in emails, the @ sign has history.","The first {{10}} use was in The Mannasses Chronicle in 1345, where an @ sign is the first letter in the word ‘Amen’. By the 16th century, in southern {{11}} documents of trade, the sign represented amphora, a storage jar {{12}} since Roman times. By the 18th century it was called ‘commercial A’ and meant ‘at the rate of’ (eg.: 10 hats @ 1 shilling = 10 shillings).","It didn’t make it onto the earliest typewriters but was included by 1889, when it became a standard character. By 1963 @ was included in the new {{13}} recognised character set.","In 1971 computer {{14}} Ray Tomlinson was at work on Arpanet, the prototype of the internet. He added some of his own code to an {{15}} programme and sent a message from one computer to {{16}} – the first email. Ray needed a character to separate the message’s recipient from the computer it would arrive at, and {{17}} down at his teletype keyboard, he chose the @ symbol and changed the world forever."],"grading":{"spelling":"strict"},"items":[{"n":0,"prompt":"Hungary","example":true,"accept":["Hungarian"]},{"n":9,"prompt":"Wales"},{"n":10,"prompt":"record"},{"n":11,"prompt":"Europe"},{"n":12,"prompt":"use"},{"n":13,"prompt":"international"},{"n":14,"prompt":"programme"},{"n":15,"prompt":"exist"},{"n":16,"prompt":"other"},{"n":17,"prompt":"look"}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2021-okt-kozep-L2$mtr$, $mtr${"id":"2021-okt-kozep-L2","number":2,"kind":"text","layout":"inline","examType":"szóképzés (zárójeles szó)","points":9,"instructions":["You are going to read an article about the origins of the @ sign. Some words are missing from the text.","Use the words in brackets to form the words that fit in the gaps (9-17).","There might be cases when you do not have to change the word in brackets.","Use only one word for each gap."],"title":"A WELL-KNOWN SIGN","body":["In Dutch the @ sign is called a “monkey tail”, in {{0}} a “maggot”, in Danish an “elephant’s trunk”, and in {{9}} a “snail”. Appearing everywhere now in emails, the @ sign has history.","The first {{10}} use was in The Mannasses Chronicle in 1345, where an @ sign is the first letter in the word ‘Amen’. By the 16th century, in southern {{11}} documents of trade, the sign represented amphora, a storage jar {{12}} since Roman times. By the 18th century it was called ‘commercial A’ and meant ‘at the rate of’ (eg.: 10 hats @ 1 shilling = 10 shillings).","It didn’t make it onto the earliest typewriters but was included by 1889, when it became a standard character. By 1963 @ was included in the new {{13}} recognised character set.","In 1971 computer {{14}} Ray Tomlinson was at work on Arpanet, the prototype of the internet. He added some of his own code to an {{15}} programme and sent a message from one computer to {{16}} – the first email. Ray needed a character to separate the message’s recipient from the computer it would arrive at, and {{17}} down at his teletype keyboard, he chose the @ symbol and changed the world forever."],"grading":{"spelling":"strict","maxWords":1},"items":[{"n":0,"prompt":"Hungary","example":true,"accept":["Hungarian"]},{"n":9,"prompt":"Wales","accept":["Welsh"]},{"n":10,"prompt":"record","accept":["recorded"]},{"n":11,"prompt":"Europe","accept":["European"]},{"n":12,"prompt":"use","accept":["used"]},{"n":13,"prompt":"international","accept":["internationally"]},{"n":14,"prompt":"programme","accept":["programmer","programer"]},{"n":15,"prompt":"exist","accept":["existing","existent"]},{"n":16,"prompt":"other","accept":["another"]},{"n":17,"prompt":"look","accept":["looking"]}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2021-okt-kozep-L3$mtr$, $mtr$2021-okt-kozep$mtr$, $mtr$language$mtr$, 3, $mtr$text$mtr$, $mtr$nyílt cloze (egy szó)$mtr$, 8, 7, $mtr${"id":"2021-okt-kozep-L3","number":3,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":8,"instructions":["You are going to read an article about the history of ice cream. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (18- 25) after the text.","Use only one word in each gap."],"title":"ICE-CREAM","body":["A kind of ice-cream was invented in China about 200 BC {{0}} a milk and rice mixture was frozen by packing it into snow. It is believed that Roman emperors sent slaves to mountain tops to bring back fresh snow, {{18}} was then flavoured and served as an early form of ice-cream.","The explorer, Marco Polo (1254-1324), is believed to have seen ice-cream being made during his trip to China and introduced {{19}} to Italy. The King of England, Charles I, offered his chef £500 a year to {{20}} his ice-cream recipe a secret from the rest of England.","Ice Cream Sundaes were invented when it became illegal {{21}} sell ice-cream sodas on a Sunday in the American town of Evanston during the late 19th century. To get around the problem, some ice-cream sellers replaced the soda {{22}} syrup and called the dessert an \"Ice Cream Sunday\". They changed the final \"y\" for an \"e\" to avoid upsetting religious leaders.","Probably a Syrian man {{23}} Ernest E Hamwi invented the ice-cream cone in 1904. During the St Louis World's Fair in the United States, his waffle booth stood {{24}} to an ice-cream seller who ran short {{25}} dishes. As a favour, Hamwi rolled a waffle to hold his ice-cream and the cone was born."],"grading":{"spelling":"strict"},"items":[{"n":0,"example":true,"accept":["when"]},{"n":18},{"n":19},{"n":20},{"n":21},{"n":22},{"n":23},{"n":24},{"n":25}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2021-okt-kozep-L3$mtr$, $mtr${"id":"2021-okt-kozep-L3","number":3,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":8,"instructions":["You are going to read an article about the history of ice cream. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (18- 25) after the text.","Use only one word in each gap."],"title":"ICE-CREAM","body":["A kind of ice-cream was invented in China about 200 BC {{0}} a milk and rice mixture was frozen by packing it into snow. It is believed that Roman emperors sent slaves to mountain tops to bring back fresh snow, {{18}} was then flavoured and served as an early form of ice-cream.","The explorer, Marco Polo (1254-1324), is believed to have seen ice-cream being made during his trip to China and introduced {{19}} to Italy. The King of England, Charles I, offered his chef £500 a year to {{20}} his ice-cream recipe a secret from the rest of England.","Ice Cream Sundaes were invented when it became illegal {{21}} sell ice-cream sodas on a Sunday in the American town of Evanston during the late 19th century. To get around the problem, some ice-cream sellers replaced the soda {{22}} syrup and called the dessert an \"Ice Cream Sunday\". They changed the final \"y\" for an \"e\" to avoid upsetting religious leaders.","Probably a Syrian man {{23}} Ernest E Hamwi invented the ice-cream cone in 1904. During the St Louis World's Fair in the United States, his waffle booth stood {{24}} to an ice-cream seller who ran short {{25}} dishes. As a favour, Hamwi rolled a waffle to hold his ice-cream and the cone was born."],"grading":{"spelling":"strict","maxWords":1},"items":[{"n":0,"example":true,"accept":["when"]},{"n":18,"accept":["which"]},{"n":19,"accept":["it"]},{"n":20,"accept":["keep"]},{"n":21,"accept":["to"]},{"n":22,"accept":["with"]},{"n":23,"accept":["called","named"]},{"n":24,"accept":["next","close","near"]},{