insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2022-maj-emelt-L3$mtr$, $mtr$2022-maj-emelt$mtr$, $mtr$language$mtr$, 3, $mtr$text$mtr$, $mtr$nyílt cloze (egy szó)$mtr$, 9, 7, $mtr${"id":"2022-maj-emelt-L3","number":3,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":9,"instructions":["You are going to read an article about an unusual job offer. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (18-26) after the text.","Use only one word in each gap."],"title":"WANTED: ALL-IN-ONE LANDLORD, PUB MANAGER AND MONARCH FOR REMOTE U.K. ISLAND","body":["Have you ever wanted to be crowned king {{0}} queen? A council in England {{18}} have a job for you. If you take it, you'll move to a remote British island {{19}} a population of exactly two, get drenched with beer, and be the caretaker and landlord of a centuries-old pub. Oh, and the monarch title is purely symbolic.","But tour guide John Murphy says it's well {{20}} the trouble for the chance to live full-time on Piel Island, {{21}} he says is known for its pure isolation and incredible beauty. \"If they choose the solitude of sitting there on a glorious sunset, watching a few seals sunbathing, that's not a bad lifestyle, {{22}} it?\" Murphy said to As It Happens host Carol Off.","Piel is a small island off the coast of northwest England, reachable {{23}} ferry between April and September. It's currently home to one couple, a booming population of seals, a badly damaged 14th-century castle, and a pub called the Ship Inn, which is believed to be more than 300 years old. The pub is owned by the Barrow-in-Furness local government council, which is hiring a landlord to look {{24}} the pub and operate it in the summer, when it {{25}} for tourists.","Murphy, 72, {{26}} been visiting Piel Island for more than 60 years. In the summers, he guides walking tours there."],"grading":{"spelling":"strict"},"items":[{"n":0,"example":true,"accept":["or"]},{"n":18},{"n":19},{"n":20},{"n":21},{"n":22},{"n":23},{"n":24},{"n":25},{"n":26}],"source":"https://www.cbc.ca/radio/asithappens/as-it-happens-the-tuesday-edition-1.6294256/wanted-all-in-one-landlord-pub-manager-"}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2022-maj-emelt-L3$mtr$, $mtr${"id":"2022-maj-emelt-L3","number":3,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":9,"instructions":["You are going to read an article about an unusual job offer. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (18-26) after the text.","Use only one word in each gap."],"title":"WANTED: ALL-IN-ONE LANDLORD, PUB MANAGER AND MONARCH FOR REMOTE U.K. ISLAND","body":["Have you ever wanted to be crowned king {{0}} queen? A council in England {{18}} have a job for you. If you take it, you'll move to a remote British island {{19}} a population of exactly two, get drenched with beer, and be the caretaker and landlord of a centuries-old pub. Oh, and the monarch title is purely symbolic.","But tour guide John Murphy says it's well {{20}} the trouble for the chance to live full-time on Piel Island, {{21}} he says is known for its pure isolation and incredible beauty. \"If they choose the solitude of sitting there on a glorious sunset, watching a few seals sunbathing, that's not a bad lifestyle, {{22}} it?\" Murphy said to As It Happens host Carol Off.","Piel is a small island off the coast of northwest England, reachable {{23}} ferry between April and September. It's currently home to one couple, a booming population of seals, a badly damaged 14th-century castle, and a pub called the Ship Inn, which is believed to be more than 300 years old. The pub is owned by the Barrow-in-Furness local government council, which is hiring a landlord to look {{24}} the pub and operate it in the summer, when it {{25}} for tourists.","Murphy, 72, {{26}} been visiting Piel Island for more than 60 years. In the summers, he guides walking tours there."],"grading":{"spelling":"strict","maxWords":1},"items":[{"n":0,"example":true,"accept":["or"]},{"n":18,"accept":["might","may","will","could","now","probably","likely"]},{"n":19,"accept