insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2022-okt-kozep-H2$mtr$, $mtr$2022-okt-kozep$mtr$, $mtr$listening$mtr$, 2, $mtr$choice$mtr$, $mtr$igaz / hamis / a szöveg nem mondja (A/B/C)$mtr$, 9, 9, $mtr${"id":"2022-okt-kozep-H2","number":2,"kind":"choice","layout":"stems","examType":"igaz / hamis / a szöveg nem mondja (A/B/C)","points":9,"instructions":["In this section you will hear a radio interview with a street musician.","Your task will be to decide whether the following statements are true, false or we do not know because the text does not say, and write the appropriate letter in the boxes on the right. Write A if the statement is true, write B if the statement is false, and write C if the text does not say.","First, you will have some time to study the task, and then we will play the whole recording in one piece.","Then, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_22okt_fl.mp3","start":622.88,"end":1191.73,"clip":"hang/k_angol_22okt_fl_H2.mp3"},"items":[{"n":0,"example":true,"stem":"Stefano Rosa is an Italian street musician.","answer":"A"},{"n":10,"stem":"Stefano was satisfied with the money he earned in clubs and cafés."},{"n":11,"stem":"Stefano never plays the same song twice."},{"n":12,"stem":"Stefano’s mother taught music to her own children too."},{"n":13,"stem":"Stefano has been listening to rock music since he was a very small child."},{"n":14,"stem":"Stefano thinks he is a guitarist rather than a singer."},{"n":15,"stem":"Stefano prefers performing with other musicians to playing on his own."},{"n":16,"stem":"Stefano never plays on Sundays."},{"n":17,"stem":"The British girls in Piazza Duomo in Milan were very pretty."},{"n":18,"stem":"A drunk guy in Pisa stole Stefano’s microphone."}],"options":[{"key":"A","text":"TRUE"},{"key":"B","text":"FALSE"},{"key