insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2023-maj-emelt-H1$mtr$, $mtr$2023-maj-emelt$mtr$, $mtr$listening$mtr$, 1, $mtr$choice$mtr$, $mtr$igaz / hamis / a szöveg nem mondja (A/B/C)$mtr$, 8, 9, $mtr${"id":"2023-maj-emelt-H1","number":1,"kind":"choice","layout":"stems","examType":"igaz / hamis / a szöveg nem mondja (A/B/C)","points":8,"instructions":["In this section, you will hear the story of Britain’s most famous talking bird, Sparkie, the budgie.","Your task will be to decide whether the following statements are true, false or we do not know because the text does not say, and write the appropriate letter in the boxes on the right. Write A if the statement is true, write B if the statement is false, and write C if the text does not say.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"e_angol_23maj_fl.mp3","start":0,"end":624.84,"clip":"hang/e_angol_23maj_fl_H1.mp3"},"items":[{"n":0,"example":true,"stem":"The voice of the talking budgie can be heard in a Tyneside recorded archive.","answer":"A"},{"n":1,"stem":"In the photo above we can see Sparkie and his owner when the bird was still alive."},{"n":2,"stem":"The stuffed body of Sparkie can be seen in a museum in Newcastle."},{"n":3,"stem":"Sparkie died at an extremely young age for a budgie."},{"n":4,"stem":"Sparkie was able to ‘say’ eight full nursery rhymes."},{"n":5,"stem":"Geordie is the local dialect used by people in the area."},{"n":6,"stem":"A record with Sparkie’s voice on it reached the top of the charts in 1958."},{"n":7,"stem":"Sparkie’s amazing ability was the result of regular training by his owner."},{"n":8,"stem":"Sparkie is not listed as a record holder in the Guinness Book of Records any longer."}],"options":[{"key":"A","text":"TRUE"},{"key":"B","text":"FALSE"},{"key":"C","text":"THE TEXT DOES NOT SAY"}]}$mtr$::jsonb, $mtr${"file":"e_angol_23maj_fl.mp3","start":0,"end":624.84,"clip":"hang/e_angol_23maj_fl_H1.mp3"}$mtr$::jsonb)
