insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2023-maj-kozep-L3$mtr$, $mtr$2023-maj-kozep$mtr$, $mtr$language$mtr$, 3, $mtr$text$mtr$, $mtr$nyílt cloze (egy szó)$mtr$, 8, 7, $mtr${"id":"2023-maj-kozep-L3","number":3,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":8,"instructions":["You are going to read an article about a new Barbie doll inspired by Dr. Jane Goodall, one of the world's most famous conservationists. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (18-25) after the text.","Use only one word in each gap."],"title":"DR. JANE GOODALL BARBIE DOLL MADE OF RECYCLED PLASTIC","body":["Barbie is going green with a new doll modeled after Dr. Jane Goodall, which will {{0}} released next Tuesday ahead of World Chimpanzee Day. According {{18}} Mattel company, Goodall's Barbie doll is made of 90 percent recycled plastic that otherwise would have ended {{19}} in the ocean.","The 88-year-old researcher tells People Magazine she \"couldn’t be happier\" to see herself {{20}} a Barbie doll, something she long hoped for. Goodall says she wants her Barbie {{21}} \"inspire little girls\" everywhere. \"So many people know about Jane because they learn about me at school,\" she says, \"so I think they'll {{22}} delighted to be given a Barbie Jane.\"","Lisa McKnight, Executive Vice President of Barbie and Dolls at Mattel, said in a statement that the company is \"excited to introduce\" the new doll. \"Kids need more role models {{23}} Dr. Jane Goodall because imagining that they can be anything is just the beginning – seeing it {{24}} a huge difference,\" said McKnight.","\"We hope this collection and our respect for women in science will inspire girls to learn more about green careers, how they can protect the planet, and act {{25}} stories about the environment in their doll play,\" she added."],"grading":{"spelling":"strict"},"items":[{"n":0,"example":true,"accept":["be"]},{"n":18},{"n":19},{"n":20},{"n":21},{"n":22},{"n":23},{"n":24},{"n":25}],"source":"https://people.com/human-interest/dr-jane-goodall-has-her-own-barbie-new-doll-made-of-90-recycled-ocean-bound-plastic/"}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2023-maj-kozep-L3$mtr$, $mtr${"id":"2023-maj-kozep-L3","number":3,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":8,"instructions":["You are going to read an article about a new Barbie doll inspired by Dr. Jane Goodall, one of the world's most famous conservationists. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (18-25) after the text.","Use only one word in each gap."],"title":"DR. JANE GOODALL BARBIE DOLL MADE OF RECYCLED PLASTIC","body":["Barbie is going green with a new doll modeled after Dr. Jane Goodall, which will {{0}} released next Tuesday ahead of World Chimpanzee Day. According {{18}} Mattel company, Goodall's Barbie doll is made of 90 percent recycled plastic that otherwise would have ended {{19}} in the ocean.","The 88-year-old researcher tells People Magazine she \"couldn’t be happier\" to see herself {{20}} a Barbie doll, something she long hoped for. Goodall says she wants her Barbie {{21}} \"inspire little girls\" everywhere. \"So many people know about Jane because they learn about me at school,\" she says, \"so I think they'll {{22}} delighted to be given a Barbie Jane.\"","Lisa McKnight, Executive Vice President of Barbie and Dolls at Mattel, said in a statement that the company is \"excited to introduce\" the new doll. \"Kids need more role models {{23}} Dr. Jane Goodall because imagining that they can be anything is just the beginning – seeing it {{24}} a huge difference,\" said McKnight.","\"We hope this collection and our respect for women in science will inspire girls to learn more about green careers, how they can protect the planet, and act {{25}} stories about the environment in their doll play,\" she added."],"grading":{"spelling":"strict","maxWords":1},"items":[{"n":0,"example":true,"accept":["be"]},{"n":18,"accept":["to"]},{"n":19,"accept":["up"]},{"n":20,"accept":["as","in","become","becoming","inspire"]},{"n":21,"accept":["to"]},{"n":22,"accept":["be","feel"]},{"n":23,"accept":["like","resembling"]},{"n":24,"accept":["makes"]},{"n":25,"accept":["out","in","their"]}],"source":"https://people.com/human-interest/dr-jane-goodall-has-her-own-barbie-new-doll-made-of-90-recycled-ocean-bound-plastic/"}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
