insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2026-okt-emelt-H2$mtr$, $mtr$2026-okt-emelt$mtr$, $mtr$listening$mtr$, 2, $mtr$multi$mtr$, $mtr$kettős választás (A, B vagy mindkettő)$mtr$, 7, 10, $mtr${"id":"2026-okt-emelt-H2","number":2,"kind":"multi","layout":"stems","examType":"kettős választás (A, B vagy mindkettő)","points":7,"instructions":["In this section you will listen to the story of Brenda Lee, a famous pop star of the 60s.","Your task will be to circle the letter(s) of the correct answer(s) in the boxes on the right. Please note that in this task both answers may be correct. However, there is always at least one correct answer. This means you might have to circle one or two letters.","First, you will have some time to study the task, and then we will play the whole recording in one piece.","Then, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"e_angol_26okt_fl.mp3","start":606.5,"end":1192.01,"clip":"hang/e_angol_26okt_fl_H2.mp3"},"items":[{"n":0,"example":true,"stem":"Brenda Lee …","options":[{"key":"A","text":"is an American singer."},{"key":"B","text":"sings rockabilly, pop, country and Christmas songs."}],"answer":["A","B"]},{"n":9,"stem":"Brenda Lee …","options":[{"key":"A","text":"started her career at the age of 5."},{"key":"B","text":"had her first big hit at the age of 20."}]},{"n":10,"stem":"She …","options":[{"key":"A","text":"has sold more than 100 million records in the U.S."},{"key":"B","text":"was named as one of the greatest singers of all time."}]},{"n":11,"stem":"Brenda Lee …","options":[{"key":"A","text":"was born after her father's tragic death."},{"key":"B","text":"began performing to help to support her family. ."}]},{"n":12,"stem":"She …","options":[{"key":"A","text":"had a powerful voice."},{"key":"B","text":"sang very emotionally."}]},{"n":13,"stem":"Brenda …","options":[{"key":"A","text":"earned more money than her mother as early as at the age of 10."},{"key":"B","text":"had two brothers and two sisters."}]},{"n":14,"stem":"What helped Brenda's career was her …","options":[{"key":"A","text":"difficult early life."},{"key":"B","text":"strong will."}]},{"n":15,"stem":"She was called \"Little Miss Dynamite\" because of …","options":[{"key":"A","text":"her clear singing voice."},{"key":"B","text":"the way she performed in live concerts."}]}]}$mtr$::jsonb, $mtr${"file":"e_angol_26okt_fl.mp3","start":606.5,"end":1192.01,"clip":"hang/e_angol_26okt_fl_H2.mp3"}$mtr$::jsonb)
